values ('hsk2-l09', 'hsk2', 'HSK2', 9, '题太多，我没做完', 'Tí tài duō, wǒ méi zuòwán', 'There were too many questions; I didn’t finish all of them', '{"level": "hsk2", "lesson": 9, "book": "HSK2", "title_zh": "题太多，我没做完", "title_pinyin": "Tí tài duō, wǒ méi zuòwán", "title_en": "There were too many questions; I didn’t finish all of them", "textbook": {"ref": {"book": "textbook", "pages": [85, 86, 87, 88, 89, 90, 91, 92]}, "warmup": [{"instruction_zh": "给下面的词语选择对应的图片", "instruction_en": "Match the pictures with the words/phrases.", "items": ["①上班 shàng bān", "②唱歌 chàng gē", "③对错 duì cuò", "④问题 wèntí", "⑤第一 dì yī", "⑥跳舞 tiào wǔ"], "pictures_desc_en": ["A: a young woman singing into a microphone", "B: a group of young people dancing with their arms raised", "C: a woman in a business suit walking along a street carrying a briefcase", "D: a large silver number “1” with the word “first” on it", "E: a man scratching his head, surrounded by question marks", "F: a 3D figure holding a green tick in one hand and a red cross in the other"]}, {"instruction_zh": "给下面的动词加上合适的宾语", "instruction_en": "Add an appropriate object after each of the following verbs.", "items": ["例如：学汉语 xué Hànyǔ", "看________ kàn", "写________ xiě", "吃________ chī", "喝________ hē", "打________ dǎ", "做________ zuò"]}], "pronunciation": [{"title_zh": "是非疑问句的句调", "rows": ["（1）你明天去学校吗？↗ Nǐ míngtiān qù xuéxiào ma?［重读点：去］", "（2）他们都知道这件事吗？↗ Tāmén dōu zhīdào zhè jiàn shì ma?［重读点：知道］", "（3）你都听懂了吗？↗ Nǐ dōu tīngdǒng le ma?［重读点：听懂］"], "notes_zh": ["谓语部分重读，全句末为升调。", "［重读点］为书中汉字下的红点所标示的字；“↗”为书中句末的升调箭头（书中无文字说明）。"], "notes_en": ["Intonation of a Yes-No Question", "The predicate is stressed, and the end of the sentence has a rising intonation."]}], "texts": [{"n": 1, "title_zh": "打电话", "title_en": "On the phone", "kind": "dialogue", "lines": [{"speaker": "A", "zh": "你好！请问张欢在吗？", "pinyin": "Nǐ hǎo! Qǐngwèn Zhāng Huān zài ma?"}, {"speaker": "B", "zh": "你打错了，我们这儿没有叫张欢的。", "pinyin": "Nǐ dǎcuò le, wǒmen zhèr méiyǒu jiào Zhāng Huān de."}, {"speaker": "A", "zh": "对不起。", "pinyin": "Duìbuqǐ."}], "english_version": "A: Hello! May I speak to Zhang Huan?\nB: You’ve got the wrong number. There isn’t a person called Zhang Huan here.\nA: I’m sorry.", "new_words": [{"n": 1, "zh": "错", "pinyin": "cuò", "pos": "adj.", "en": "wrong, incorrect", "text": 1}]}, {"n": 2, "title_zh": "在学校", "title_en": "In the school", "kind": "dialogue", "lines": [{"speaker": "A", "zh": "您从几岁开始学习跳舞？", "pinyin": "Nín cóng jǐ suì kāishǐ xuéxí tiào wǔ?"}, {"speaker": "B", "zh": "我第一次跳舞是在七岁的时候。", "pinyin": "Wǒ dì yī cì tiào wǔ shì zài qī suì de shíhou."}, {"speaker": "A", "zh": "我女儿今年也七岁了。我希望她能跟您学跳舞，可以吗？", "pinyin": "Wǒ nǚ’ér jīnnián yě qī suì le. Wǒ xīwàng tā néng gēn nín xué tiào wǔ, kěyǐ ma?"}, {"speaker": "B", "zh": "没问题，非常欢迎。", "pinyin": "Méi wèntí, fēicháng huānyíng."}], "english_version": "A: At what age did you start to learn dancing?\nB: I was seven when I danced for the first time.\nA: My daughter is seven now. I hope she can learn to dance from you, can she?\nB: Sure. It’s my pleasure.", "new_words": [{"n": 2, "zh": "从", "pinyin": "cóng", "pos": "prep.", "en": "from", "text": 2}, {"n": 3, "zh": "跳舞", "pinyin": "tiào wǔ", "pos": "v.", "en": "to dance", "text": 2}, {"n": 4, "zh": "第一", "pinyin": "dì yī", "pos": "num.", "en": "first", "text": 2}, {"n": 5, "zh": "希望", "pinyin": "xīwàng", "pos": "v.", "en": "to hope, to wish", "text": 2}, {"n": 6, "zh": "问题", "pinyin": "wèntí", "pos": "n.", "en": "question, problem", "text": 2}, {"n": 7, "zh": "欢迎", "pinyin": "huānyíng", "pos": "v.", "en": "to welcome", "star": true, "text": 2}]}, {"n": 3, "title_zh": "在家里", "title_en": "At home", "kind": "dialogue", "lines": [{"speaker": "A", "zh": "你知道吗？大卫找到工作了。", "pinyin": "Nǐ zhīdào ma? Dàwèi zhǎodào gōngzuò le."}, {"speaker": "B", "zh": "太好了！他从什么时候开始上班？", "pinyin": "Tài hǎo le! Tā cóng shénme shíhou kāishǐ shàng bān?"}, {"speaker": "A", "zh": "从下个星期一开始。", "pinyin": "Cóng xià ge xīngqīyī kāishǐ."}, {"speaker": "B", "zh": "这是他的第一个工作，希望他能喜欢。", "pinyin": "Zhè shì tā de dì yī ge gōngzuò, xīwàng tā néng xǐhuan."}], "english_version": "A: You know what? David has got a job.\nB: That’s great! When will he start to work?\nA: Next Monday.\nB: This is his first job. I hope he will like it.", "new_words": [{"n": 8, "zh": "上班", "pinyin": "shàng bān", "pos": "v.", "en": "to work, to do a job", "text": 3}]}, {"n": 4, "title_zh": "在教室", "title_en": "In the classroom", "kind": "dialogue", "lines": [{"speaker": "A", "zh": "昨天的考试怎么样？你都听懂了吗？", "pinyin": "Zuótiān de kǎoshì zěnmeyàng? Nǐ dōu tīngdǒng le ma?"}, {"speaker": "B", "zh": "听懂了。", "pinyin": "Tīngdǒng le."}, {"speaker": "A", "zh": "你都做完了没有？", "pinyin": "Nǐ dōu zuòwán le méiyǒu?"}, {"speaker": "B", "zh": "题太多，我没做完。", "pinyin": "Tí tài duō, wǒ méi zuòwán."}], "english_version": "A: How was the test yesterday? Did you understand everything you heard?\nB: Yes, I did.\nA: Did you finish the test paper?\nB: There were too many questions, I didn’t finish all of them.", "new_words": [{"n": 9, "zh": "懂", "pinyin": "dǒng", "pos": "v.", "en": "to understand, to know", "text": 4}, {"n": 10, "zh": "完", "pinyin": "wán", "pos": "v.", "en": "to finish, to end", "text": 4}, {"n": 11, "zh": "题", "pinyin": "tí", "pos": "n.", "en": "question, problem", "text": 4}]}], "grammar": [{"n": 1, "title_zh": "结果补语", "title_en": "Complements of Result", "explanation_zh": "一些动词或形容词可以放在动词后边，补充、说明动作的结果，它们叫作结果补语。例如：\n在结果补语前加“没（有）”表示否定，句尾不能用“了”。例如：\n表示疑问时，常在句尾加上“（了）没有”。例如：", "explanation_en": "Some verbs or adjectives can be used after a verb to add remarks about the result of an action. They are called complements of result. For example:\n“没（有）” is added before the verb to form the negative form of a complement of result, in which case “了” cannot appear at the end of the sentence. For example:\nTo form a question, “（了）没有” is often added at the end of the sentence. For example:", "structure_rows": ["表1：Subject | Predicate: V + Complement of result | Object", "我 | 看见 | 你的女朋友了。", "我 | 听懂 | 今天的汉语课了。", "我 | 做好 | 饭了。", "大卫 | 找到 | 工作了。", "表2：Subject | Predicate: 没（有）+ V + Complement of result | Object", "我 | 没有看见 | 你的女朋友。", "我 | 没听懂 | 他说的话。", "我 | 没做完 | （考试题）。", "表3：Subject | Predicate: V + Complement of result | Object +（了）没有？", "你 | 看见 | 我的女朋友了没有？", "你 | 听懂 | 他说的话没有？", "你 | （都）做完 | （考试题）了没有？"], "examples": [{"n": 1, "zh": "我看见你的女朋友了。"}, {"n": 2, "zh": "我听懂今天的汉语课了。"}, {"n": 3, "zh": "我做好饭了。"}, {"n": 4, "zh": "大卫找到工作了。"}, {"n": 5, "zh": "我没有看见你的女朋友。", "note_zh": "否定"}, {"n": 6, "zh": "我没听懂他说的话。", "note_zh": "否定"}, {"n": 7, "zh": "我没做完（考试题）。", "note_zh": "否定"}, {"n": 8, "zh": "你看见我的女朋友了没有？", "note_zh": "疑问"}, {"n": 9, "zh": "你听懂他说的话没有？", "note_zh": "疑问"}, {"n": 10, "zh": "你（都）做完（考试题）了没有？", "note_zh": "疑问"}]}, {"n": 2, "title_zh": "介词“从”", "title_en": "The Preposition “从”", "explanation_zh": "介词“从”引出一段时间、一段路程、一件事情的经过或者一个序列的起点，后面常跟“到”一起搭配使用。例如：", "explanation_en": "The preposition “从” introduces the starting point of a period of time, a distance, a process or a sequence, often used together with “到”. For example:", "structure_rows": ["从 | A | 到 | B | ……", "从 | 北京 | 到 | 上海 | 要坐几个小时的飞机？", "从 | 老人 | 到 | 孩子 | 都喜欢吃苹果。", "从 | 下个星期一 | （空） | （空） | 开始（上班）。"], "examples": [{"n": 1, "zh": "从北京到上海要坐几个小时的飞机？"}, {"n": 2, "zh": "从老人到孩子都喜欢吃苹果。"}, {"n": 3, "zh": "从下个星期一开始（上班）。"}]}, {"n": 3, "title_zh": "“第～”表示顺序", "title_en": "“第～” Indicating Order", "explanation_zh": "“第”常被放在数量短语前边，表示顺序。例如：", "explanation_en": "“第” is often used before a numeral-measure-word phrase to indicate order. For example:", "structure_rows": ["第 | 数词（Num） | 量词（M） | 名词（N）", "第 | 一 | 本 | 书", "第 | 二 | 个 | 工作", "第 | 一 | 次 | 跳舞"], "examples": [{"n": 1, "zh": "第一本书"}, {"n": 2, "zh": "第二个工作"}, {"n": 3, "zh": "第一次跳舞"}]}], "exercises": [{"n": 1, "type_zh": "分角色朗读课文", "instruction_zh": "分角色朗读课文", "instruction_en": "Role-play the dialogs.", "items": []}, {"n": 2, "type_zh": "回答问题", "instruction_zh": "根据课文内容回答问题", "instruction_en": "Answer the questions based on the dialogs.", "items": [{"n": 1, "zh": "老师从几岁开始学跳舞？", "pinyin": "Lǎoshī cóng jǐ suì kāishǐ xué tiào wǔ?"}, {"n": 2, "zh": "老师想教她的女儿跳舞吗？", "pinyin": "Lǎoshī xiǎng jiāo tā de nǚ’ér tiào wǔ ma?"}, {"n": 3, "zh": "大卫什么时候去工作？", "pinyin": "Dàwèi shénme shíhou qù gōngzuò?"}, {"n": 4, "zh": "这次考试她都听懂了吗？", "pinyin": "Zhè cì kǎoshì tā dōu tīngdǒng le ma?"}, {"n": 5, "zh": "她考试为什么没做完？", "pinyin": "Tā kǎoshì wèi shénme méi zuòwán?"}]}, {"n": 3, "type_zh": "描述图片", "instruction_zh": "用本课新学的语言点和词语描述图片", "instruction_en": "Describe the pictures using the newly-learned language points and words.", "items": [{"n": 1, "zh": "衣服你________了没有？", "pinyin": "Yīfu nǐ ______ le méiyǒu?", "picture_desc_en": "a woman in a blue top holding a white plastic laundry basket full of clothes"}, {"n": 2, "zh": "作业太多了，我还________。", "pinyin": "Zuòyè tài duō le, wǒ hái ______.", "picture_desc_en": "a little girl resting her head on a desk beside a pile of books and papers"}, {"n": 3, "zh": "从八点到十二点她们都在________。", "pinyin": "Cóng bā diǎn dào shí’èr diǎn tāmen dōu zài ______.", "picture_desc_en": "a row of young women wearing headsets working at computers in an office"}, {"n": 4, "zh": "我第一次________。", "pinyin": "Wǒ dì yī cì ______.", "picture_desc_en": "Tian’anmen gate in Beijing with flower beds and lawn in front"}]}], "characters": {"knowledge_title_zh": "汉字偏旁“土（提土旁）”和“灬”", "knowledge_zh": "偏旁 | 解释 | 例字\n土（提土旁） | 提土旁，多与泥土、土地、建筑物有关。 | 块 kuài、地 dì\n灬 | 四点底，多与火及用火有关系。 | 热 rè、黑 hēi", "knowledge_en": "Chinese Radicals: “土” (as a left-side component) and “灬” — The radical “土” is usually related to soil, land or buildings: 块 kuài lump, piece; 地 dì earth, land, ground. The radical “灬” is usually related to fire or the use of fire: 热 rè hot; 黑 hēi black.", "characters": [{"zh": "块", "pinyin": "kuài", "note_zh": "偏旁“提土旁”例字（lump, piece）"}, {"zh": "地", "pinyin": "dì", "note_zh": "偏旁“提土旁”例字（earth, land, ground）"}, {"zh": "热", "pinyin": "rè", "note_zh": "偏旁“灬（四点底）”例字（hot）"}, {"zh": "黑", "pinyin": "hēi", "note_zh": "偏旁“灬（四点底）”例字（black）"}]}, "application": [{"title_zh": "双人活动", "instruction_zh": "说说你有哪些兴趣爱好，比如唱歌、跳舞、画画儿、打球、游泳等等。你是从什么时候开始学习它们的？", "instruction_en": "Talk about your hobbies and interests, for example, singing, dancing, drawing, playing a ball game, swimming and so on. When did you begin to learn them?", "example_zh": ["表格：爱好 Hobby/Interest | 学习时间 Since When", "唱歌 chàng gē | 从8岁开始学习 cóng bā suì kāishǐ xuéxí", "（另有2行空白）"]}, {"title_zh": "小组活动", "instruction_zh": "3～4人一组，用所给出的结果补语练习说句子，每组请一位同学做记录。", "instruction_en": "Work in groups of 3-4. Practice saying sentences using the given complements of result. Each group chooses a member to take notes.", "example_zh": ["提示词：看见　听见　写完　看完　听懂　写错　买到", "1 | 今天上午你看见大卫了吗？ Jīntiān shàngwǔ nǐ kànjiàn Dàwèi le ma?", "（另有3行空白）"]}]}, "teacher": {"ref": {"book": "teacher", "pages": [66, 67, 68, 69, 70, 71, 72]}, "objectives_zh": ["重点词语：学生能够熟练掌握“错、问题、懂、完、题”的词义和用法", "语言点：学生能够了解并掌握：（1）结果补语（2）介词“从”（3）“第～”表示顺序", "语音：学生能够掌握是非疑问句的句调，并能正确朗读", "汉字：学生能够：（1）熟练认读本课生词（2）了解“土（提土旁）、灬（四点底）”所表示的意思", "功能：学生能够：（1）表达动作的结果（结果补语）（2）引出时间、路程、事情的经过或者一个序列（从……到……）（3）表达顺序（第～）"], "steps": [{"title_zh": "一 复习旧课", "body_zh": "1. 教师出示第8课生词卡片，要求学生快速认读下列生词：\n告诉、事情、服务员、再、让、等、找、贵\n2. 教师带领学生辨析下列字形相近的汉字：\n请____　报____　让____　我____\n情____　服____　诉____　找____\n3. 教师根据第8课重点内容，要求学生快速回答问题：\n考试的时候，教师不让同学们做什么？\n大卫病了，医生让他做什么？\n晚上十点多了，妈妈不让我做什么？\n不忙的时候，你喜欢做什么？\n房间的门打不开了，怎么办？"}, {"title_zh": "二 学习新课 1 热身", "body_zh": "热身1：教师先带领学生根据图片选出正确的词语，然后分组练习。一组学生看图片说出正确的词语；另一组学生看词语，说出图片的编号。\n答案：①C　②A　③F　④E　⑤D　⑥B\n热身2：教师可以先让学生自己进行搭配练习，然后请学生说出自己的答案。教师要鼓励学生说出不同的答案。\n例如：看书　看电视　看电影　……"}, {"title_zh": "2 生词", "body_zh": "（1）生词快速认读及正音\n错、从、跳舞、第一、希望、问题、欢迎、上班、懂、完、题\n• 教师可以用PPT依次快速展示生词；\n• 教师领读，学生齐读；\n• 学生接龙式读一遍，每人读两个。\n（2）重点生词扩展及常用搭配\n错—写错—看错—读错—听错—买错—没写错—写错了没有\n　—对不起，这个汉字我写错了。\n　—他不是大卫，我看错了。\n　—你打错（电话）了，我们这儿没有叫张欢的。\n问题—有问题—没问题—很多问题—什么问题\n　—有问题的同学可以给老师打电话。\n　—你有什么问题？\n　—没问题，非常欢迎。\n懂—听懂—看懂—读懂—没听懂—听懂了没有\n　—昨天的课你听懂了没有？\n　—考试太难了，我看不懂。\n　—昨天的考试怎么样？你都听懂了吗？\n完—看完—写完—读完—做完—没做完—做完了没有\n　—这本书你看完了没有？\n　—老师，汉字我都写完了。\n　—你都做完了没有？\n题—问题—考试题—一道题—很多题\n　—我有一个题还没写完。\n　—我只写完了一道题。\n　—题太多，我没做完。\n练习册相关练习：第79页／一／第一部分，第82-83页／二／第一、二部分"}, {"title_zh": "3 语言点（1）结果补语", "body_zh": "① 语言点解析：\n结果补语主要表示动作或行为的结果。有些结果补语表示对动作的评价、判断。结果补语由形容词和动词充当。当我们需要叙述由一个动作或状态引起某种具体结果时，就应该用结果补语。\n［句型框］动词＋结果补语\n② 语言点导入：\n教师可用对比的方式导入语言点。教师给出句子，请学生说说两个句子的意思是否相同。\nA₁：我吃苹果。　A₂：我吃完苹果了。\nB₁：妈妈做饭。　B₂：妈妈做好饭了。\n③ 语言点操练：\n让学生用肯定式和否定式回答问题。\n今天的语法课你听懂了没有？\n汉字写完了没有？\n今天上午你看见大卫了没有？\n你吃完早饭了没有？\n④ 语言点扩展练习：\n选择正确的词语完成句子。\n看见　做完　听见　看懂　做好\n我没有________你的女朋友。\n妈妈说，饭已经________了，可以吃了。\n这本汉语书你能________吗？\n老师说什么了？我没________。\n考试题太多了，我没________。"}, {"title_zh": "3 语言点（2）介词“从”", "body_zh": "① 语言点解析：\n介词“从”表示起点，后接处所词、方位词、时间词，常与“到、往、向”等搭配使用，表示事情的发展、变化。\n［句型框］从＋处所词／方位词／时间词\n② 语言点导入：\n教师可利用图片进行导入，让学生用“从……到……”说出图片内容。图片可以表示不同的时间，也可以表示不同的地点。\n例如：八点　十点　从八点到十点\n学校　商店　从学校到商店\n十八岁　三十岁　从十八岁到三十岁\n③ 语言点操练：\n请学生大声朗读下列句子，并让学生注意体会句子的意思。\n从八点到十点，我在教室学习。\n从北京到上海，坐飞机要两个多小时。\n从我家到学校不太远。\n从第三课到第五课，我都没听懂。\n④ 语言点扩展练习：\n做课本第71页的双人活动。"}, {"title_zh": "4 课文", "body_zh": "课文1\n（1）让学生听两遍录音并回答下列问题：\n男的想给谁打电话？\n他为什么没有找到要找的人？\n女的是谁？\n（2）教师领读课文两遍，然后让学生分角色朗读课文。\n（3）教师用PPT展示课文提示词，请学生再次通读一遍课文后，根据提示词复述课文。\nA：你好，请问……吗？\nB：你……了，我们这儿……的。\nA：对不起。\n（4）请学生分角色表演此段课文。\n课文2\n（1）让学生听两遍录音并回答下列问题：\nA和B谁会跳舞？\nB第一次跳舞是什么时候？\nA的女儿今年多大了？\nA想让女儿做什么？\n（2）教师带领学生齐读课文两遍，然后请学生分角色朗读课文。\n（3）教师用PPT展示课文提示词，请学生再次通读一遍课文后，根据提示词复述课文。\nA：您……学习跳舞？\nB：我……是在……时候。\nA：我女儿……了。我希望她……，可以吗？\nB：……，非常欢迎。\n课文3\n（1）让学生听两遍录音并回答下列问题：\n大卫找到工作了吗？\n大卫从什么时候开始上班？\n大卫以前有工作吗？\n大卫喜欢他的工作吗？\n（2）教师带领学生齐读课文两遍，然后请学生分角色朗读课文。\n（3）教师根据课文内容，设计若干问题并写在小纸条上。请学生任意抽取其中一张，先大声读出问题，然后根据课文内容回答。例如：\n大卫以前有工作吗？\n大卫什么时候开始上班？\n这个星期大卫要去上班吗？\n下个星期一谁要去上班？\n这是大卫的新工作吗？\n……\n（4）让学生以A的口气将本段课文改为叙述体。\n大卫……，他以前……，这是……，他从……，希望……。\n课文4\n（1）让学生听两遍录音并回答下列问题：\n考试是什么时候？\nB都听懂考试题了吗？\nB做完考试题了没有？为什么？\n（2）教师带领学生齐读课文两遍，然后请学生分角色朗读课文。\n（3）教师用PPT展示课文提示词，请学生再次通读一遍课文后，根据提示词复述课文。\nA：……怎么样？你都……了吗？\nB：……了。\nA：你都……了没有？\nB：题……，我……。"}, {"title_zh": "5 语音", "body_zh": "是非疑问句的句调：\n① 知识点解析\n是非疑问句中的谓语部分要重读，全句末的句调为升调。\n同学们明天都去看电影吗？↗\n你下午有时间和大家一起去喝茶吗？↗\n作业太多了，你有时间写吗？↗\n② 语音练习\n教师可利用课本第70页的例句进行语音练习。教师可先领读句子，使学生掌握是非疑问句的句调规律和方法，然后让学生个别读，教师纠正错误。\n练习册相关练习：第86页／三"}, {"title_zh": "6 汉字", "body_zh": "① 知识点解析：\n偏旁\n土（提土旁）：提土旁，由它构成的汉字一般与泥土、土地和建筑物有关系。\n灬：四点底，由它构成的汉字一般与火及用火有关系。\n② 汉字练习：\n• 教师板书本课偏旁“土（提土旁）、灬”，提示学生注意这两个偏旁的笔画和笔顺，并书写各自的代表汉字，帮助学生识记该偏旁的意义。\n• 补充练习\na. 找出下列含有提土旁和四点底的汉字\n地　热　场　块\n点　珠　打　黑\nb. 拆分下列汉字\n希：____　____　迎：____　____\n题：____　____　班：____　____\nc. 用下列偏旁和部件组合成新汉字\n元　欠　是　又　忄　页　董　宀\n____　____　____　____\n练习册相关练习：第87页／四"}, {"title_zh": "7 补充课堂活动——考试总结", "body_zh": "说说你最近一次的考试情况。\n参考问题：\n1. 考试难不难？\n2. 考试考得怎么样？\n3. 什么地方写错了？\n4. 哪个地方不会做？\n5. 如果考得不好，是什么原因？\n6. 下次考试，你会注意些什么问题？\n……\n参考句型：\n……考得不太好。\n……考得还不错。\n……都听懂了。\n……都不会写。\n……没做完。"}, {"title_zh": "8 本课小结", "body_zh": "• 语言点：结果补语\n　介词“从”\n　“第～”表示顺序\n• 语音：是非疑问句的句调\n• 汉字：偏旁“土（提土旁）、灬”"}, {"title_zh": "附注：建议教学用具", "body_zh": "1. 生词卡片：第8、9课生词卡片\n2. 图片：时间、地点"}], "notes_zh": ["语言点“第～”表示顺序：教学步骤中没有单独的讲解／操练环节（只列在教学目标和本课小结中）。"], "warmup_answers_zh": ["热身1 答案：①C　②A　③F　④E　⑤D　⑥B"], "text_questions": [{"text": 1, "q_zh": "男的想给谁打电话？"}, {"text": 1, "q_zh": "他为什么没有找到要找的人？"}, {"text": 1, "q_zh": "女的是谁？"}, {"text": 2, "q_zh": "A和B谁会跳舞？"}, {"text": 2, "q_zh": "B第一次跳舞是什么时候？"}, {"text": 2, "q_zh": "A的女儿今年多大了？"}, {"text": 2, "q_zh": "A想让女儿做什么？"}, {"text": 3, "q_zh": "大卫找到工作了吗？"}, {"text": 3, "q_zh": "大卫从什么时候开始上班？"}, {"text": 3, "q_zh": "大卫以前有工作吗？"}, {"text": 3, "q_zh": "大卫喜欢他的工作吗？"}, {"text": 4, "q_zh": "考试是什么时候？"}, {"text": 4, "q_zh": "B都听懂考试题了吗？"}, {"text": 4, "q_zh": "B做完考试题了没有？为什么？"}], "summary_zh": "• 语言点：结果补语\n　介词“从”\n　“第～”表示顺序\n• 语音：是非疑问句的句调\n• 汉字：偏旁“土（提土旁）、灬”"}, "workbook": {"ref": {"book": "workbook", "pages": [87, 88, 89, 90, 91, 92, 93, 94, 95]}, "sections": [{"n": "一、听力 第一部分", "type_zh": "听力 第一部分", "instruction_zh": "第1–5题：听句子，判断对错", "instruction_en": "Questions 1-5: Decide whether the pictures are right or wrong based on the sentences you hear.", "items": [{"n": "例1", "zh": "我们家有三个人。", "pinyin": "Wǒmen jiā yǒu sān ge rén.", "transcript_zh": "我们家有三个人。", "picture_desc_en": "a smiling family: a man, a woman and a child outdoors", "answer": "√", "answer_ref": {"book": "workbook", "pages": [87]}}, {"n": "例2", "zh": "我每天坐公共汽车去上班。", "pinyin": "Wǒ měi tiān zuò gōnggòngqìchē qù shàng bān.", "transcript_zh": "我每天坐公共汽车去上班。", "picture_desc_en": "a mountain bicycle", "answer": "×", "answer_ref": {"book": "workbook", "pages": [87]}}, {"n": 1, "zh": "", "transcript_zh": "我第一次跳舞是在七岁的时候。", "picture_desc_en": "a girl in a ballet costume dancing with her arms raised above her head", "answer": "√", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": 2, "zh": "", "transcript_zh": "这是她的第一个工作，她非常喜欢。", "picture_desc_en": "a boy sleeping with his head on a pillow next to a tall stack of papers", "answer": "×", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": 3, "zh": "", "transcript_zh": "今天的汉语课我都听懂了。", "picture_desc_en": "a man helping a boy write on a board", "answer": "√", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": 4, "zh": "", "transcript_zh": "你看，衣服都洗完了。", "picture_desc_en": "a smiling woman in an apron holding a basket of folded clothes", "answer": "√", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": 5, "zh": "", "transcript_zh": "考试的题太多了，我没有做完。", "picture_desc_en": "two smiling boys holding up sheets of paper in front of a blackboard", "answer": "×", "answer_ref": {"book": "teacher", "pages": [132]}}]}, {"n": "一、听力 第二部分", "type_zh": "听力 第二部分", "instruction_zh": "第6–10题：听对话，选择与对话内容一致的图片", "instruction_en": "Questions 6-10: Choose the right picture for each dialogue you hear.", "items": [{"n": "例", "zh": "男：你喜欢什么运动？ Nǐ xǐhuan shénme yùndòng? (What sport do you like?) 女：我最喜欢踢足球。 Wǒ zuì xǐhuan tī zúqiú. (My favorite sport is playing football.)", "options": {"A": "[picture] a tablet and a smartphone lying on papers on a desk", "B": "[picture] a woman teacher adjusting a girl’s arm at a ballet barre", "C": "[picture] a hand with a pencil on a worksheet of multiplication problems", "D": "[picture] a young woman juggling a football on her knee on a field", "E": "[picture] a young man and a girl with a pile of clothes, the girl holding up a white garment", "F": "[picture] people sitting in a corridor waiting while a doctor holds a clipboard"}, "transcript_zh": "男：你喜欢什么运动？ 女：我最喜欢踢足球。", "answer": "D", "answer_ref": {"book": "workbook", "pages": [88]}}, {"n": 6, "zh": "", "options": {"A": "[picture] a tablet and a smartphone lying on papers on a desk", "B": "[picture] a woman teacher adjusting a girl’s arm at a ballet barre", "C": "[picture] a hand with a pencil on a worksheet of multiplication problems", "D": "[picture] a young woman juggling a football on her knee on a field", "E": "[picture] a young man and a girl with a pile of clothes, the girl holding up a white garment", "F": "[picture] people sitting in a corridor waiting while a doctor holds a clipboard"}, "transcript_zh": "男：你从几岁开始学跳舞？ 女：我第一次跳舞是在七岁的时候。", "answer": "B", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": 7, "zh": "", "options": {"A": "[picture] a tablet and a smartphone lying on papers on a desk", "B": "[picture] a woman teacher adjusting a girl’s arm at a ballet barre", "C": "[picture] a hand with a pencil on a worksheet of multiplication problems", "D": "[picture] a young woman juggling a football on her knee on a field", "E": "[picture] a young man and a girl with a pile of clothes, the girl holding up a white garment", "F": "[picture] people sitting in a corridor waiting while a doctor holds a clipboard"}, "transcript_zh": "女：今天的考试怎么样？ 男：不太好，有几个题没有做完。", "answer": "C", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": 8, "zh": "", "options": {"A": "[picture] a tablet and a smartphone lying on papers on a desk", "B": "[picture] a woman teacher adjusting a girl’s arm at a ballet barre", "C": "[picture] a hand with a pencil on a worksheet of multiplication problems", "D": "[picture] a young woman juggling a football on her knee on a field", "E": "[picture] a young man and a girl with a pile of clothes, the girl holding up a white garment", "F": "[picture] people sitting in a corridor waiting while a doctor holds a clipboard"}, "transcript_zh": "男：你看见我的手机了吗？ 女：就在桌子上面，你看见了没有？", "answer": "A", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": 9, "zh": "", "options": {"A": "[picture] a tablet and a smartphone lying on papers on a desk", "B": "[picture] a woman teacher adjusting a girl’s arm at a ballet barre", "C": "[picture] a hand with a pencil on a worksheet of multiplication problems", "D": "[picture] a young woman juggling a football on her knee on a field", "E": "[picture] a young man and a girl with a pile of clothes, the girl holding up a white garment", "F": "[picture] people sitting in a corridor waiting while a doctor holds a clipboard"}, "transcript_zh": "女：这么多的衣服，你一个人能洗完吗？ 男：你现在有时间吗？帮我一起洗吧。", "answer": "E", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": 10, "zh": "", "options": {"A": "[picture] a tablet and a smartphone lying on papers on a desk", "B": "[picture] a woman teacher adjusting a girl’s arm at a ballet barre", "C": "[picture] a hand with a pencil on a worksheet of multiplication problems", "D": "[picture] a young woman juggling a football on her knee on a field", "E": "[picture] a young man and a girl with a pile of clothes, the girl holding up a white garment", "F": "[picture] people sitting in a corridor waiting while a doctor holds a clipboard"}, "transcript_zh": "女：这是我第一次去大医院，医院里人真多啊。 男：是啊。", "answer": "F", "answer_ref": {"book": "teacher", "pages": [132]}}]}, {"n": "一、听力 第三部分", "type_zh": "听力 第三部分", "instruction_zh": "第11–15题：听对话，选择正确答案", "instruction_en": "Questions 11-15: Listen to the dialogues and answer the questions.", "items": [{"n": "例", "zh": "问：小王的杯子是什么颜色的？", "pinyin": "Xiǎo Wáng de bēizi shì shénme yánsè de?", "transcript_zh": "男：小王，这里有几个杯子，哪个是你的？ 女：左边那个红色的是我的。 问：小王的杯子是什么颜色的？", "options": {"A": "红色 hóngsè red", "B": "黑色 hēisè black", "C": "白色 báisè white"}, "answer": "A", "answer_ref": {"book": "workbook", "pages": [89]}}, {"n": 11, "zh": "", "options": {"A": "想找女的 xiǎng zhǎo nǚ de", "B": "想找张欢 xiǎng zhǎo Zhāng Huān", "C": "想去看看张欢 xiǎng qù kànkan Zhāng Huān"}, "transcript_zh": "男：您好，请问张欢在吗？ 女：对不起，我们这儿没有张欢，你打错电话了。 问：男的为什么要打电话？", "answer": "B", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": 12, "zh": "", "options": {"A": "昨天 zuótiān", "B": "今天 jīntiān", "C": "明天 míngtiān"}, "transcript_zh": "男：买到电影票了没有？今天晚上的。 女：买到了，是明天的。今天的都卖完了。 问：他们什么时候去看电影？", "answer": "C", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": 13, "zh": "", "options": {"A": "医院 yīyuàn", "B": "学校 xuéxiào", "C": "公司 gōngsī"}, "transcript_zh": "女：你真的认识去医院的路？是不是走错了？ 男：没错，就在那个公司的前面，学校的后面。 问：他们想去哪儿？", "answer": "A", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": 14, "zh": "", "options": {"A": "没看见 méi kànjiàn", "B": "看见了 kànjiàn le", "C": "没有报纸 méiyǒu bàozhǐ"}, "transcript_zh": "男：看见了没有？报纸就在电视的左边。 女：等一下，你这儿的东西太多了。 问：女的看见报纸了没有？", "answer": "A", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": 15, "zh": "", "options": {"A": "没听懂 méi tīngdǒng", "B": "不会做 bú huì zuò", "C": "没做完 méi zuòwán"}, "transcript_zh": "男：昨天的考试怎么样？都做完了没有？ 女：题太多，我没做完。 问：她昨天的考试怎么样？", "answer": "C", "answer_ref": {"book": "teacher", "pages": [132]}}]}, {"n": "二、阅读 第一部分", "type_zh": "阅读 第一部分", "instruction_zh": "第16–20题：看图片，选择与句子内容一致的图片", "instruction_en": "Questions 16-20: Choose the right picture for each sentence.", "items": [{"n": "例", "zh": "每个星期六，我都去打篮球。", "pinyin": "Měi ge xīngqīliù, wǒ dōu qù dǎ lánqiú.", "options": {"A": "[picture] a young woman jogging outdoors", "B": "[picture] a group of friends raising glasses in a toast at a table", "C": "[picture] double-decker buses on a city road", "D": "[picture] a young man holding a basketball above his head", "E": "[picture] a man and a woman in business suits shaking hands in a meeting room", "F": "[picture] a hand drawing a large tick mark with a pen"}, "answer": "D", "answer_ref": {"book": "workbook", "pages": [90]}}, {"n": 16, "zh": "非常欢迎你来我们公司上班。", "pinyin": "Fēicháng huānyíng nǐ lái wǒmen gōngsī shàng bān.", "options": {"A": "[picture] a young woman jogging outdoors", "B": "[picture] a group of friends raising glasses in a toast at a table", "C": "[picture] double-decker buses on a city road", "D": "[picture] a young man holding a basketball above his head", "E": "[picture] a man and a woman in business suits shaking hands in a meeting room", "F": "[picture] a hand drawing a large tick mark with a pen"}, "answer": "E", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": 17, "zh": "吃完晚饭后，她还要慢跑一个小时。", "pinyin": "Chīwán wǎnfàn hòu, tā hái yào màn pǎo yí ge xiǎoshí.", "options": {"A": "[picture] a young woman jogging outdoors", "B": "[picture] a group of friends raising glasses in a toast at a table", "C": "[picture] double-decker buses on a city road", "D": "[picture] a young man holding a basketball above his head", "E": "[picture] a man and a woman in business suits shaking hands in a meeting room", "F": "[picture] a hand drawing a large tick mark with a pen"}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": 18, "zh": "考试不难，我都做对了。", "pinyin": "Kǎoshì bù nán, wǒ dōu zuòduì le.", "options": {"A": "[picture] a young woman jogging outdoors", "B": "[picture] a group of friends raising glasses in a toast at a table", "C": "[picture] double-decker buses on a city road", "D": "[picture] a young man holding a basketball above his head", "E": "[picture] a man and a woman in business suits shaking hands in a meeting room", "F": "[picture] a hand drawing a large tick mark with a pen"}, "answer": "F", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": 19, "zh": "我希望能和朋友们一起过生日。", "pinyin": "Wǒ xīwàng néng hé péngyoumen yìqǐ guò shēngrì.", "options": {"A": "[picture] a young woman jogging outdoors", "B": "[picture] a group of friends raising glasses in a toast at a table", "C": "[picture] double-decker buses on a city road", "D": "[picture] a young man holding a basketball above his head", "E": "[picture] a man and a woman in business suits shaking hands in a meeting room", "F": "[picture] a hand drawing a large tick mark with a pen"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": 20, "zh": "从我家到学校要坐一个多小时的公共汽车。", "pinyin": "Cóng wǒ jiā dào xuéxiào yào zuò yí ge duō xiǎoshí de gōnggòngqìchē.", "options": {"A": "[picture] a young woman jogging outdoors", "B": "[picture] a group of friends raising glasses in a toast at a table", "C": "[picture] double-decker buses on a city road", "D": "[picture] a young man holding a basketball above his head", "E": "[picture] a man and a woman in business suits shaking hands in a meeting room", "F": "[picture] a hand drawing a large tick mark with a pen"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [132]}}]}, {"n": "二、阅读 第二部分", "type_zh": "阅读 第二部分", "instruction_zh": "第21–25题：选择合适的词语填空", "instruction_en": "Questions 21-25: Choose the proper words to fill in the brackets.", "word_bank": [["A 上班 shàng bān", "B 从 cóng", "C 希望 xīwàng", "D 问题 wèntí", "E 贵 guì", "F 懂 dǒng"]], "items": [{"n": "例", "zh": "这儿的羊肉很好吃，但是也很（________）。", "pinyin": "Zhèr de yángròu hěn hǎochī, dànshì yě hěn ______.", "answer": "E", "answer_ref": {"book": "workbook", "pages": [91]}}, {"n": 21, "zh": "我每天（________）八点到十二点都在公司工作。", "pinyin": "Wǒ měi tiān ______ bā diǎn dào shí’èr diǎn dōu zài gōngsī gōngzuò.", "answer": "B", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": 22, "zh": "我家离公司不太远，所以每天走路去（________）。", "pinyin": "Wǒ jiā lí gōngsī bú tài yuǎn, suǒyǐ měi tiān zǒu lù qù ______.", "answer": "A", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": 23, "zh": "今天的课你都听（________）了没有？", "pinyin": "Jīntiān de kè nǐ dōu tīng ______ le méiyǒu?", "answer": "F", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": 24, "zh": "你有什么（________）都可以问老师。", "pinyin": "Nǐ yǒu shénme ______ dōu kěyǐ wèn lǎoshī.", "answer": "D", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": 25, "zh": "我（________）能找到一个好的工作。", "pinyin": "Wǒ ______ néng zhǎodào yí ge hǎo de gōngzuò.", "answer": "C", "answer_ref": {"book": "teacher", "pages": [132]}}]}, {"n": "二、阅读 第三部分", "type_zh": "阅读 第三部分", "instruction_zh": "第26–30题：判断下列句子的意思是否正确", "instruction_en": "Questions 26-30: Decide whether the inferences are true or false.", "items": [{"n": "例1", "zh": "现在是11点30分，他们已经游了20分钟了。 ★他们11点10分开始游泳。", "pinyin": "Xiànzài shì diǎn fēn, tāmen yǐjīng yóule fēnzhōng le. ★Tāmen diǎn fēn kāishǐ yóuyǒng.", "answer": "√", "answer_ref": {"book": "workbook", "pages": [91]}}, {"n": "例2", "zh": "我会跳舞，但跳得不怎么样。 ★我跳得非常好。", "pinyin": "Wǒ huì tiàowǔ, dàn tiào de bù zěnmeyàng. ★Wǒ tiào de fēicháng hǎo.", "answer": "×", "answer_ref": {"book": "workbook", "pages": [92]}}, {"n": 26, "zh": "我女儿已经六岁了，我希望她能跟您学唱歌。 ★她女儿唱歌非常好。", "pinyin": "Wǒ nǚ’ér yǐjīng liù suì le, wǒ xīwàng tā néng gēn nín xué chànggē. ★Tān nǚ’ér chànggē fēicháng hǎo.", "answer": "×", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": 27, "zh": "这是他的第一个工作，从下个星期开始上班，希望他能喜欢这个工作。 ★他还没有上班呢。", "pinyin": "Zhè shì tā de dì yī ge gōngzuò, cóng xià ge xīngqī kāishǐ shàng bān, xīwàng tā néng xǐhuan zhège gōngzuò. ★Tā hái méiyǒu shàng bān ne.", "answer": "√", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": 28, "zh": "昨天的考试不太难，题很多，我有两个题没有做完。 ★这次考试题很多，很难。", "pinyin": "Zuótiān de kǎoshì bú tài nán, tí hěn duō, wǒ yǒu liǎng ge tí méiyǒu zuòwán. ★Zhè cì kǎoshì tí hěn duō, hěn nán.", "answer": "×", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": 29, "zh": "今天是9月20号，再有三天就是爸爸的生日了。我想送他一个新手机。 ★9月23号是我的生日。", "pinyin": "Jīntiān shì yuè hào, zài yǒu sān tiān jiù shì bàba de shēngrì le. Wǒ xiǎng sòng tā yí ge xīn shǒujī. ★ yuè hào shì wǒ de shēngrì.", "answer": "×", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": 30, "zh": "我的一个朋友正在找房子，希望离公司近一些，这样他每天七点起床就可以了。 ★他的朋友现在每天七点起床。", "pinyin": "Wǒ de yí ge péngyou zhèngzài zhǎo fángzi, xīwàng lí gōngsī jìn yìxiē, zhèyàng tā měi tiān qī diǎn qǐ chuáng jiù kěyǐ le. ★Tā de péngyou xiànzài měi tiān qī diǎn qǐ chuáng.", "answer": "×", "answer_ref": {"book": "teacher", "pages": [132]}}]}, {"n": "二、阅读 第四部分", "type_zh": "阅读 第四部分", "instruction_zh": "第31–35题：选择合适的问答", "instruction_en": "Questions 31-35: Match the sentences to make dialogues.", "items": [{"n": "例", "zh": "他还在教室里学习。 (He is still studying in the classroom.)", "pinyin": "Tā hái zài jiàoshì li xuéxí.", "options": {"A": "就在前面，你还没看见吗？ Jiù zài qiánmian, nǐ hái méi kànjiàn ma?", "B": "非常好，我想明年再来一次。 Fēicháng hǎo, wǒ xiǎng míngnián zài lái yí cì.", "C": "还可以，都做完了。 Hái kěyǐ, dōu zuòwán le.", "D": "这些衣服你一个人能洗完吗？ Zhèxiē yīfu nǐ yí ge rén néng xǐwán ma?", "E": "他在哪儿呢？你看见他了吗？ Tā zài nǎr ne? Nǐ kànjiàn tā le ma?", "F": "等等我，我也想去。 Děngdeng wǒ, wǒ yě xiǎng qù."}, "answer": "E", "answer_ref": {"book": "workbook", "pages": [93]}}, {"n": 31, "zh": "昨天的考试怎么样？题都做完了吗？", "pinyin": "Zuótiān de kǎoshì zěnmeyàng? Tí dōu zuòwán le ma?", "options": {"A": "就在前面，你还没看见吗？ Jiù zài qiánmian, nǐ hái méi kànjiàn ma?", "B": "非常好，我想明年再来一次。 Fēicháng hǎo, wǒ xiǎng míngnián zài lái yí cì.", "C": "还可以，都做完了。 Hái kěyǐ, dōu zuòwán le.", "D": "这些衣服你一个人能洗完吗？ Zhèxiē yīfu nǐ yí ge rén néng xǐwán ma?", "E": "他在哪儿呢？你看见他了吗？ Tā zài nǎr ne? Nǐ kànjiàn tā le ma?", "F": "等等我，我也想去。 Děngdeng wǒ, wǒ yě xiǎng qù."}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": 32, "zh": "没关系，今天洗一些，明天再洗一些。", "pinyin": "Méi guānxi, jīntiān xǐ yìxiē, míngtiān zài xǐ yìxiē.", "options": {"A": "就在前面，你还没看见吗？ Jiù zài qiánmian, nǐ hái méi kànjiàn ma?", "B": "非常好，我想明年再来一次。 Fēicháng hǎo, wǒ xiǎng míngnián zài lái yí cì.", "C": "还可以，都做完了。 Hái kěyǐ, dōu zuòwán le.", "D": "这些衣服你一个人能洗完吗？ Zhèxiē yīfu nǐ yí ge rén néng xǐwán ma?", "E": "他在哪儿呢？你看见他了吗？ Tā zài nǎr ne? Nǐ kànjiàn tā le ma?", "F": "等等我，我也想去。 Děngdeng wǒ, wǒ yě xiǎng qù."}, "answer": "D", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": 33, "zh": "你看见我哥哥了吗？", "pinyin": "Nǐ kànjiàn wǒ gēge le ma?", "options": {"A": "就在前面，你还没看见吗？ Jiù zài qiánmian, nǐ hái méi kànjiàn ma?", "B": "非常好，我想明年再来一次。 Fēicháng hǎo, wǒ xiǎng míngnián zài lái yí cì.", "C": "还可以，都做完了。 Hái kěyǐ, dōu zuòwán le.", "D": "这些衣服你一个人能洗完吗？ Zhèxiē yīfu nǐ yí ge rén néng xǐwán ma?", "E": "他在哪儿呢？你看见他了吗？ Tā zài nǎr ne? Nǐ kànjiàn tā le ma?", "F": "等等我，我也想去。 Děngdeng wǒ, wǒ yě xiǎng qù."}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": 34, "zh": "羊肉吃完了，我再去商店买一些吧。", "pinyin": "Yángròu chīwán le, wǒ zài qù shāngdiàn mǎi yìxiē ba.", "options": {"A": "就在前面，你还没看见吗？ Jiù zài qiánmian, nǐ hái méi kànjiàn ma?", "B": "非常好，我想明年再来一次。 Fēicháng hǎo, wǒ xiǎng míngnián zài lái yí cì.", "C": "还可以，都做完了。 Hái kěyǐ, dōu zuòwán le.", "D": "这些衣服你一个人能洗完吗？ Zhèxiē yīfu nǐ yí ge rén néng xǐwán ma?", "E": "他在哪儿呢？你看见他了吗？ Tā zài nǎr ne? Nǐ kànjiàn tā le ma?", "F": "等等我，我也想去。 Děngdeng wǒ, wǒ yě xiǎng qù."}, "answer": "F", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": 35, "zh": "第一次来北京吧？北京漂亮吗？", "pinyin": "Dì yī cì lái Běijīng ba? Běijīng piàoliang ma?", "options": {"A": "就在前面，你还没看见吗？ Jiù zài qiánmian, nǐ hái méi kànjiàn ma?", "B": "非常好，我想明年再来一次。 Fēicháng hǎo, wǒ xiǎng míngnián zài lái yí cì.", "C": "还可以，都做完了。 Hái kěyǐ, dōu zuòwán le.", "D": "这些衣服你一个人能洗完吗？ Zhèxiē yīfu nǐ yí ge rén néng xǐwán ma?", "E": "他在哪儿呢？你看见他了吗？ Tā zài nǎr ne? Nǐ kànjiàn tā le ma?", "F": "等等我，我也想去。 Děngdeng wǒ, wǒ yě xiǎng qù."}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [132]}}]}, {"n": "三、语音 第一部分", "type_zh": "语音 第一部分 听录音", "instruction_zh": "第1题：听录音，注意句末的升降调", "instruction_en": "Question 1: Listen to the recording and pay attention to the intonation at the end of each sentence.", "items": [{"n": "1-(1)", "zh": "请问张欢在吗？［句末升调↗］", "pinyin": "Qǐngwèn Zhāng Huān zài ma?", "transcript_zh": "请问张欢在吗？"}, {"n": "1-(2)", "zh": "昨天的考试你都听懂了吗？［句末升调↗］", "pinyin": "Zuótiān de kǎoshì nǐ dōu tīngdǒng le ma?", "transcript_zh": "昨天的考试你都听懂了吗？"}, {"n": "1-(3)", "zh": "午饭准备好了吗？［句末升调↗］", "pinyin": "Wǔfàn zhǔnbèi hǎo le ma?", "transcript_zh": "午饭准备好了吗？"}, {"n": "1-(4)", "zh": "大卫找到工作了吗？［句末升调↗］", "pinyin": "Dàwèi zhǎodào gōngzuò le ma?", "transcript_zh": "大卫找到工作了吗？"}]}, {"n": "三、语音 第二部分", "type_zh": "语音 第二部分 跟读", "instruction_zh": "第2题：听录音并跟读下列句子，注意句末的升降调", "instruction_en": "Question 2: Listen to the recording and repeat the following sentences, paying attention to the intonation at the end of each sentence.", "items": [{"n": "2-(1)", "zh": "你喜欢学跳舞吗？［句末升调↗］", "pinyin": "Nǐ xǐhuan xué tiàowǔ ma?", "transcript_zh": "你喜欢学跳舞吗？"}, {"n": "2-(2)", "zh": "你什么时候开始学习跳舞？［句末降调↘］", "pinyin": "Nǐ shénme shíhou kāishǐ xuéxí tiàowǔ?", "transcript_zh": "你什么时候开始学习跳舞？"}, {"n": "2-(3)", "zh": "我七点半就来教室了。［句末降调↘］", "pinyin": "Wǒ qī diǎn bàn jiù lái jiàoshì le.", "transcript_zh": "我七点半就来教室了。"}, {"n": "2-(4)", "zh": "昨天晚上你十点就睡觉了吗？［句末升调↗］", "pinyin": "Zuótiān wǎnshang nǐ shí diǎn jiù shuì jiào le ma?", "transcript_zh": "昨天晚上你十点就睡觉了吗？"}]}, {"n": "四、汉字 第一部分", "type_zh": "汉字 偏旁归类", "instruction_zh": "第1–2题：看汉字，按偏旁归类", "instruction_en": "Questions 1-2: Group the characters with the same radical.", "word_bank": [["A 地", "B 羔", "C 杰", "D 场"], ["E 照", "F 埋", "G 热", "H 块"]], "items": [{"n": 1, "zh": "土（提土旁）：________", "answer": "A D F H", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": 2, "zh": "灬：________", "answer": "B C E G", "answer_ref": {"book": "teacher", "pages": [132]}}]}, {"n": "四、汉字 第二部分", "type_zh": "汉字 猜词义", "instruction_zh": "第3题：看生词和图片，猜出词义", "instruction_en": "Question 3: Guess the meaning of each word based on the new words and pictures.", "word_bank": [["电视", "电话", "电灯", "电冰箱"]], "items": [{"n": "3-电视", "zh": "电视 ________", "options": {"A": "[picture] a flat-screen monitor / television screen on a stand", "B": "[picture] an old-fashioned black rotary telephone", "C": "[picture] a tall double-door refrigerator", "D": "[picture] pendant lamps hanging over a dining table with white chairs"}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": "3-电话", "zh": "电话 ________", "options": {"A": "[picture] a flat-screen monitor / television screen on a stand", "B": "[picture] an old-fashioned black rotary telephone", "C": "[picture] a tall double-door refrigerator", "D": "[picture] pendant lamps hanging over a dining table with white chairs"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": "3-电灯", "zh": "电灯 ________", "options": {"A": "[picture] a flat-screen monitor / television screen on a stand", "B": "[picture] an old-fashioned black rotary telephone", "C": "[picture] a tall double-door refrigerator", "D": "[picture] pendant lamps hanging over a dining table with white chairs"}, "answer": "D", "answer_ref": {"book": "teacher", "pages": [132]}}, {"n": "3-电冰箱", "zh": "电冰箱 ________", "options": {"A": "[picture] a flat-screen monitor / television screen on a stand", "B": "[picture] an old-fashioned black rotary telephone", "C": "[picture] a tall double-door refrigerator", "D": "[picture] pendant lamps hanging over a dining table with white chairs"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [132]}}]}], "answers_ref": {"book": "teacher", "pages": [131, 132]}}, "unclear": ["偏旁 «提土旁» (土-ийн сүүлчийн хэвтээ зурлага 提 болсон хэлбэр) тусдаа Unicode тэмдэгтгүй тул JSON-д «土（提土旁）» гэж бичсэн (сурах бичиг PDF х.91, багшийн ном PDF х.66/71/72, дасгалын ном PDF х.95).", "Сурах бичиг PDF х.90 语音 (2): пиньинь «Tāmén dōu zhīdào…» — «们»-д 2-р хөгийн тэмдэг хэвлэгдсэн (ердийн «Tāmen») — номд байгаагаар.", "Дасгалын ном PDF х.92 阅读 第三部分 26 ★ өгүүлбэрийн пиньинь «Tān nǚ’ér chànggē fēicháng hǎo.» — «她»-ийн пиньинь «Tān» гэж хэвлэгдсэн — номд байгаагаар.", "Дасгалын ном PDF х.91–92 阅读 第三部分 例1 болон 29-ийн пиньинь мөрөнд тоонууд (11, 30, 20, 10; 9, 20, 23) орхигдсон — номд байгаагаар.", "语音 (сурах бичиг PDF х.90): онцлох (重读) хэсгийг ханзын доорх улаан цэгээр, сөрөг/эерэг өнгө аясыг сумаар тэмдэглэсэн; JSON-д «［重读点：…］», «↗» гэж бичсэн. Дасгалын ном PDF х.94 语音-ийн сумыг «［句末升调↗］/［句末降调↘］» гэж оруулсан (энэ тэмдэглэгээ номд текстээр байхгүй). 2-(2) «你什么时候开始学习跳舞？» асуулт боловч доош сумтай (降调) — номд байгаагаар.", "Багшийн ном PDF х.69 课文1 асуулт «女的是谁？» — сурах бичгийн 课文1-т B-гийн хүйс заагдаагүй, зурагт зөвхөн эрэгтэй хүн утсаар ярьж байна — номд байгаагаар.", "Багшийн ном: 语言点 алхамд зөвхөн (1) 结果补语 ба (2) 介词“从” тайлбарлагдсан; «“第～”表示顺序»-д тусдаа алхам байхгүй (教学目标 ба 本课小结-д бий).", "Багшийн ном PDF х.71 汉字 补充练习 a/b/c — хариулт хэвлэгдээгүй. c-ийн 5-р бүрэлдэхүүн «忄» гэж харагдана.", "Сурах бичгийн 热身2 / 练习2 回答问题 / 练习3 描述图片 — хариулт хэвлэгдээгүй (热身2-т багшийн номд зөвхөн «看书　看电视　看电影» жишээ). 热身1-ийн хариулт зөвхөн багшийн номд (PDF х.67).", "注释1 结果补语-ийн гурван хүснэгт, 注释2, 注释3-ын хүснэгтийн сүүлчийн (улаан) мөр нь хичээлийн бичвэрээс авсан жишээ; structure_rows-д хүснэгтээр, examples-д бүтэн өгүүлбэрээр оруулсан. 注释2-ын 3-р мөрөнд «到 | B» нүд хоосон.", "Сурах бичиг PDF х.87 课文4: A-гийн эхний хэлэх үг хоёр өгүүлбэр (昨天的考试怎么样？你都听懂了吗？) — нэг мөрөнд нэгтгэсэн. 课文1/3 «New Word» (ганц тоо) — тус бүр 1 үгтэй.", "Сурах бичиг PDF х.86 生词 7 «欢迎» — «*» тэмдэгтэй (star: true).", "Дасгалын номын 听力 бичвэр (transcript_zh) ба бүх хариулт — багшийн номын хавсралт PDF х.131–132-оос; 例-ийн хариулт дасгалын номд өөрт нь хэвлэгдсэн. 三、语音 хэсэгт хариулт шаардлагагүй (сонсох/давтах). Хавсралтын PDF х.133 нь 10-р хичээлийнх тул ашиглаагүй.", "Дасгалын номын 三、语音 болон 四、汉字 хэсгийн дугаарлалт 1-ээс дахин эхэлдэг; 语音 1–2 асуулт тус бүр 4 өгүүлбэртэй тул n «1-(1)» гэх мэт.", "Аудио файлын нэр мэдэгдэхгүй тул audio талбар орхисон. Номын CD тэмдэг: сурах бичиг 课文1–4 = 09-1…09-4, 语音 09-5; дасгалын ном 听力 09-1, 语音 09-2.", "Энэ хичээлд 课堂用语 (classroom_expressions) / 文化 / 俗语 хэсэг байхгүй.", "Зургийн тайлбарууд (picture_desc_en, pictures_desc_en, options «[picture]») зургаас товч, объектив дүрсэлсэн."], "verified_pages": [66, 67, 68, 69, 70, 71, 72, 85, 86, 87, 88, 89, 90, 91, 92, 93, 94, 95, 131, 132], "schema_version": 1}'::jsonb, 1, 'image_verified')
on conflict (id) do update set book=excluded.book, title_zh=excluded.title_zh, title_pinyin=excluded.title_pinyin, title_en=excluded.title_en, payload=excluded.payload, schema_version=excluded.schema_version, status=excluded.status;
insert into public.hsk_source_lessons (id, level, book, lesson, title_zh, title_pinyin, title_en, payload, schema_version, status)
values ('hsk2-l10', 'hsk2', 'HSK2', 10, '别找了，手机在桌子上呢', 'Bié zhǎo le, shǒujī zài zhuōzi shang ne', 'Stop looking for your cell phone; it’s on the desk', '{"level": "hsk2", "lesson": 10, "book": "HSK2", "title_zh": "别找了，手机在桌子上呢", "title_pinyin": "Bié zhǎo le, shǒujī zài zhuōzi shang ne", "title_en": "Stop looking for your cell phone; it’s on the desk", "textbook": {"ref": {"book": "textbook", "pages": [93, 94, 95, 96, 97, 98, 99, 100]}, "warmup": [{"instruction_zh": "给下面的词语选择对应的图片", "instruction_en": "Match the pictures with the words/phrases.", "items": ["①西瓜 xīguā", "②鸡蛋 jīdàn", "③休息 xiūxi", "④吃药 chī yào", "⑤手机 shǒujī", "⑥准备午饭 zhǔnbèi wǔfàn"], "pictures_desc_en": ["A: three brown eggs", "B: slices of red watermelon", "C: a smiling young woman lying back relaxing on a sofa with her arms behind her head", "D: a row of touchscreen mobile phones in different colours", "E: a woman and a boy preparing food together in a kitchen", "F: a white-haired elderly woman putting a pill into her mouth, holding a blister pack"]}, {"instruction_zh": "给下面的动词加上合适的宾语", "instruction_en": "Add an appropriate object after each of the following verbs.", "items": ["例如：学 汉语 xué Hànyǔ", "听________ tīng", "踢________ tī", "玩儿（to play）________ wánr", "写________ xiě", "下________ xià", "开________ kāi"]}], "pronunciation": [{"title_zh": "特指问句的句调", "rows": ["Zhè shì shéi de bǐ? （1）这是谁的笔？↘［重读点：谁］", "Nǐmen xuéxiào yǒu duōshao xuésheng? （2）你们学校有多少学生？↘［重读点：多少］", "Nǐ zài zhǎo shénme? （3）你在找什么？↘［重读点：什么］"], "notes_zh": ["疑问代词重读，重音之后全句句调逐渐下降。例如：", "［重读点］为书中汉字下的红点所标示的字；“↘”为书中句末的下降箭头（书中无文字说明）。"], "notes_en": ["Intonation of a Specific Question", "The interrogative pronoun is stressed, and the intonation of the part of the sentence following the stress falls gradually. For example:"]}], "texts": [{"n": 1, "title_zh": "在家里", "title_en": "At home", "kind": "dialogue", "lines": [{"speaker": "A", "zh": "不要看电视了，明天上午还有汉语课呢。", "pinyin": "Búyào kàn diànshì le, míngtiān shàngwǔ hái yǒu Hànyǔ kè ne."}, {"speaker": "B", "zh": "看电视对学汉语有帮助。", "pinyin": "Kàn diànshì duì xué Hànyǔ yǒu bāngzhù."}, {"speaker": "A", "zh": "明天的课你都准备好了吗？", "pinyin": "Míngtiān de kè nǐ dōu zhǔnbèi hǎo le ma?"}, {"speaker": "B", "zh": "都准备好了。", "pinyin": "Dōu zhǔnbèi hǎo le."}], "english_version": "A: Stop watching TV. You’ll have a Chinese class tomorrow morning.\nB: Watching TV is good for Chinese learning.\nA: Are you well prepared for the lessons tomorrow?\nB: Yes, I am.", "new_words": [{"n": 1, "zh": "课", "pinyin": "kè", "pos": "n.", "en": "class, lesson", "text": 1}, {"n": 2, "zh": "帮助", "pinyin": "bāngzhù", "pos": "v.", "en": "to help, to assist, to aid", "text": 1}]}, {"n": 2, "title_zh": "在医院", "title_en": "In the hospital", "kind": "dialogue", "lines": [{"speaker": "A", "zh": "别看报纸了，医生说你要多休息。", "pinyin": "Bié kàn bàozhǐ le, yīshēng shuō nǐ yào duō xiūxi."}, {"speaker": "B", "zh": "好，不看了。给我一杯茶吧。", "pinyin": "Hǎo, bú kàn le. Gěi wǒ yì bēi chá ba."}, {"speaker": "A", "zh": "医生说吃药后两个小时不要喝茶。", "pinyin": "Yīshēng shuō chī yào hòu liǎng ge xiǎoshí búyào hē chá."}, {"speaker": "B", "zh": "医生还说什么了？", "pinyin": "Yīshēng hái shuō shénme le?"}, {"speaker": "A", "zh": "医生让你听我的。", "pinyin": "Yīshēng ràng nǐ tīng wǒ de."}], "english_version": "A: Stop reading the newspaper. The doctor said you need more rest.\nB: OK. Give me a cup of tea.\nA: The doctor said you shouldn’t drink tea during the first two hours after you’ve taken the medicine.\nB: What else did the doctor say?\nA: The doctor said you should listen to me.", "new_words": [{"n": 3, "zh": "别", "pinyin": "bié", "pos": "adv.", "en": "don’t", "text": 2}]}, {"n": 3, "title_zh": "在家里", "title_en": "At home", "kind": "dialogue", "lines": [{"speaker": "A", "zh": "你怎么买了这么多东西啊？", "pinyin": "Nǐ zěnme mǎile zhème duō dōngxi a?"}, {"speaker": "B", "zh": "哥哥今天中午回来吃饭。", "pinyin": "Gēge jīntiān zhōngwǔ huílai chī fàn."}, {"speaker": "A", "zh": "我看看买什么了。羊肉、鸡蛋、面条、西瓜……真不少！妈妈呢？", "pinyin": "Wǒ kànkan mǎi shénme le. Yángròu, jīdàn, miàntiáo, xīguā…… zhēn bù shǎo! Māma ne?"}, {"speaker": "B", "zh": "正在准备午饭呢！", "pinyin": "Zhèngzài zhǔnbèi wǔfàn ne!"}], "english_version": "A: Why did you buy so many things?\nB: Our elder brother will come back to have lunch.\nA: Let me see. Mutton, eggs, noodles, watermelon…That’s a lot! Where is Mom?\nB: She is preparing lunch!", "new_words": [{"n": 4, "zh": "哥哥", "pinyin": "gēge", "pos": "n.", "en": "elder brother", "text": 3}, {"n": 5, "zh": "鸡蛋", "pinyin": "jīdàn", "pos": "n.", "en": "(hen’s) egg", "text": 3}, {"n": 6, "zh": "西瓜", "pinyin": "xīguā", "pos": "n.", "en": "watermelon", "text": 3}, {"n": 7, "zh": "正在", "pinyin": "zhèngzài", "pos": "adv.", "en": "in the process of", "text": 3}]}, {"n": 4, "title_zh": "在家里", "title_en": "At home", "kind": "dialogue", "lines": [{"speaker": "A", "zh": "你在找什么？", "pinyin": "Nǐ zài zhǎo shénme?"}, {"speaker": "B", "zh": "你看见我的手机了吗？白色的。", "pinyin": "Nǐ kànjiàn wǒ de shǒujī le ma? Báisè de."}, {"speaker": "A", "zh": "别找了，手机在桌子上呢，电脑旁边。", "pinyin": "Bié zhǎo le, shǒujī zài zhuōzi shang ne, diànnǎo pángbiān."}, {"speaker": "B", "zh": "你看见我的衣服了吗？红色的那件。", "pinyin": "Nǐ kànjiàn wǒ de yīfu le ma? Hóngsè de nà jiàn."}, {"speaker": "A", "zh": "那件衣服我帮你洗了，在外边呢。", "pinyin": "Nà jiàn yīfu wǒ bāng nǐ xǐ le, zài wàibian ne."}], "english_version": "A: What are you looking for?\nB: Have you seen my cell phone? It’s white.\nA: Stop looking for your cell phone. It’s on the desk, beside the computer.\nB: Have you seen my garment? The red one.\nA: I have washed it for you. It’s hung outside.", "new_words": [{"n": 8, "zh": "手机", "pinyin": "shǒujī", "pos": "n.", "en": "cell phone", "text": 4}, {"n": 9, "zh": "洗", "pinyin": "xǐ", "pos": "v.", "en": "to wash, to bathe", "text": 4}]}], "grammar": [{"n": 1, "title_zh": "祈使句：不要……了；别……了", "title_en": "The Imperative Sentence “不要……了/别……了”", "explanation_zh": "表示劝阻或禁止做某件事情。例如：", "explanation_en": "This sentence structure is used to dissuade or forbid somebody from doing something. For example:", "structure_rows": ["不要 | V（＋O） | 了", "不要 | 玩手机 | 了。", "不要 | 做饭 | 了。", "不要 | 看电视 | 了。", "别 | V（＋O） | 了", "别 | 睡觉 | 了。", "别 | 看书 | 了。", "别 | 看报纸 | 了。"], "examples": [{"n": 1, "zh": "不要玩手机了。"}, {"n": 2, "zh": "不要做饭了。"}, {"n": 3, "zh": "不要看电视了。"}, {"n": 4, "zh": "别睡觉了。"}, {"n": 5, "zh": "别看书了。"}, {"n": 6, "zh": "别看报纸了。"}]}, {"n": 2, "title_zh": "介词“对”", "title_en": "The Preposition “对”", "explanation_zh": "介词“对”可以表示人和人、人和事物、事物和事物之间的对待关系。例如：", "explanation_en": "The preposition “对” can indicate a subject-target relation between people or things. For example:", "structure_rows": ["Subject | Predicate: 对 | O | V/Adj", "跑步 | 对 | 身体 | 很好。", "老师 | 对 | 学生 | 非常好。", "看电视 | 对 | 学汉语 | 有帮助。"], "examples": [{"n": 1, "zh": "跑步对身体很好。"}, {"n": 2, "zh": "老师对学生非常好。"}, {"n": 3, "zh": "看电视对学汉语有帮助。"}]}], "exercises": [{"n": 1, "type_zh": "分角色朗读课文", "instruction_zh": "分角色朗读课文", "instruction_en": "Role-play the dialogs.", "items": []}, {"n": 2, "type_zh": "回答问题", "instruction_zh": "根据课文内容回答问题", "instruction_en": "Answer the questions based on the dialogs.", "items": [{"n": 1, "zh": "孩子们正在做什么？", "pinyin": "Háizimen zhèngzài zuò shénme?"}, {"n": 2, "zh": "妈妈为什么不让他们看电视了？", "pinyin": "Māma wèi shénme bú ràng tāmen kàn diànshì le?"}, {"n": 3, "zh": "吃药以后可以喝茶吗？", "pinyin": "Chī yào yǐhòu kěyǐ hē chá ma?"}, {"n": 4, "zh": "他今天都买了什么东西？为什么要买这么多？", "pinyin": "Tā jīntiān dōu mǎile shénme dōngxi? Wèi shénme yào mǎi zhème duō?"}, {"n": 5, "zh": "你知道男的正在找什么吗？", "pinyin": "Nǐ zhīdào nán de zhèngzài zhǎo shénme ma?"}]}, {"n": 3, "type_zh": "描述图片", "instruction_zh": "用本课新学的语言点和词语描述图片", "instruction_en": "Describe the pictures using the newly-learned language points and words.", "items": [{"n": 1, "zh": "你的病已经好了，别________了。", "pinyin": "Nǐ de bìng yǐjīng hǎo le, bié ______ le.", "picture_desc_en": "a man in a white coat talking with a white-haired elderly woman in red in a pharmacy, medicine shelves behind them"}, {"n": 2, "zh": "别________了，明天还要上学呢。", "pinyin": "Bié ______ le, míngtiān hái yào shàng xué ne.", "picture_desc_en": "a young man sitting cross-legged on a bed, typing on a laptop"}, {"n": 3, "zh": "________对身体很好。", "pinyin": "______ duì shēntǐ hěn hǎo.", "picture_desc_en": "a smiling woman in a yellow swimming cap holding the ladder at the edge of a swimming pool"}, {"n": 4, "zh": "________对学习英语有帮助。", "pinyin": "______ duì xuéxí Yīngyǔ yǒu bāngzhù.", "picture_desc_en": "a young woman reading a newspaper"}]}], "characters": {"knowledge_title_zh": "汉字偏旁“走”和“穴”", "knowledge_zh": "偏旁 | 解释 | 例字\n走 | 走字旁，一般与奔跑和行走有关。 | 超 chāo、起 qǐ\n穴 | 穴字头，一般与孔洞、房屋有关。 | 空 kōng、穿 chuān", "knowledge_en": "Chinese Radicals: “走” and “穴” — The radical “走” is usually related to the act of running or walking: 超 chāo to exceed, to surpass; 起 qǐ to get up, to rise. The radical “穴” is usually related to holes, caves or houses: 空 kōng empty; 穿 chuān to pierce through, to penetrate.", "characters": [{"zh": "超", "pinyin": "chāo", "note_zh": "偏旁“走（走字旁）”例字（to exceed, to surpass）"}, {"zh": "起", "pinyin": "qǐ", "note_zh": "偏旁“走（走字旁）”例字（to get up, to rise）"}, {"zh": "空", "pinyin": "kōng", "note_zh": "偏旁“穴（穴字头）”例字（empty）"}, {"zh": "穿", "pinyin": "chuān", "note_zh": "偏旁“穴（穴字头）”例字（to pierce through, to penetrate）"}]}, "application": [{"title_zh": "双人活动", "instruction_zh": "两人一组，选择下列词语，用“不要……了”“别……了”练习说句子。", "instruction_en": "Work in pairs. Choose appropriate words and use “不要……了” “别……了” to make sentences.", "example_zh": ["例如：不要玩儿（to play）电脑了。 Búyào wánr diànnǎo le.", "词语框（左列）：看 kàn、吃 chī、玩 wán、买 mǎi、喝 hē", "词语框（右列）：咖啡 kāfēi、手机 shǒujī、新衣服 xīn yīfu、药 yào、电视 diànshì"]}, {"title_zh": "小组活动", "instruction_zh": "3～4人一组，用介词“对”练习说句子，每组请一位同学做记录。", "instruction_en": "Work in groups of 3-4. Practice saying sentences with the preposition “对”. Each group chooses a member to take notes.", "example_zh": ["表格：（序号） | A | 对 | B | 很好/不好", "1 | 看电视 Kàn diànshì | 对 duì | 眼睛 yǎnjing | 不好。 bù hǎo.", "（另有3行空白）"]}], "culture": {"title_zh": "中国的茶文化", "body_zh": "中国人喜欢喝茶。茶不仅好喝，而且对身体有好处。它可以提神醒脑、抵抗衰老、预防疾病，还有减肥的功效。中国茶有很多种，比如，红茶、绿茶、青茶、花茶等。随着季节的不同，人们会选择喝不同的茶。一般来说，春天的时候喝花茶，夏天的时候喝绿茶，秋天的时候喝青茶，冬天的时候喝红茶。\n如果你有机会来中国，一定要体验一下中国的茶文化。", "body_en": "Chinese Tea Culture\nChinese people love drinking tea. Tea is both delicious and beneficial to our health. It can help people refresh themselves, defer aging, prevent diseases and even lose weight. There are a variety of Chinese tea, such as black tea, non-fermented green tea, half-fermented green tea and scented tea. People drink different kinds of tea in different seasons. Generally speaking, people drink scented tea in spring, non-fermented green tea in summer, half-fermented green tea in autumn, and black tea in winter.\nIf you have an opportunity to visit China some day, you should have a taste of the Chinese tea culture."}}, "teacher": {"ref": {"book": "teacher", "pages": [73, 74, 75, 76, 77, 78, 79]}, "objectives_zh": ["重点词语：学生能够熟练掌握“课、帮助、正在、洗”的词义和用法", "语言点：学生能够了解并掌握：（1）祈使句“不要……了”“别……了”（2）介词“对”", "语音：学生能够掌握特指问句的句调，并能正确朗读", "汉字：学生能够：（1）熟练认读本课生词（2）了解“走（走字旁）、穴（穴字头）”所表示的意思", "功能：学生能够：（1）表达劝阻或禁止做某件事情（不要……了，别……了）（2）引出人和人、人和事物、事物和事物间的对待关系（……对……）"], "steps": [{"title_zh": "一 复习旧课", "body_zh": "1. 教师出示第9课生词卡片，要求学生快速认读下列生词：\n跳舞、第一、希望、问题、欢迎、上班、听懂、做完\n2. 教师带领学生辨析下列字形相近的汉字：\n弟____　问____　听____　完____\n第____　间____　诉____　字____\n3. 教师根据第9课重点内容，要求学生用肯定式和否定式回答下列问题：\n妈妈做好饭了没有？\n大卫找到工作了没有？\n你看见我的汉语书了没有？\n考试题你都做完了吗？\n今天的作业你都做完了吗？"}, {"title_zh": "二 学习新课 1 热身", "body_zh": "热身1：教师先带领学生根据图片选出正确的词语，然后分组练习。一组学生看图片说出正确的词语；另一组学生看词语，说出图片的编号。\n答案：①B　②A　③C　④F　⑤D　⑥E\n热身2：教师可以先让学生自己进行搭配练习，然后请学生说出自己的答案。教师要鼓励学生说出不同的答案。\n例如：听课文　听音乐　听歌　……"}, {"title_zh": "2 生词", "body_zh": "（1）生词快速认读及正音\n课、帮助、别、哥哥、鸡蛋、西瓜、正在、手机、洗\n• 教师可以用PPT依次快速展示生词；\n• 教师领读，学生齐读；\n• 学生接龙式读一遍，每人读两个。\n（2）重点生词扩展及常用搭配\n课—上课—下课—有课—汉语课—明天的课\n　—我明天上午有课。\n　—你去上汉语课吗？\n　—明天的课你都准备好了吗？\n帮助—帮助老师—帮助同学—有帮助—对学习有帮助\n　—他常常帮助同学。\n　—你能帮助一下大卫吗？\n　—看电视对学汉语有帮助。\n正在—正在学习—正在看书—正在写汉字—正在听音乐\n　—大卫正在做什么呢？\n　—他正在写汉字呢。\n　—妈妈正在准备午饭呢。\n洗—洗衣服—洗手—洗头—洗完了—洗好了\n　—你每天洗衣服吗？\n　—水果都洗好了。\n　—那件衣服我帮你洗了。\n练习册相关练习：第88页／一／第一部分，第91-92页／二／第一、二部分"}, {"title_zh": "3 语言点（1）祈使句“不要……了”“别……了”", "body_zh": "① 语言点解析：\n祈使句是表示命令、请求的句子，包括命令、请求别人做什么或不要做什么。否定的祈使句表示不准、劝阻别人做什么。常由“不要、别、不用”加上其他谓语成分构成。\n［句型框］不要／别／不用＋动词＋了\n② 语言点导入：\n教师可以通过创设情境的方式导入语言点。\n教师：上课的时候，很多同学在说话。老师应该怎么说？\n学生：别说话了。／不要说话了。\n教师：孩子已经吃得很多了，还要吃。妈妈说什么？\n学生：别吃了。／不要吃了。\n③ 语言点操练：\n请学生大声朗读下列句子。\n别说话了。　　不要说话了。\n别打电话了。　不要打电话了。\n别玩儿电脑了。不要玩儿电脑了。\n别出去吃了。　不要出去吃了。\n④ 语言点扩展练习：\n教师带领学生做课本第78页的双人活动。"}, {"title_zh": "3 语言点（2）介词“对”", "body_zh": "① 语言点解析：\n介词“对”用来指示动作的对象，可以用在助动词、副词的前或后，也可用在主语前，意思相同。\n［句型框］A对B好／不好\n② 语言点导入：\n教师可以通过创设情境的方式导入语言点。\n教师：长时间玩儿手机好不好？对什么不好？\n学生：长时间玩儿手机对眼睛不好。\n教师：天天跑步好不好？对什么好？\n学生：天天跑步对身体很好。\n③ 语言点操练：\n教师带领学生先完成下列句子，然后让学生大声朗读已完成的句子。\n________对身体很好。\n________对身体不好。\n________对学习汉语有帮助。\n多喝咖啡对________不好。\n④ 语言点扩展练习：\n• 教师带领学生做课本第79页的小组活动。\n• 教师可以在网上搜索一段医生给病人看病的视频，删掉音频，让学生根据视频的内容，设计一段医生和病人的对话。"}, {"title_zh": "4 课文", "body_zh": "课文1\n（1）让学生听两遍录音并回答下列问题：\n妈妈为什么不让孩子看电视？\n孩子为什么看电视？\n明天的汉语课是什么时候？\n孩子准备好明天的课了吗？\n（2）教师领读课文两遍，然后让学生分角色朗读课文。\n（3）教师用PPT展示课文提示词，请学生再次通读一遍课文后，根据提示词复述课文。\nA：不要……了，明天上午……呢。\nB：看……对……有帮助。\nA：明天的课你都……了吗？\nB：都……了。\n（4）让学生以孩子的语气将本段课文的主要内容改为叙述体。\n妈妈不让我……，因为……，可是我觉得……。\n课文2\n（1）让学生听两遍录音并回答下列问题：\n女的为什么不让男的看报纸？\n男的想做什么？\n男的为什么不能喝茶？\n医生都说什么了？\n（2）教师带领学生齐读课文两遍，然后请学生分角色朗读课文。\n（3）教师用PPT展示课文提示词，请学生再次通读一遍课文后，根据提示词复述课文。\nA：别……了，医生说……。\nB：好，不看了。给我……吧。\nA：医生说……不要喝茶。\nB：医生还……了？\nA：医生……。\n课文3\n（1）让学生听两遍录音并回答下列问题：\n男的为什么买这么多东西？\n谁今天中午回来吃饭？\n男的今天都买了什么东西？\n妈妈做什么呢？\n（2）教师带领学生齐读课文两遍，然后请学生分角色朗读课文。\n（3）教师用PPT展示课文提示词，请学生分角色表演课文。\nA：你怎么……啊？\nB：哥哥今天中午……。\nA：我看看……。……真不少！妈妈呢？\nB：正在……。\n（4）让学生以男的的口气将本段课文改为叙述体。\n我买了……，因为……，有……，妈妈……。\n课文4\n（1）让学生听两遍录音并回答下列问题：\n男的在找什么？\n男的的手机是什么颜色的？\n电脑在哪儿？\n手机在电脑旁边吗？\n男的的衣服为什么在外边？\n（2）教师带领学生齐读课文两遍，然后请学生分角色朗读课文。\n（3）教师让学生根据课文内容快速完成下列句子，并大声读出来。\n你看见________了吗？白色的。\n你看见________了吗？红色的那件。\n手机在________。\n电脑在________。\n衣服在________。"}, {"title_zh": "5 语音", "body_zh": "特指问句的句调：\n① 知识点解析\n特指问句中的疑问代词要重读，全句的句调逐渐下降。例如：\n你每天和谁一起去学校？↘\n看中文报纸对学习汉语有什么帮助？↘\n妈妈为什么不让孩子看电视了？↘\n② 语音练习\n教师可利用课本第77页的例句进行练习。教师可先领读句子，使学生掌握特指问句句调的特点，然后让学生个别读，教师纠正错误。\n练习册相关练习：第95页／三"}, {"title_zh": "6 汉字", "body_zh": "① 知识点解析：\n偏旁\n走：走字旁，由它构成的汉字一般与奔跑和行走有关系。\n穴：穴字头，由它构成的汉字一般与孔洞、房屋有关系。\n② 汉字练习：\n• 教师板书本课偏旁“走、穴”，提示学生注意这两个偏旁的笔画和笔顺，并书写各自的代表汉字，帮助学生识记该偏旁的意义。\n• 补充练习\na. 找出下列含有走字旁和穴字头的汉字\n空　超　实　建\n定　容　起　穿\nb. 拆分下列汉字\n别：____　____　蛋：____　____\n怎：____　____　边：____　____\nc. 用下列偏旁和部件组合成新汉字\n又　另　且　刂　先　力　鸟　冫\n____　____　____　____\n练习册相关练习：第96页／四"}, {"title_zh": "7 补充课堂活动——要听医生的话", "body_zh": "根据第二段课文，请学生设计一个小话剧。要求有医生、病人和病人家属。可以选择下面的提示词语设计话剧内容。\n不要看报纸　不要看电视　不要喝咖啡　不要喝茶\n多休息　多喝水　多睡觉　多运动\n给我一杯　给我一张\n吃药以后　吃药以前\n医生说……　医生告诉……\n医生让你……"}, {"title_zh": "8 本课小结", "body_zh": "• 语言点：祈使句“不要……了”“别……了”\n　介词“对”\n• 语音：特指问句的句调\n• 汉字：偏旁“走、穴”"}, {"title_zh": "附注：建议教学用具", "body_zh": "1. 生词卡片：第9、10课生词卡片\n2. 视频：医生给病人看病"}, {"title_zh": "文化：中国的茶文化", "body_zh": "1 文化点解析\n① 茶是中国人生活中不可缺少的。茶不仅好喝，而且对身体有好处。\n② 茶的作用：提神醒脑、抵抗衰老、预防疾病、减肥。\n③ 茶的种类很多，比如：红茶、绿茶、青茶、花茶等。\n④ 人们常常根据季节选择不同的茶，一般来说，春天饮花茶，夏天饮绿茶，秋天饮青茶，冬天饮红茶。\n2 文化点参考处理方式\n• 教师可以给出一些图片，介绍不同种类的茶，说说它们有什么特点和不同。\n• 中国茶的冲泡方法是很有讲究的，教师可以通过视频或者亲自给学生演示泡茶的方法。\n• 教师可以准备几种茶叶，让学生品尝一下。"}], "notes_zh": [], "warmup_answers_zh": ["热身1 答案：①B　②A　③C　④F　⑤D　⑥E", "热身2 例如：听课文　听音乐　听歌　……"], "text_questions": [{"text": 1, "q_zh": "妈妈为什么不让孩子看电视？"}, {"text": 1, "q_zh": "孩子为什么看电视？"}, {"text": 1, "q_zh": "明天的汉语课是什么时候？"}, {"text": 1, "q_zh": "孩子准备好明天的课了吗？"}, {"text": 2, "q_zh": "女的为什么不让男的看报纸？"}, {"text": 2, "q_zh": "男的想做什么？"}, {"text": 2, "q_zh": "男的为什么不能喝茶？"}, {"text": 2, "q_zh": "医生都说什么了？"}, {"text": 3, "q_zh": "男的为什么买这么多东西？"}, {"text": 3, "q_zh": "谁今天中午回来吃饭？"}, {"text": 3, "q_zh": "男的今天都买了什么东西？"}, {"text": 3, "q_zh": "妈妈做什么呢？"}, {"text": 4, "q_zh": "男的在找什么？"}, {"text": 4, "q_zh": "男的的手机是什么颜色的？"}, {"text": 4, "q_zh": "电脑在哪儿？"}, {"text": 4, "q_zh": "手机在电脑旁边吗？"}, {"text": 4, "q_zh": "男的的衣服为什么在外边？"}], "summary_zh": "• 语言点：祈使句“不要……了”“别……了”\n　介词“对”\n• 语音：特指问句的句调\n• 汉字：偏旁“走、穴”"}, "workbook": {"ref": {"book": "workbook", "pages": [96, 97, 98, 99, 100, 101, 102, 103, 104]}, "sections": [{"n": "一、听力 第一部分", "type_zh": "听力 第一部分", "instruction_zh": "第1–5题：听句子，判断对错", "instruction_en": "Questions 1-5: Decide whether the pictures are right or wrong based on the sentences you hear.", "items": [{"n": "例1", "zh": "我们家有三个人。", "pinyin": "Wǒmen jiā yǒu sān ge rén.", "transcript_zh": "我们家有三个人。", "picture_desc_en": "a smiling family outdoors: a man carrying a child on his shoulders and a woman", "answer": "√", "answer_ref": {"book": "workbook", "pages": [96]}}, {"n": "例2", "zh": "我每天坐公共汽车去上班。", "pinyin": "Wǒ měi tiān zuò gōnggòngqìchē qù shàng bān.", "transcript_zh": "我每天坐公共汽车去上班。", "picture_desc_en": "a mountain bicycle", "answer": "×", "answer_ref": {"book": "workbook", "pages": [96]}}, {"n": 1, "zh": "", "transcript_zh": "看电影对学习汉语有帮助。", "picture_desc_en": "a cinema: rows of seated audience facing a large screen", "answer": "√", "answer_ref": {"book": "teacher", "pages": [134]}}, {"n": 2, "zh": "", "transcript_zh": "妈妈，别走了，我们休息休息吧。", "picture_desc_en": "a little girl hugging the leg of an adult woman who is standing", "answer": "√", "answer_ref": {"book": "teacher", "pages": [134]}}, {"n": 3, "zh": "", "transcript_zh": "妈妈正在准备午饭呢。", "picture_desc_en": "a man and a small child at a kitchen sink, washing something", "answer": "×", "answer_ref": {"book": "teacher", "pages": [134]}}, {"n": 4, "zh": "", "transcript_zh": "张老师的手机在桌子上呢。", "picture_desc_en": "a tablet computer on a desk, with a cup of coffee, glasses, a pen and papers", "answer": "×", "answer_ref": {"book": "teacher", "pages": [134]}}, {"n": 5, "zh": "", "transcript_zh": "你的衣服我帮你洗了。", "picture_desc_en": "hands putting laundry into a front-loading washing machine", "answer": "√", "answer_ref": {"book": "teacher", "pages": [134]}}]}, {"n": "一、听力 第二部分", "type_zh": "听力 第二部分", "instruction_zh": "第6–10题：听对话，选择与对话内容一致的图片", "instruction_en": "Questions 6-10: Choose the right picture for each dialogue you hear.", "items": [{"n": "例", "zh": "男：你喜欢什么运动？ Nǐ xǐhuan shénme yùndòng? (What sport do you like?) 女：我最喜欢踢足球。 Wǒ zuì xǐhuan tī zúqiú. (My favorite sport is playing football.)", "transcript_zh": "男：你喜欢什么运动？ 女：我最喜欢踢足球。", "options": {"A": "[picture] a doctor with a stethoscope writing on a paper at a desk, a patient''s hands across the desk", "B": "[picture] a woman with a shopping cart reaching for goods on supermarket shelves", "C": "[picture] a schoolgirl and a schoolboy in uniforms sitting together with books, smiling", "D": "[picture] a young woman juggling a football on her knee on a field", "E": "[picture] a little girl seen from behind, sitting and watching a television", "F": "[picture] clothes hanging on a washing line outdoors"}, "answer": "D", "answer_ref": {"book": "workbook", "pages": [97]}}, {"n": 6, "zh": "", "options": {"A": "[picture] a doctor with a stethoscope writing on a paper at a desk, a patient''s hands across the desk", "B": "[picture] a woman with a shopping cart reaching for goods on supermarket shelves", "C": "[picture] a schoolgirl and a schoolboy in uniforms sitting together with books, smiling", "D": "[picture] a young woman juggling a football on her knee on a field", "E": "[picture] a little girl seen from behind, sitting and watching a television", "F": "[picture] clothes hanging on a washing line outdoors"}, "transcript_zh": "男：别看电视了，长时间看电视对眼睛不好。 女：好的，我去睡觉了。", "answer": "E", "answer_ref": {"book": "teacher", "pages": [134]}}, {"n": 7, "zh": "", "options": {"A": "[picture] a doctor with a stethoscope writing on a paper at a desk, a patient''s hands across the desk", "B": "[picture] a woman with a shopping cart reaching for goods on supermarket shelves", "C": "[picture] a schoolgirl and a schoolboy in uniforms sitting together with books, smiling", "D": "[picture] a young woman juggling a football on her knee on a field", "E": "[picture] a little girl seen from behind, sitting and watching a television", "F": "[picture] clothes hanging on a washing line outdoors"}, "transcript_zh": "女：明天的课你都准备好了没有？ 男：还没有呢，正在准备。", "answer": "C", "answer_ref": {"book": "teacher", "pages": [134]}}, {"n": 8, "zh": "", "options": {"A": "[picture] a doctor with a stethoscope writing on a paper at a desk, a patient''s hands across the desk", "B": "[picture] a woman with a shopping cart reaching for goods on supermarket shelves", "C": "[picture] a schoolgirl and a schoolboy in uniforms sitting together with books, smiling", "D": "[picture] a young woman juggling a football on her knee on a field", "E": "[picture] a little girl seen from behind, sitting and watching a television", "F": "[picture] clothes hanging on a washing line outdoors"}, "transcript_zh": "男：医生，这个药怎么吃？ 女：饭后吃，吃药以后两个小时不要喝茶。", "answer": "A", "answer_ref": {"book": "teacher", "pages": [134]}}, {"n": 9, "zh": "", "options": {"A": "[picture] a doctor with a stethoscope writing on a paper at a desk, a patient''s hands across the desk", "B": "[picture] a woman with a shopping cart reaching for goods on supermarket shelves", "C": "[picture] a schoolgirl and a schoolboy in uniforms sitting together with books, smiling", "D": "[picture] a young woman juggling a football on her knee on a field", "E": "[picture] a little girl seen from behind, sitting and watching a television", "F": "[picture] clothes hanging on a washing line outdoors"}, "transcript_zh": "男：你怎么买了这么多东西？ 女：今天有朋友来我家吃饭。", "answer": "B", "answer_ref": {"book": "teacher", "pages": [134]}}, {"n": 10, "zh": "", "options": {"A": "[picture] a doctor with a stethoscope writing on a paper at a desk, a patient''s hands across the desk", "B": "[picture] a woman with a shopping cart reaching for goods on supermarket shelves", "C": "[picture] a schoolgirl and a schoolboy in uniforms sitting together with books, smiling", "D": "[picture] a young woman juggling a football on her knee on a field", "E": "[picture] a little girl seen from behind, sitting and watching a television", "F": "[picture] clothes hanging on a washing line outdoors"}, "transcript_zh": "女：你看见我那件红色的衣服了吗？ 男：我帮你洗了，在外面呢。", "answer": "F", "answer_ref": {"book": "teacher", "pages": [134]}}]}, {"n": "一、听力 第三部分", "type_zh": "听力 第三部分", "instruction_zh": "第11–15题：听对话，选择正确答案", "instruction_en": "Questions 11-15: Listen to the dialogues and answer the questions.", "items": [{"n": "例", "zh": "问：小王的杯子是什么颜色的？", "pinyin": "Xiǎo Wáng de bēizi shì shénme yánsè de?", "transcript_zh": "男：小王，这里有几个杯子，哪个是你的？ 女：左边那个红色的是我的。 问：小王的杯子是什么颜色的？", "options": {"A": "红色 hóngsè red", "B": "黑色 hēisè black", "C": "白色 báisè white"}, "answer": "A", "answer_ref": {"book": "workbook", "pages": [98]}}, {"n": 11, "zh": "", "transcript_zh": "女：大卫，不要看电视了，去睡觉吧。 男：看电视对学习汉语有帮助，我再看一会儿。 问：大卫为什么要看电视？", "options": {"A": "电视好看 diànshì hǎo kàn", "B": "他不想睡觉 tā bù xiǎng shuì jiào", "C": "他想学习汉语 tā xiǎng xuéxí Hànyǔ"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [134]}}, {"n": 12, "zh": "", "transcript_zh": "男：我想喝茶。 女：医生说吃药后一个小时不要喝茶。 问：男的为什么不能喝茶？", "options": {"A": "茶不好喝 chá bù hǎo hē", "B": "他生病了 tā shēng bìng le", "C": "他吃药了 tā chī yào le"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [134]}}, {"n": 13, "zh": "", "transcript_zh": "女：你看见我的手机了吗？我昨天晚上放在桌子上了。 男：桌子上没有，你看看床上吧。 问：女的的手机在哪儿？", "options": {"A": "不知道 bù zhīdào", "B": "床上 chuáng shang", "C": "桌子上 zhuōzi shang"}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [134]}}, {"n": 14, "zh": "", "transcript_zh": "男：过来喝杯水，休息一下吧。 女：我不累。 问：女的是什么意思？", "options": {"A": "不太忙 bú tài máng", "B": "不太累 bú tài lèi", "C": "想休息 xiǎng xiūxi"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [134]}}, {"n": 15, "zh": "", "transcript_zh": "男：你别忙了，我不在这儿吃饭。 女：菜很快就好了，吃了再走吧。 问：女的是什么意思？", "options": {"A": "没有米饭 méiyǒu mǐfàn", "B": "吃完了 chīwán le", "C": "很快就可以吃饭 hěn kuài jiù kěyǐ chī fàn"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [134]}}]}, {"n": "二、阅读 第一部分", "type_zh": "阅读 第一部分", "instruction_zh": "第16–20题：看图片，选择与句子内容一致的图片", "instruction_en": "Questions 16-20: Choose the right picture for each sentence.", "items": [{"n": "例", "zh": "每个星期六，我都去打篮球。", "pinyin": "Měi ge xīngqīliù, wǒ dōu qù dǎ lánqiú.", "options": {"A": "[picture] a boy typing on a laptop while an adult''s hand pushes the laptop lid closed", "B": "[picture] a young man at a desk with a laptop, rubbing his eyes with both hands", "C": "[picture] a man reading a newspaper with the word “BUSINESS” on it", "D": "[picture] a smiling young man holding a basketball above his head", "E": "[picture] a person holding a plastic laundry basket full of clothes", "F": "[picture] hands holding a smartphone, a finger touching the screen"}, "answer": "D", "answer_ref": {"book": "workbook", "pages": [99]}}, {"n": 16, "zh": "我每天早上都看报纸。", "pinyin": "Wǒ měi tiān zǎoshang dōu kàn bàozhǐ.", "options": {"A": "[picture] a boy typing on a laptop while an adult''s hand pushes the laptop lid closed", "B": "[picture] a young man at a desk with a laptop, rubbing his eyes with both hands", "C": "[picture] a man reading a newspaper with the word “BUSINESS” on it", "D": "[picture] a smiling young man holding a basketball above his head", "E": "[picture] a person holding a plastic laundry basket full of clothes", "F": "[picture] hands holding a smartphone, a finger touching the screen"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [134]}}, {"n": 17, "zh": "妈妈正在给我们洗衣服呢。", "pinyin": "Māma zhèngzài gěi wǒmen xǐ yīfu ne.", "options": {"A": "[picture] a boy typing on a laptop while an adult''s hand pushes the laptop lid closed", "B": "[picture] a young man at a desk with a laptop, rubbing his eyes with both hands", "C": "[picture] a man reading a newspaper with the word “BUSINESS” on it", "D": "[picture] a smiling young man holding a basketball above his head", "E": "[picture] a person holding a plastic laundry basket full of clothes", "F": "[picture] hands holding a smartphone, a finger touching the screen"}, "answer": "E", "answer_ref": {"book": "teacher", "pages": [134]}}, {"n": 18, "zh": "别玩儿电脑了，看电脑时间长了对眼睛不好。", "pinyin": "Bié wánr diànnǎo le, kàn diànnǎo shíjiān cháng le duì yǎnjīng bù hǎo.", "options": {"A": "[picture] a boy typing on a laptop while an adult''s hand pushes the laptop lid closed", "B": "[picture] a young man at a desk with a laptop, rubbing his eyes with both hands", "C": "[picture] a man reading a newspaper with the word “BUSINESS” on it", "D": "[picture] a smiling young man holding a basketball above his head", "E": "[picture] a person holding a plastic laundry basket full of clothes", "F": "[picture] hands holding a smartphone, a finger touching the screen"}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [134]}}, {"n": 19, "zh": "别工作了，睡觉吧，明天早点儿起床。", "pinyin": "Bié gōngzuò le, shuì jiào ba, míngtiān zǎodiǎnr qǐ chuáng.", "options": {"A": "[picture] a boy typing on a laptop while an adult''s hand pushes the laptop lid closed", "B": "[picture] a young man at a desk with a laptop, rubbing his eyes with both hands", "C": "[picture] a man reading a newspaper with the word “BUSINESS” on it", "D": "[picture] a smiling young man holding a basketball above his head", "E": "[picture] a person holding a plastic laundry basket full of clothes", "F": "[picture] hands holding a smartphone, a finger touching the screen"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [134]}}, {"n": 20, "zh": "有什么问题，你可以打我的手机。", "pinyin": "Yǒu shénme wèntí, nǐ kěyǐ dǎ wǒ de shǒujī.", "options": {"A": "[picture] a boy typing on a laptop while an adult''s hand pushes the laptop lid closed", "B": "[picture] a young man at a desk with a laptop, rubbing his eyes with both hands", "C": "[picture] a man reading a newspaper with the word “BUSINESS” on it", "D": "[picture] a smiling young man holding a basketball above his head", "E": "[picture] a person holding a plastic laundry basket full of clothes", "F": "[picture] hands holding a smartphone, a finger touching the screen"}, "answer": "F", "answer_ref": {"book": "teacher", "pages": [134]}}]}, {"n": "二、阅读 第二部分", "type_zh": "阅读 第二部分", "instruction_zh": "第21–25题：选择合适的词语填空", "instruction_en": "Questions 21-25: Choose the proper words to fill in the brackets.", "word_bank": [["A 帮助 bāngzhù", "B 正在 zhèngzài", "C 课 kè", "D 鸡蛋 jīdàn", "E 贵 guì", "F 别 bié"]], "items": [{"n": "例", "zh": "这儿的羊肉很好吃，但是也很（________）。", "pinyin": "Zhèr de yángròu hěn hǎochī, dànshì yě hěn ______.", "answer": "E", "answer_ref": {"book": "workbook", "pages": [100]}}, {"n": 21, "zh": "明天的（________）我都准备好了，可以睡觉了。", "pinyin": "Míngtiān de ______ wǒ dōu zhǔnbèi hǎo le, kěyǐ shuì jiào le.", "answer": "C", "answer_ref": {"book": "teacher", "pages": [134]}}, {"n": 22, "zh": "大卫是一个喜欢（________）别人的好孩子。", "pinyin": "Dàwèi shì yí ge xǐhuan ______ biéren de hǎo háizi.", "answer": "A", "answer_ref": {"book": "teacher", "pages": [134]}}, {"n": 23, "zh": "我每天早上吃一个（________），喝一杯牛奶。", "pinyin": "Wǒ měi tiān zǎoshang chī yí ge ______ hē yì bēi niúnǎi.", "answer": "D", "answer_ref": {"book": "teacher", "pages": [134]}}, {"n": 24, "zh": "妈妈睡觉了，我们（________）看电视了。", "pinyin": "Māma shuì jiào le, wǒmen ______ kàn diànshì le.", "answer": "F", "answer_ref": {"book": "teacher", "pages": [134]}}, {"n": 25, "zh": "哥哥（________）玩儿电脑呢，没时间帮助我。", "pinyin": "Gēge ______ wánr diànnǎo ne, méi shíjiān bāngzhù wǒ.", "answer": "B", "answer_ref": {"book": "teacher", "pages": [134]}}]}, {"n": "二、阅读 第三部分", "type_zh": "阅读 第三部分", "instruction_zh": "第26–30题：判断下列句子的意思是否正确", "instruction_en": "Questions 26-30: Decide whether the inferences are true or false.", "items": [{"n": "例1", "zh": "现在是11点30分，他们已经游了20分钟了。 ★他们11点10分开始游泳。", "pinyin": "Xiànzài shì diǎn fēn, tāmen yǐjīng yóule fēnzhōng le. ★Tāmen diǎn fēn kāishǐ yóuyǒng.", "answer": "√", "answer_ref": {"book": "workbook", "pages": [101]}}, {"n": "例2", "zh": "我会跳舞，但跳得不怎么样。 ★我跳得非常好。", "pinyin": "Wǒ huì tiàowǔ, dàn tiào de bù zěnmeyàng. ★Wǒ tiào de fēicháng hǎo.", "answer": "×", "answer_ref": {"book": "workbook", "pages": [101]}}, {"n": 26, "zh": "这本书是我写的，希望能对你有帮助。 ★这本书还没写完。", "pinyin": "Zhè běn shū shì wǒ xiě de, xīwàng néng duì nǐ yǒu bāngzhù. ★Zhè běn shū hái méi xiěwán.", "answer": "×", "answer_ref": {"book": "teacher", "pages": [134]}}, {"n": 27, "zh": "医生说这个药要饭前吃，吃药后两个小时别喝茶。 ★医生说多喝茶对身体好。", "pinyin": "Yīshēng shuō zhège yào yào fànqián chī, chī yào hòu liǎng ge xiǎoshí bié hē chá. ★Yīshēng shuō duō hē chá duì shēntǐ hǎo.", "answer": "×", "answer_ref": {"book": "teacher", "pages": [134]}}, {"n": 28, "zh": "别找了，你的手机在桌子上呢，电脑旁边。 ★电脑也在桌子上。", "pinyin": "Bié zhǎo le, nǐ de shǒujī zài zhuōzi shang ne, diànnǎo pángbiān. ★Diànnǎo yě zài zhuōzi shang.", "answer": "√", "answer_ref": {"book": "teacher", "pages": [134]}}, {"n": 29, "zh": "那件白色的衣服我帮你洗了，在外面呢。 ★衣服在外面。", "pinyin": "Nà jiàn báisè de yīfu wǒ bāng nǐ xǐ le, zài wàimian ne. ★Yīfu zài wàimian.", "answer": "√", "answer_ref": {"book": "teacher", "pages": [134]}}, {"n": 30, "zh": "机场离这儿很远，坐公共汽车要一个多小时，坐出租车也要四五十分钟吧。 ★机场离这儿非常远。", "pinyin": "Jīchǎng lí zhèr hěn yuǎn, zuò gōnggòngqìchē yào yí ge duō xiǎoshí, zuò chūzūchē yě yào sì wǔshí fēnzhōng ba. ★Jīchǎng lí zhèr fēicháng yuǎn.", "answer": "√", "answer_ref": {"book": "teacher", "pages": [134]}}]}, {"n": "二、阅读 第四部分", "type_zh": "阅读 第四部分", "instruction_zh": "第31–35题：选择合适的问答", "instruction_en": "Questions 31-35: Match the sentences to make dialogues.", "items": [{"n": "例", "zh": "他还在教室里学习。 (He is still studying in the classroom.)", "pinyin": "Tā hái zài jiàoshì li xuéxí.", "options": {"A": "爸，我们明天去跑步吧。 Bà, wǒmen míngtiān qù pǎo bù ba.", "B": "你弟弟正在学习汉语吗？ Nǐ dìdi zhèngzài xuéxí Hànyǔ ma?", "C": "一个红的，一个白的，真漂亮。 Yí ge hóng de, yí ge bái de, zhēn piàoliang.", "D": "你明天的课都准备好了吗？ Nǐ míngtiān de kè dōu zhǔnbèi hǎo le ma?", "E": "他在哪儿呢？你看见他了吗？ Tā zài nǎr ne? Nǐ kànjiàn tā le ma?", "F": "别看电视了，明天还要考试呢。 Bié kàn diànshì le, míngtiān hái yào kǎoshì ne."}, "answer": "E", "answer_ref": {"book": "workbook", "pages": [102]}}, {"n": 31, "zh": "你喜欢哪个？我可以送给你。", "pinyin": "Nǐ xǐhuan nǎ ge? Wǒ kěyǐ sòng gěi nǐ.", "options": {"A": "爸，我们明天去跑步吧。 Bà, wǒmen míngtiān qù pǎo bù ba.", "B": "你弟弟正在学习汉语吗？ Nǐ dìdi zhèngzài xuéxí Hànyǔ ma?", "C": "一个红的，一个白的，真漂亮。 Yí ge hóng de, yí ge bái de, zhēn piàoliang.", "D": "你明天的课都准备好了吗？ Nǐ míngtiān de kè dōu zhǔnbèi hǎo le ma?", "E": "他在哪儿呢？你看见他了吗？ Tā zài nǎr ne? Nǐ kànjiàn tā le ma?", "F": "别看电视了，明天还要考试呢。 Bié kàn diànshì le, míngtiān hái yào kǎoshì ne."}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [134]}}, {"n": 32, "zh": "好啊，医生说多运动对我的身体好。", "pinyin": "Hǎo a, yīshēng shuō duō yùndòng duì wǒ de shēntǐ hǎo.", "options": {"A": "爸，我们明天去跑步吧。 Bà, wǒmen míngtiān qù pǎo bù ba.", "B": "你弟弟正在学习汉语吗？ Nǐ dìdi zhèngzài xuéxí Hànyǔ ma?", "C": "一个红的，一个白的，真漂亮。 Yí ge hóng de, yí ge bái de, zhēn piàoliang.", "D": "你明天的课都准备好了吗？ Nǐ míngtiān de kè dōu zhǔnbèi hǎo le ma?", "E": "他在哪儿呢？你看见他了吗？ Tā zài nǎr ne? Nǐ kànjiàn tā le ma?", "F": "别看电视了，明天还要考试呢。 Bié kàn diànshì le, míngtiān hái yào kǎoshì ne."}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [134]}}, {"n": 33, "zh": "好吧，我这就去睡觉。", "pinyin": "Hǎo ba, wǒ zhè jiù qù shuì jiào.", "options": {"A": "爸，我们明天去跑步吧。 Bà, wǒmen míngtiān qù pǎo bù ba.", "B": "你弟弟正在学习汉语吗？ Nǐ dìdi zhèngzài xuéxí Hànyǔ ma?", "C": "一个红的，一个白的，真漂亮。 Yí ge hóng de, yí ge bái de, zhēn piàoliang.", "D": "你明天的课都准备好了吗？ Nǐ míngtiān de kè dōu zhǔnbèi hǎo le ma?", "E": "他在哪儿呢？你看见他了吗？ Tā zài nǎr ne? Nǐ kànjiàn tā le ma?", "F": "别看电视了，明天还要考试呢。 Bié kàn diànshì le, míngtiān hái yào kǎoshì ne."}, "answer": "F", "answer_ref": {"book": "teacher", "pages": [134]}}, {"n": 34, "zh": "对，因为公司想让他明年去中国工作。", "pinyin": "Duì, yīnwèi gōngsī xiǎng ràng tā míngnián qù Zhōngguó gōngzuò.", "options": {"A": "爸，我们明天去跑步吧。 Bà, wǒmen míngtiān qù pǎo bù ba.", "B": "你弟弟正在学习汉语吗？ Nǐ dìdi zhèngzài xuéxí Hànyǔ ma?", "C": "一个红的，一个白的，真漂亮。 Yí ge hóng de, yí ge bái de, zhēn piàoliang.", "D": "你明天的课都准备好了吗？ Nǐ míngtiān de kè dōu zhǔnbèi hǎo le ma?", "E": "他在哪儿呢？你看见他了吗？ Tā zài nǎr ne? Nǐ kànjiàn tā le ma?", "F": "别看电视了，明天还要考试呢。 Bié kàn diànshì le, míngtiān hái yào kǎoshì ne."}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [134]}}, {"n": 35, "zh": "没问题，您放心吧。", "pinyin": "Méi wèntí, nín fàngxīn ba.", "options": {"A": "爸，我们明天去跑步吧。 Bà, wǒmen míngtiān qù pǎo bù ba.", "B": "你弟弟正在学习汉语吗？ Nǐ dìdi zhèngzài xuéxí Hànyǔ ma?", "C": "一个红的，一个白的，真漂亮。 Yí ge hóng de, yí ge bái de, zhēn piàoliang.", "D": "你明天的课都准备好了吗？ Nǐ 