values ('hsk2-l13', 'hsk2', 'HSK2', 13, '门开着呢', 'Mén kāi zhe ne', 'The door is open', '{"level": "hsk2", "lesson": 13, "book": "HSK2", "title_zh": "门开着呢", "title_pinyin": "Mén kāi zhe ne", "title_en": "The door is open", "textbook": {"ref": {"book": "textbook", "pages": [117, 118, 119, 120, 121, 122, 123, 124]}, "warmup": [{"instruction_zh": "给下面的词语选择对应的图片", "instruction_en": "Match the pictures with the words.", "items": ["①铅笔 qiānbǐ", "②手 shǒu", "③宾馆 bīnguǎn", "④拿 ná", "⑤眼睛 yǎnjing", "⑥路口 lùkǒu"], "pictures_desc_en": ["A: two hands, one resting on the other", "B: close-up of a woman’s eye", "C: a yellow pencil", "D: two roads crossing (a crossroads) seen from above", "E: fingers holding a red chili pepper", "F: a hotel room with two made beds and lamps"]}, {"instruction_zh": "给下面的动词加上合适的宾语", "instruction_en": "Add an appropriate object after each of the following verbs.", "items": ["例如：学 汉语 xué Hànyǔ", "下________ xià", "坐________ zuò", "听________ tīng", "上________ shàng", "送________ sòng", "拿________ ná"]}], "pronunciation": [{"title_zh": "祈使句的句调", "rows": ["Ràng wǒmen xiūxi xiūxi ba. （1）让我们休息休息吧。↘", "Kuàidiǎnr xià kè ba. （2）快点儿下课吧。↘", "Qǐng zuò ba. （3）请坐吧。↘"], "notes_zh": ["语气委婉时，全句音高较低，第一个分句末尾语调略升，全句末尾语调缓降。例如：", "“↘”为书中句末的下降箭头（书中无文字说明）。"], "notes_en": ["Intonation of an Imperative Sentence", "When the tone is polite, the whole sentence is said in a low pitch, the first clause ending in a slightly rising intonation and the whole sentence ending in a smoothly falling intonation. For example:"]}], "texts": [{"n": 1, "title_zh": "在办公室", "title_en": "In the office", "kind": "dialogue", "lines": [{"speaker": "A", "zh": "门开着呢，请进。", "pinyin": "Mén kāi zhe ne, qǐng jìn."}, {"speaker": "B", "zh": "请问，张先生在吗？", "pinyin": "Qǐngwèn, Zhāng xiānsheng zài ma?"}, {"speaker": "A", "zh": "他出去了。你下午再来吧。", "pinyin": "Tā chūqu le. Nǐ xiàwǔ zài lái ba."}, {"speaker": "B", "zh": "好的，谢谢！", "pinyin": "Hǎo de, xièxie!"}], "english_version": "A: The door is open. Come on in.\nB: Excuse me, is Mr. Zhang in?\nA: He’s gone out. Please come in the afternoon.\nB: OK. Thank you!", "new_words": [{"n": 1, "zh": "着", "pinyin": "zhe", "pos": "part.", "en": "used to indicate a state", "text": 1}]}, {"n": 2, "title_zh": "在办公室", "title_en": "In the office", "kind": "dialogue", "lines": [{"speaker": "A", "zh": "那个正在说话的女孩儿是谁？", "pinyin": "Nàge zhèngzài shuōhuà de nǚháir shì shéi?"}, {"speaker": "B", "zh": "我知道她的名字，她姓杨，叫杨笑笑，她姐姐是我同学。", "pinyin": "Wǒ zhīdào tā de míngzi, tā xìng Yáng, jiào Yáng Xiàoxiao, tā jiějie shì wǒ tóngxué."}, {"speaker": "A", "zh": "那个手里拿着铅笔的呢？", "pinyin": "Nàge shǒu li názhe qiānbǐ de ne?"}, {"speaker": "B", "zh": "我不认识。", "pinyin": "Wǒ bú rènshi."}], "english_version": "A: Who is the girl speaking?\nB: I know her name. Her name is Yang Xiaoxiao. Yang is her family name. Her elder sister is my classmate.\nA: What about the girl with a pencil in her hand?\nB: That one I don’t know.", "new_words": [{"n": 2, "zh": "手", "pinyin": "shǒu", "pos": "n.", "en": "hand", "text": 2}, {"n": 3, "zh": "拿", "pinyin": "ná", "pos": "v.", "en": "to hold, to take, to bring", "star": true, "text": 2}, {"n": 4, "zh": "铅笔", "pinyin": "qiānbǐn", "pos": "n.", "en": "pencil", "text": 2}], "proper_nouns": [{"zh": "杨笑笑", "pinyin": "Yáng Xiàoxiao", "en": "name of a person"}]}, {"n": 3, "title_zh": "在运动场", "title_en": "On the playground", "kind": "dialogue", "lines": [{"speaker": "A", "zh": "听说你有女朋友了？我认识她吗？", "pinyin": "Tīngshuō nǐ yǒu nǚpéngyou le? Wǒ rènshi tā ma?"}, {"speaker": "B", "zh": "就是我们班那个长着两个大眼睛，非常爱笑的女孩儿。", "pinyin": "Jiù shì wǒmen bān nàge zhǎngzhe liǎng ge dà yǎnjing, fēicháng ài xiào de nǚháir."}, {"speaker": "A", "zh": "她不是有男朋友吗？", "pinyin": "Tā bú shì yǒu nánpéngyou ma?"}, {"speaker": "B", "zh": "那个已经是她的前男友了。", "pinyin": "Nàge yǐjīng shì tā de qián nányǒu le."}], "english_version": "A: I heard you have a girlfriend now? Do I know her?\nB: She is the girl in our class with big eyes and a smiling face.\nA: She’s already got a boyfriend, hasn’t she?\nB: That’s her ex now.", "new_words": [{"n": 5, "zh": "班", "pinyin": "bān", "pos": "n.", "en": "class, grade, team", "star": true, "text": 3}, {"n": 6, "zh": "长", "pinyin": "zhǎng", "pos": "v.", "en": "to grow, to develop", "star": true, "text": 3}, {"n": 7, "zh": "笑", "pinyin": "xiào", "pos": "v.", "en": "to smile, to laugh", "text": 3}]}, {"n": 4, "title_zh": "在路上", "title_en": "On the road", "kind": "dialogue", "lines": [{"speaker": "A", "zh": "请问，这儿离新京宾馆远吗？", "pinyin": "Qǐngwèn, zhèr lí Xīnjīng Bīnguǎn yuǎn ma?"}, {"speaker": "B", "zh": "不远，走路二十分钟就到。", "pinyin": "Bù yuǎn, zǒu lù èrshí fēnzhōng jiù dào."}, {"speaker": "A", "zh": "你能告诉我怎么走吗？", "pinyin": "Nǐ néng gàosu wǒ zěnme zǒu ma?"}, {"speaker": "B", "zh": "从这儿一直往前走，到了前面的路口再往右走。", "pinyin": "Cóng zhèr yìzhí wǎng qián zǒu, dàole qiánmiàn de lùkǒu zài wǎng yòu zǒu."}], "english_version": "A: Excuse me, is Xinjing Hotel far away from here?\nB: No, it’s about a 20 minutes’ walk.\nA: Could you tell me how to get there?\nB: Walk straight ahead from here and turn right at the first crossing.", "new_words": [{"n": 8, "zh": "宾馆", "pinyin": "bīnguǎn", "pos": "n.", "en": "hotel", "text": 4}, {"n": 9, "zh": "一直", "pinyin": "yìzhí", "pos": "adv.", "en": "straight, all along", "star": true, "text": 4}, {"n": 10, "zh": "往", "pinyin": "wǎng", "pos": "prep.", "en": "to, towards", "text": 4}, {"n": 11, "zh": "路口", "pinyin": "lùkǒu", "pos": "n.", "en": "crossing, crossroads", "text": 4}]}], "grammar": [{"n": 1, "title_zh": "结构助词“着”", "title_en": "The Structural Particle “着”", "explanation_zh": "动词加上结构助词“着”可以表示某种状态的持续。例如：\n在动词前加“没”表示否定。例如：\n在句末加“没有”表示疑问。例如：", "explanation_en": "A verb followed by the structural particle “着” can indicate the continuation of a certain state. For example:\nIn the negative form, “没” is added before the verb. For example:\nIn the interrogative form, “没有” is added at the end of the sentence. For example:", "structure_rows": ["Subject | Predicate: V | 着 | O", "门 | 开 | 着。 | ", "他们 | 穿 | 着 | 红色的衣服。", "（她） | 拿 | 着 | 铅笔。", "Subject | Predicate: 没＋V | 着 | O", "门 | 没开 | 着。 | ", "他们 | 没穿 | 着 | 红色的衣服。", "（她） | 没拿 | 着 | 铅笔。", "Subject | Predicate: V | 着 | O | 没有", "门 | 开 | 着 |  | 没有？", "他们 | 穿 | 着 | 红色的衣服 | 没有？", "她（手里） | 拿 | 着 | 铅笔 | 没有？"], "examples": [{"n": 1, "zh": "门开着。"}, {"n": 2, "zh": "他们穿着红色的衣服。"}, {"n": 3, "zh": "（她）拿着铅笔。"}, {"n": 4, "zh": "门没开着。"}, {"n": 5, "zh": "他们没穿着红色的衣服。"}, {"n": 6, "zh": "（她）没拿着铅笔。"}, {"n": 7, "zh": "门开着没有？"}, {"n": 8, "zh": "他们穿着红色的衣服没有？"}, {"n": 9, "zh": "她（手里）拿着铅笔没有？"}]}, {"n": 2, "title_zh": "反问句“不是……吗”", "title_en": "The Rhetorical Question “不是……吗”", "explanation_zh": "“不是……吗”常用来表示提醒或者表达说话人的不理解、不满等。例如：", "explanation_en": "“不是……吗” is often used to remind someone of something or to show confusion or dissatisfaction. For example:", "examples": [{"n": 1, "zh": "不是说今天有雨吗？怎么没下？"}, {"n": 2, "zh": "你不是北京人吗？怎么不会说北京话？"}, {"n": 3, "zh": "（她是你的女朋友？）她不是有男朋友了吗？"}]}, {"n": 3, "title_zh": "介词“往”", "title_en": "The Preposition “往”", "explanation_zh": "介词“往”常常用来指示方向。例如：", "explanation_en": "The preposition “往” is often used to indicate direction. For example:", "examples": [{"n": 1, "zh": "从这儿往前走，就是我们学校。"}, {"n": 2, "zh": "你看，往左走是医院，往右走是银行。"}, {"n": 3, "zh": "从这儿一直往前走，到了前面的路口再往右走。"}]}], "exercises": [{"n": 1, "type_zh": "分角色朗读课文", "instruction_zh": "分角色朗读课文", "instruction_en": "Role-play the dialogs.", "items": []}, {"n": 2, "type_zh": "回答问题", "instruction_zh": "根据课文内容回答问题", "instruction_en": "Answer the questions based on the dialogs.", "items": [{"n": 1, "zh": "张先生去哪儿了？", "pinyin": "Zhāng xiānsheng qù nǎr le?"}, {"n": 2, "zh": "杨笑笑是谁？", "pinyin": "Yáng Xiàoxiao shì shéi?"}, {"n": 3, "zh": "他的女朋友是谁？", "pinyin": "Tā de nǚpéngyou shì shéi?"}, {"n": 4, "zh": "“前男友”是什么意思？", "pinyin": "“Qián nányǒu” shì shénme yìsi?"}, {"n": 5, "zh": "去新京宾馆怎么走？", "pinyin": "Qù Xīnjīng Bīnguǎn zěnme zǒu?"}]}, {"n": 3, "type_zh": "描述图片", "instruction_zh": "用本课新学的语言点和词语描述图片", "instruction_en": "Describe the pictures using the newly-learned language points and words.", "items": [{"n": 1, "zh": "他________。", "pinyin": "Tā ______. （ná）", "hint_zh": "（拿）", "picture_desc_en": "a hand holding an orange pen"}, {"n": 2, "zh": "他________。", "pinyin": "Tā ______. （chuān）", "hint_zh": "（穿）", "picture_desc_en": "a young man standing, wearing a white T-shirt and black jeans"}, {"n": 3, "zh": "电视________。", "pinyin": "Diànshì ______. （kāi）", "hint_zh": "（开）", "picture_desc_en": "two people seen from behind sitting on a sofa facing a television that is on"}, {"n": 4, "zh": "他________呢。", "pinyin": "Tā ______ ne. （kāi）", "hint_zh": "（开）", "picture_desc_en": "a smiling man in a suit driving a car"}]}], "characters": {"knowledge_title_zh": "汉字偏旁“斤”和“页”", "knowledge_zh": "偏旁 | 解释 | 例字\n斤 | 斤字旁，一般与斧头及砍削的动作有关系。 | 新 xīn、所 suǒ\n页 | 页字旁，一般与人头、面部有关系。 | 颜 yán、须 xū", "knowledge_en": "Chinese Radicals: “斤” and “页” — The radical “斤” is usually related to axes or the action of cutting or whittling: 新 xīn new; 所 suǒ place. The radical “页” is usually related to the human head or face: 颜 yán face, look; 须 xū beard, mustache.", "characters": [{"zh": "新", "pinyin": "xīn", "note_zh": "偏旁“斤（斤字旁）”例字（new）"}, {"zh": "所", "pinyin": "suǒ", "note_zh": "偏旁“斤（斤字旁）”例字（place）"}, {"zh": "颜", "pinyin": "yán", "note_zh": "偏旁“页（页字旁）”例字（face, look）"}, {"zh": "须", "pinyin": "xū", "note_zh": "偏旁“页（页字旁）”例字（beard, mustache）"}]}, "application": [{"title_zh": "双人活动", "instruction_zh": "两人一组，其中一个人用“往……”说句子，另一个同学做出相应的动作，然后两个人交替进行。", "instruction_en": "Work in pairs. One says sentences using “往……”, and the other acts accordingly. Then switch the roles.", "example_zh": ["例如：往前走 wǎng qián zǒu", "往后跑 wǎng hòu pǎo", "往左看 wǎng zuǒ kàn", "往右走 wǎng yòu zǒu"]}, {"title_zh": "小组活动", "instruction_zh": "3~4人一组，用结构助词“着”描述图片内容。每组请一位同学做记录。", "instruction_en": "Work in groups of 3-4. Describe the picture using the structural particle “着”. Each group chooses a member to take notes.", "example_zh": ["例如：有两个学生穿着白色的衣服。 Yǒu liǎng ge xuésheng chuānzhe báisè de yīfu.", "［picture］a woman sitting on a chair reading a picture book to a group of young children sitting on a blue-and-white tiled floor", "（1）________。（坐着 zuòzhe）", "（2）________。（穿着 chuānzhe）", "（3）________。（看着 kànzhe）", "（4）________。（说着 shuōzhe）", "（5）________。（听着 tīngzhe）", "（6）________。（拿着 názhe）", "（7）________。（笑着 xiàozhe）"]}]}, "teacher": {"ref": {"book": "teacher", "pages": [94, 95, 96, 97, 98, 99, 100]}, "objectives_zh": ["重点词语：学生能够熟练掌握“手、拿、长、一直、路口”的词义和用法", "语言点：学生能够了解并掌握：（1）动态助词“着”（2）反问句“不是……吗”（3）介词“往”", "语音：学生能够掌握祈使句的句调，并能正确朗读", "汉字：学生能够：（1）熟练认读本课生词（2）了解“斤（斤字旁）、页（页字旁）”所表示的意思", "功能：学生能够：（1）表达某种状态的延续（动态助词“着”）（2）表达提醒或者表达说话人的不理解、不满意等（不是……吗）（3）指示方向（介词“往”）"], "steps": [{"title_zh": "一 复习旧课", "body_zh": "1. 教师出示第12课生词卡片，要求学生快速认读下列生词：\n妻子、雪、零度、穿、进、弟弟、近\n2. 教师带领学生辨析下列字形相近的汉字：\n雨____　进____　第____　真____\n雪____　近____　弟____　直____\n3. 教师引导学生把下列句子变成问句，再用否定式回答：\n我觉得我的汉语说得很好。\n这是妻子给我做的鱼，做得很好吃。\n从我家到医院有点儿远。"}, {"title_zh": "二 学习新课 1 热身", "body_zh": "热身1：教师先带领学生根据图片选出正确的词语，然后分组练习。一组学生看图片说出正确的词语；另一组学生看词语，说出图片的编号。\n答案：①C　②A　③F　④E　⑤B　⑥D\n热身2：教师可以先让学生自己完成，然后请学生说出自己的答案。教师要鼓励学生说出不同的答案。\n例如：下课　下车　下飞机　……"}, {"title_zh": "2 生词", "body_zh": "（1）生词快速认读及正音\n着、手、拿、铅笔、班、长、笑、宾馆、一直、往、路口\n• 教师可以用PPT依次快速展示生词；\n• 教师领读，学生齐读；\n• 学生接龙式读一遍，每人读两个。\n（2）重点生词扩展及常用搭配\n手—左手—右手—手里—在手上\n　—我喜欢用左手写字。\n　—你手里的东西是什么？\n　—那个手里拿着铅笔的人是谁？\n拿—拿东西—拿铅笔—拿好—没拿到\n　—下车的时候，请大家拿好自己的东西。\n　—别让他拿那么多东西。\n　—那个手里拿着铅笔的人是我朋友。\n长—长大—长高—长着\n　—孩子已经长大了。\n　—几年没见，你都长这么高了。\n　—（大卫的女朋友）就是我们班那个长着两个大眼睛、非常爱笑的女孩儿。\n一直—一直走—一直往前—一直往左走\n　—从这儿一直走就是我们学校。\n　—一直往左走就是宾馆。\n　—从这儿一直往前走。\n路口—十字路口—大路口—左边的路口—路口的右边\n　—前边有一个十字路口。\n　—路口的右边就是医院。\n　—从这儿一直往前走，到了前面的路口再往右走。\n练习册相关练习：第115页／一／第一部分，第118-119页／二／第一、二部分"}, {"title_zh": "3 语言点（1）动态助词“着”", "body_zh": "① 语言点解析：\n表示状态的持续，可以用在动词、形容词后，动词、形容词前一般不加“正、正在、在”。\n［句型框］主语＋动词＋着＋宾语\n［句型框］主语＋没（有）＋动词＋着＋定语\n② 语言点导入：\n教师可根据班里的实际情况，用提问的方式导入语言点。\n教师：（指着教室里的灯问学生）灯开着还是关着？\n学生：灯开着。\n教师：（指着教室里的门问学生）门开着还是关着？\n学生：门关着。\n③ 语言点操练：\n教师带领学生大声朗读下列句子。\n同学们在教室里坐着。\n她穿着一件白色的衣服。\n房间的门开着，小王在里边学习汉语呢。\n电视开着，可是没有人看。\n④ 语言点扩展练习：\n教师带领学生做课本第104页的小组活动。"}, {"title_zh": "3 语言点（2）反问句“不是……吗”", "body_zh": "① 语言点解析：\n用“不是……吗”的格式，强调“不是”后边的句子，提醒学生注意某种明显的事实，表达时略带惊讶或者不满的语气。\n② 语言点导入：\n教师说出陈述句，请学生变成反问句的形式，并提醒学生注意体会句子的意思。教师可以用学生熟悉的人或事物创设情境导入。\n教师：王方19岁了。\n学生：王方不是20岁了吗？\n教师：前边路口有一个很大的饭馆。\n学生：前边路口不是只有一个小饭馆吗？\n③ 语言点操练：\n教师带领学生大声朗读下列句子，并提醒学生注意体会句子的意思。\n你不是说今天休息吗？怎么又来学校了？\n你不是没钱吗？怎么还买这么贵的衣服？\n你弟弟上大学了？他不是只有16岁吗？\n前边不是有一个书店吗？\n④ 语言点扩展练习：\n把学生分成两组，一组学生用“不是……吗”说句子，另一组学生用肯定句或者否定句回答。\n你不是每天六点起床吗？________。\n你妈妈不是上个星期来北京了吗？________。\n那个正在说话的女孩不是你姐姐吗？________。\n那个穿红衣服的不是王老师吗？________。"}, {"title_zh": "3 语言点（3）介词“往”", "body_zh": "① 语言点解析：\n表示动作的方向。可以跟方位词或者处所词组成介词短语，用在动词前。\n［句型框］往＋方位词／处所词＋动词\n② 语言点导入：\n教师做动作，让学生来说。\n往前走—往后走—往左走—往右走—往外走\n③ 语言点操练：\n把学生分成两组，分别用“往＋方向＋动作”说句子，看哪组说得准确，说得多，说得快。\n例如：往前看　往后走　往左跑　……\n④ 语言点扩展练习：\n• 教师带领学生做课本第103页的双人活动。\n• 教师带领学生完成课本第102页练习部分的第三题。"}, {"title_zh": "4 课文", "body_zh": "课文1\n（1）让学生听两遍录音并回答下列问题：\nB想找谁？\n张先生在办公室吗？\n张先生去哪儿了？\n张先生什么时候回来？\n（2）教师领读课文两遍，然后让学生分角色朗读课文。\n（3）请学生根据课文内容，自己设计情景，进行角色扮演。\n课文2\n（1）让学生听两遍录音并回答下列问题：\n那个正在说话的人是谁？\n谁认识杨笑笑？为什么？\n那个手里拿着铅笔的人是谁？\n（2）教师带领学生齐读课文两遍，然后请学生分角色朗读课文。\n（3）教师用PPT展示课文提示词，请学生再次通读一遍课文后，根据提示词复述课文。\nA：那个……是谁？\nB：我知道……，她姓……，叫杨笑笑，她姐姐……。\nA：那个……的呢？\nB：我不认识。\n课文3\n（1）让学生听两遍录音并回答下列问题：\nB有女朋友了吗？\n说说B的女朋友什么样？\nA认识B的女朋友吗？为什么？\n“前男友”是什么意思？\n（2）教师带领学生齐读课文两遍，然后请学生分角色朗读课文。\n（3）教师用PPT展示课文提示词，请学生再次通读一遍课文后，根据提示词复述课文。\nA：听说……了？我认识她吗？\nB：就是我们班那个……，非常……的女孩儿。\nA：她不是……吗？\nB：那个已经是……了。\n课文4\n（1）让学生听两遍录音并回答下列问题：\nA在做什么呢？\nA想去什么地方？\n新京宾馆离这儿远不远？\n去新京宾馆怎么走？\n（2）教师带领学生齐读课文两遍，然后请学生分角色朗读课文。\n（3）教师用PPT展示课文提示词，把学生分成两组，分角色复述课文。\nA：请问，……远吗？\nB：不远，走路……。\nA：你能……吗？\nB：从这儿……，到了前面的路口……。\n（4）请学生进行角色扮演。"}, {"title_zh": "5 语音", "body_zh": "祈使句的句调：\n① 知识点解析\n祈使句的作用是要求、命令或建议别人做或不做一件事。句调通常是一个降调，全句音高较低。如果是两个分句，前一个分句末尾语调略升，全句末尾语调缓降。\n快点儿学习吧。↘\n坐公共汽车去学校吧。↘\n下雨了，多穿点儿衣服吧。↘\n② 语音练习\n教师可利用课本第102页的例句进行练习。教师可先领读句子，使学生掌握祈使句的句调特点，然后让学生个别读，教师纠正错误。\n练习册相关练习：第122页／三"}, {"title_zh": "6 汉字", "body_zh": "① 知识点解析：\n偏旁\n斤：斤字旁，由它构成的汉字一般与斧头、砍削的动作有关系。\n页：页字旁，由它构成的汉字一般与人头、面部有关系。\n② 汉字练习：\n• 教师板书本课偏旁“斤、页”，提示学生注意这两个偏旁的笔画和笔顺，并书写各自的代表汉字，帮助学生识记该偏旁的意义。\n• 补充练习\na. 找出下列含有斤字旁和页字旁的汉字\n颜　岩　题　质\n新　须　忻　所\nb. 拆分下列汉字\n着：____　____　笔：____　____\n拿：____　____　宾：____　____\nc. 用下列偏旁和部件组合成新汉字\n合　⺮　宀　毛　主　兵　彳　手\n____　____　____　____\n练习册相关练习：第123页／四"}, {"title_zh": "7 补充课堂活动——猜猜他／她是谁", "body_zh": "请学生模仿第二段和第三段课文，描述本班一个同学的外貌或性格特点，不许说出名字，然后请大家猜猜他／她是谁。（时间允许的情况下让每个学生都做描述练习。）\n例如：\n她是女孩子。眼睛很大，个子很高，喜欢穿红色的衣服。朋友很多，上课的时候非常爱笑。我们都很喜欢她。"}, {"title_zh": "8 本课小结", "body_zh": "• 语言点：动态助词“着”\n　反问句“不是……吗”\n　介词“往”\n• 语音：祈使句的句调\n• 汉字：偏旁“斤、页”"}, {"title_zh": "附注：建议教学用具", "body_zh": "生词卡片：第12、13课生词卡片"}], "notes_zh": [], "warmup_answers_zh": ["热身1 答案：①C　②A　③F　④E　⑤B　⑥D", "热身2 例如：下课　下车　下飞机　……"], "text_questions": [{"text": 1, "q_zh": "B想找谁？"}, {"text": 1, "q_zh": "张先生在办公室吗？"}, {"text": 1, "q_zh": "张先生去哪儿了？"}, {"text": 1, "q_zh": "张先生什么时候回来？"}, {"text": 2, "q_zh": "那个正在说话的人是谁？"}, {"text": 2, "q_zh": "谁认识杨笑笑？为什么？"}, {"text": 2, "q_zh": "那个手里拿着铅笔的人是谁？"}, {"text": 3, "q_zh": "B有女朋友了吗？"}, {"text": 3, "q_zh": "说说B的女朋友什么样？"}, {"text": 3, "q_zh": "A认识B的女朋友吗？为什么？"}, {"text": 3, "q_zh": "“前男友”是什么意思？"}, {"text": 4, "q_zh": "A在做什么呢？"}, {"text": 4, "q_zh": "A想去什么地方？"}, {"text": 4, "q_zh": "新京宾馆离这儿远不远？"}, {"text": 4, "q_zh": "去新京宾馆怎么走？"}], "summary_zh": "• 语言点：动态助词“着”\n　反问句“不是……吗”\n　介词“往”\n• 语音：祈使句的句调\n• 汉字：偏旁“斤、页”"}, "workbook": {"ref": {"book": "workbook", "pages": [123, 124, 125, 126, 127, 128, 129, 130, 131]}, "sections": [{"n": "一、听力 第一部分", "type_zh": "听力 第一部分", "instruction_zh": "第1–5题：听句子，判断对错", "instruction_en": "Questions 1-5: Decide whether the pictures are right or wrong based on the sentences you hear.", "items": [{"n": "例1", "zh": "我们家有三个人。", "pinyin": "Wǒmen jiā yǒu sān ge rén.", "transcript_zh": "我们家有三个人。", "picture_desc_en": "a smiling family outdoors: a man carrying a child on his shoulders and a woman", "answer": "√", "answer_ref": {"book": "workbook", "pages": [123]}}, {"n": "例2", "zh": "我每天坐公共汽车去上班。", "pinyin": "Wǒ měi tiān zuò gōnggòngqìchē qù shàng bān.", "transcript_zh": "我每天坐公共汽车去上班。", "picture_desc_en": "a mountain bicycle", "answer": "×", "answer_ref": {"book": "workbook", "pages": [123]}}, {"n": 1, "zh": "", "transcript_zh": "大卫开着车出去了。", "picture_desc_en": "a smiling man driving a car", "answer": "√", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": 2, "zh": "", "transcript_zh": "那个笑着说话的女孩儿是谁？", "picture_desc_en": "a young woman posing cheek to cheek with a stuffed toy with big eyes", "answer": "×", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": 3, "zh": "", "transcript_zh": "那个手里拿着铅笔的人是我朋友。", "picture_desc_en": "a smiling woman holding up a mobile phone", "answer": "×", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": 4, "zh": "", "transcript_zh": "我的女朋友长着两个大眼睛，非常爱笑。", "picture_desc_en": "a smiling young woman in a knitted hat making a V sign", "answer": "√", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": 5, "zh": "", "transcript_zh": "这儿离新京宾馆不太远，到前面的路口再往右。", "picture_desc_en": "a country road with a right-turn arrow road sign", "answer": "√", "answer_ref": {"book": "teacher", "pages": [140]}}]}, {"n": "一、听力 第二部分", "type_zh": "听力 第二部分", "instruction_zh": "第6–10题：听对话，选择与对话内容一致的图片", "instruction_en": "Questions 6-10: Choose the right picture for each dialogue you hear.", "items": [{"n": "例", "zh": "男：你喜欢什么运动？ Nǐ xǐhuan shénme yùndòng? (What sport do you like?) 女：我最喜欢踢足球。 Wǒ zuì xǐhuan tī zúqiú. (My favorite sport is playing football.)", "transcript_zh": "男：你喜欢什么运动？ 女：我最喜欢踢足球。", "options": {"A": "[picture] a smiling girl sitting at a desk writing, a globe behind her", "B": "[picture] a middle-aged man leaning back relaxing with his hands behind his head", "C": "[picture] a young woman looking out of the rear window of a taxi marked “的士”", "D": "[picture] a young woman juggling a football on her knee on a field", "E": "[picture] a street lined with shops and old buildings", "F": "[picture] a laughing little girl and a smiling man at a desk"}, "answer": "D", "answer_ref": {"book": "workbook", "pages": [124]}}, {"n": 6, "zh": "", "options": {"A": "[picture] a smiling girl sitting at a desk writing, a globe behind her", "B": "[picture] a middle-aged man leaning back relaxing with his hands behind his head", "C": "[picture] a young woman looking out of the rear window of a taxi marked “的士”", "D": "[picture] a young woman juggling a football on her knee on a field", "E": "[picture] a street lined with shops and old buildings", "F": "[picture] a laughing little girl and a smiling man at a desk"}, "transcript_zh": "男：那个非常爱笑的女孩儿是谁？ 女：你不认识她吗？她叫笑笑，是王老师的女儿。", "answer": "F", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": 7, "zh": "", "options": {"A": "[picture] a smiling girl sitting at a desk writing, a globe behind her", "B": "[picture] a middle-aged man leaning back relaxing with his hands behind his head", "C": "[picture] a young woman looking out of the rear window of a taxi marked “的士”", "D": "[picture] a young woman juggling a football on her knee on a field", "E": "[picture] a street lined with shops and old buildings", "F": "[picture] a laughing little girl and a smiling man at a desk"}, "transcript_zh": "女：请问，这儿离商店远吗？ 男：不远，往前走，下一个路口就是。", "answer": "E", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": 8, "zh": "", "options": {"A": "[picture] a smiling girl sitting at a desk writing, a globe behind her", "B": "[picture] a middle-aged man leaning back relaxing with his hands behind his head", "C": "[picture] a young woman looking out of the rear window of a taxi marked “的士”", "D": "[picture] a young woman juggling a football on her knee on a field", "E": "[picture] a street lined with shops and old buildings", "F": "[picture] a laughing little girl and a smiling man at a desk"}, "transcript_zh": "男：那个手里拿着铅笔的孩子是你妹妹吗？ 女：不是，她是我同学的妹妹。", "answer": "A", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": 9, "zh": "", "options": {"A": "[picture] a smiling girl sitting at a desk writing, a globe behind her", "B": "[picture] a middle-aged man leaning back relaxing with his hands behind his head", "C": "[picture] a young woman looking out of the rear window of a taxi marked “的士”", "D": "[picture] a young woman juggling a football on her knee on a field", "E": "[picture] a street lined with shops and old buildings", "F": "[picture] a laughing little girl and a smiling man at a desk"}, "transcript_zh": "女：椅子上坐着的那个人是谁？ 男：是我爸爸。他有点儿累，正休息呢。", "answer": "B", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": 10, "zh": "", "options": {"A": "[picture] a smiling girl sitting at a desk writing, a globe behind her", "B": "[picture] a middle-aged man leaning back relaxing with his hands behind his head", "C": "[picture] a young woman looking out of the rear window of a taxi marked “的士”", "D": "[picture] a young woman juggling a football on her knee on a field", "E": "[picture] a street lined with shops and old buildings", "F": "[picture] a laughing little girl and a smiling man at a desk"}, "transcript_zh": "男：现在八点十分了，你到机场了吗？ 女：没有，我还在出租车上呢，很快就到。", "answer": "C", "answer_ref": {"book": "teacher", "pages": [140]}}]}, {"n": "一、听力 第三部分", "type_zh": "听力 第三部分", "instruction_zh": "第11–15题：听对话，选择正确答案", "instruction_en": "Questions 11-15: Listen to the dialogues and answer the questions.", "items": [{"n": "例", "zh": "问：小王的杯子是什么颜色的？", "pinyin": "Xiǎo Wáng de bēizi shì shénme yánsè de?", "transcript_zh": "男：小王，这里有几个杯子，哪个是你的？ 女：左边那个红色的是我的。 问：小王的杯子是什么颜色的？", "options": {"A": "红色 hóngsè red", "B": "黑色 hēisè black", "C": "白色 báisè white"}, "answer": "A", "answer_ref": {"book": "workbook", "pages": [125]}}, {"n": 11, "zh": "", "transcript_zh": "男：请问李先生在公司吗？ 女：他开着车出去了，你下午再来吧。 问：李先生在哪儿？", "options": {"A": "在公司 zài gōngsī", "B": "在家里 zài jiāli", "C": "在外面 zài wàimian"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": 12, "zh": "", "transcript_zh": "女：大卫是杨笑笑的男朋友吗？ 男：是杨笑笑的前男友。 问：大卫现在是杨笑笑的男朋友吗？", "options": {"A": "是 shì", "B": "不是 bú shì", "C": "不知道 bù zhīdào"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": 13, "zh": "", "transcript_zh": "男：你的书太多了，我帮你拿着吧。 女：不用了，我一个人就可以了。 问：男的为什么要帮女的拿书？", "options": {"A": "书太大 shū tài dà", "B": "书太多 shū tài duō", "C": "书太贵 shū tài guì"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": 14, "zh": "", "transcript_zh": "男：为什么你每天都穿着红色的衣服？ 女：因为别人都说我穿红色的衣服好看。 问：女的为什么每天都穿着红色的衣服？", "options": {"A": "喜欢红色 xǐhuan hóngsè", "B": "喜欢衣服 xǐhuan yīfu", "C": "别人说好看 biéren shuō hǎokàn"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": 15, "zh": "", "transcript_zh": "男：那个笑着说话的女孩儿是谁？ 女：哪个？是穿红衣服的那个吗？ 男：对，就是她。 女：她是新来的学生，我也不认识。 问：谁认识那个女孩儿？", "options": {"A": "男的认识 nán de rènshi", "B": "女的认识 nǚ de rènshi", "C": "男的和女的都不认识 nán de hé nǚ de dōu bú rènshi"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [140]}}]}, {"n": "二、阅读 第一部分", "type_zh": "阅读 第一部分", "instruction_zh": "第16–20题：看图片，选择与句子内容一致的图片", "instruction_en": "Questions 16-20: Choose the right picture for each sentence.", "items": [{"n": "例", "zh": "每个星期六，我都去打篮球。", "pinyin": "Měi ge xīngqīliù, wǒ dōu qù dǎ lánqiú.", "options": {"A": "[picture] a smiling woman, man and boy preparing food together in a kitchen", "B": "[picture] a man walking, carrying a book under his arm", "C": "[picture] a smiling woman sitting at a table with several young children", "D": "[picture] a smiling young man holding a basketball above his head", "E": "[picture] a “TAXI” sign on the roof of a car", "F": "[picture] two smiling women behind the counter of a café with an “Open” sign"}, "answer": "D", "answer_ref": {"book": "workbook", "pages": [126]}}, {"n": 16, "zh": "晚上十点了，咖啡店还开着门呢。", "pinyin": "Wǎnshang shí diǎn le, kāfēidiàn hái kāizhe mén ne.", "options": {"A": "[picture] a smiling woman, man and boy preparing food together in a kitchen", "B": "[picture] a man walking, carrying a book under his arm", "C": "[picture] a smiling woman sitting at a table with several young children", "D": "[picture] a smiling young man holding a basketball above his head", "E": "[picture] a “TAXI” sign on the roof of a car", "F": "[picture] two smiling women behind the counter of a café with an “Open” sign"}, "answer": "F", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": 17, "zh": "老师每天都坐着给学生们上课。", "pinyin": "Lǎoshī měi tiān dōu zuòzhe gěi xuéshengmen shàng kè.", "options": {"A": "[picture] a smiling woman, man and boy preparing food together in a kitchen", "B": "[picture] a man walking, carrying a book under his arm", "C": "[picture] a smiling woman sitting at a table with several young children", "D": "[picture] a smiling young man holding a basketball above his head", "E": "[picture] a “TAXI” sign on the roof of a car", "F": "[picture] two smiling women behind the counter of a café with an “Open” sign"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": 18, "zh": "妈妈笑着说：“今天给你们做了很多好吃的东西”。", "pinyin": "Māma xiàozhe shuō “jīntiān gěi nǐmen zuòle hěn duō hǎochī de dōngxi”.", "options": {"A": "[picture] a smiling woman, man and boy preparing food together in a kitchen", "B": "[picture] a man walking, carrying a book under his arm", "C": "[picture] a smiling woman sitting at a table with several young children", "D": "[picture] a smiling young man holding a basketball above his head", "E": "[picture] a “TAXI” sign on the roof of a car", "F": "[picture] two smiling women behind the counter of a café with an “Open” sign"}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": 19, "zh": "学校离我家很近，我每天走着去上课。", "pinyin": "Xuéxiào lí wǒ jiā hěn jìn, wǒ měi tiān zǒuzhe qù shàng kè.", "options": {"A": "[picture] a smiling woman, man and boy preparing food together in a kitchen", "B": "[picture] a man walking, carrying a book under his arm", "C": "[picture] a smiling woman sitting at a table with several young children", "D": "[picture] a smiling young man holding a basketball above his head", "E": "[picture] a “TAXI” sign on the roof of a car", "F": "[picture] two smiling women behind the counter of a café with an “Open” sign"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": 20, "zh": "拿着这么多东西，我们还是坐出租车回家吧。", "pinyin": "Názhe zhème duō dōngxi, wǒmen háishi zuò chūzūchē huí jiā ba.", "options": {"A": "[picture] a smiling woman, man and boy preparing food together in a kitchen", "B": "[picture] a man walking, carrying a book under his arm", "C": "[picture] a smiling woman sitting at a table with several young children", "D": "[picture] a smiling young man holding a basketball above his head", "E": "[picture] a “TAXI” sign on the roof of a car", "F": "[picture] two smiling women behind the counter of a café with an “Open” sign"}, "answer": "E", "answer_ref": {"book": "teacher", "pages": [140]}}]}, {"n": "二、阅读 第二部分", "type_zh": "阅读 第二部分", "instruction_zh": "第21–25题：选择合适的词语填空", "instruction_en": "Questions 21-25: Choose the proper words to fill in the brackets.", "word_bank": [["A 拿 ná", "B 笑 xiào", "C 长 zhǎng", "D 往 wǎng", "E 贵 guì", "F 一直 yìzhí"]], "items": [{"n": "例", "zh": "这儿的羊肉很好吃，但是也很（________）。", "pinyin": "Zhèr de yángròu hěn hǎochī, dànshì yě hěn ______.", "answer": "E", "answer_ref": {"book": "workbook", "pages": [127]}}, {"n": 21, "zh": "妹妹是一个非常爱（________）的女孩儿。", "pinyin": "Mèimei shì yí ge fēicháng ài ______ de nǚháir.", "answer": "B", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": 22, "zh": "你手里（________）着的是什么东西，我能看看吗？", "pinyin": "Nǐ shǒuli ______ zhe de shì shénme dōngxi, wǒ néng kànkan ma?", "answer": "A", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": 23, "zh": "从这儿（________）右走，过一个路口，就是北京医院。", "pinyin": "Cóng zhèr ______ yòu zǒu, guò yí ge lùkǒu, jiù shì Běijīng Yīyuàn.", "answer": "D", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": 24, "zh": "你们班有没有一个（________）着大眼睛、爱穿红衣服的学生？", "pinyin": "Nǐmen bān yǒu méiyǒu yí ge ______ zhe dà yǎnjing, ài chuān hóng yīfu de xuésheng?", "answer": "C", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": 25, "zh": "从这个路口（________）走，就能看到你们学校了。", "pinyin": "Cóng zhège lùkǒu ______ zǒu, jiù néng kàndào nǐmen xuéxiào le.", "answer": "F", "answer_ref": {"book": "teacher", "pages": [140]}}]}, {"n": "二、阅读 第三部分", "type_zh": "阅读 第三部分", "instruction_zh": "第26–30题：判断下列句子的意思是否正确", "instruction_en": "Questions 26-30: Decide whether the inferences are true or false.", "items": [{"n": "例1", "zh": "现在是11点30分，他们已经游了20分钟了。 ★他们11点10分开始游泳。", "pinyin": "Xiànzài shì diǎn fēn, tāmen yǐjīng yóule fēnzhōng le. ★Tāmen diǎn fēn kāishǐ yóuyǒng.", "answer": "√", "answer_ref": {"book": "workbook", "pages": [127]}}, {"n": "例2", "zh": "我会跳舞，但跳得不怎么样。 ★我跳得非常好。", "pinyin": "Wǒ huì tiàowǔ, dàn tiào de bù zěnmeyàng. ★Wǒ tiào de fēicháng hǎo.", "answer": "×", "answer_ref": {"book": "workbook", "pages": [128]}}, {"n": 26, "zh": "大卫不是找到新工作了吗？怎么还天天在家玩儿电脑？ ★大卫每天工作。", "pinyin": "Dàwèi bú shì zhǎodào xīn gōngzuò le ma? Zěnme hái tiāntiān zài jiā wánr diànnǎo? ★Dàwèi měi tiān gōngzuò.", "answer": "×", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": 27, "zh": "我的一个朋友正在找房子，他希望住得离公司近一些。 ★他家离公司很远。", "pinyin": "Wǒ de yí ge péngyou zhèngzài zhǎo fángzi, tā xīwàng zhù de lí gōngsī jìn yìxiē. ★Tā jiā lí gōngsī hěn yuǎn.", "answer": "√", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": 28, "zh": "妈妈告诉我说，不要开着车听音乐。 ★开着车听音乐不好。", "pinyin": "Māma gàosu wǒ shuō, bú yào kāizhe chē tīng yīnyuè. ★Kāizhe chē tīng yīnyuè bù hǎo.", "answer": "√", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": 29, "zh": "从我家到北京，坐火车就5个小时，比坐飞机便宜多了。所以我明天准备坐火车去北京。 ★我正在坐火车去北京。", "pinyin": "Cóng wǒ jiā dào Běijīng, zuò huǒchē jiù ge xiǎoshí, bǐ zuò fēijī piányi duō le. Suǒyǐ wǒ míngtiān zhǔnbèi zuò huǒchē qù Běijīng. ★Wǒ zhèngzài zuò huǒchē qù Běijīng.", "answer": "×", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": 30, "zh": "李哥，你手里拿着的是电影票吗？我也想跟你一起去看电影。 ★李哥可能有电影票。", "pinyin": "Lǐ gē, nǐ shǒuli názhe de shì diànyǐngpiào ma? Wǒ yě xiǎng gēn nǐ yìqǐ qù kàn diànyǐng. ★Lǐ gē kěnéng yǒu diànyǐngpiào.", "answer": "√", "answer_ref": {"book": "teacher", "pages": [140]}}]}, {"n": "二、阅读 第四部分", "type_zh": "阅读 第四部分", "instruction_zh": "第31–35题：选择合适的问答", "instruction_en": "Questions 31-35: Match the sentences to make dialogues.", "items": [{"n": "例", "zh": "他还在教室里学习。 (He is still studying in the classroom.)", "pinyin": "Tā hái zài jiàoshì li xuéxí.", "options": {"A": "是给我妈妈买的新衣服，明天是她的生日。 Shì gěi wǒ māma mǎi de xīn yīfu, míngtiān shì tā de shēngrì.", "B": "他开着车出去了。下午可能回来。 Tā kāizhe chē chūqu le. Xiàwǔ kěnéng huílai.", "C": "大卫也想跟我们一起去。 Dàwèi yě xiǎng gēn wǒmen yìqǐ qù.", "D": "不是两年，是一年半。 Bú shì liǎng nián, shì yì nián bàn.", "E": "他在哪儿呢？你看见他了吗？ Tā zài nǎr ne? Nǐ kànjiàn tā le ma?", "F": "教室前面还有一位老师，他正在给学生们上课呢。 Jiàoshì qiánmian hái yǒu yí wèi lǎoshī, tā zhèngzài gěi xuéshengmen shàng kè ne."}, "answer": "E", "answer_ref": {"book": "workbook", "pages": [129]}}, {"n": 31, "zh": "我看见在教室里坐着很多学生。", "pinyin": "Wǒ kànjiàn zài jiàoshì li zuòzhe hěn duō xuésheng.", "options": {"A": "是给我妈妈买的新衣服，明天是她的生日。 Shì gěi wǒ māma mǎi de xīn yīfu, míngtiān shì tā de shēngrì.", "B": "他开着车出去了。下午可能回来。 Tā kāizhe chē chūqu le. Xiàwǔ kěnéng huílai.", "C": "大卫也想跟我们一起去。 Dàwèi yě xiǎng gēn wǒmen yìqǐ qù.", "D": "不是两年，是一年半。 Bú shì liǎng nián, shì yì nián bàn.", "E": "他在哪儿呢？你看见他了吗？ Tā zài nǎr ne? Nǐ kànjiàn tā le ma?", "F": "教室前面还有一位老师，他正在给学生们上课呢。 Jiàoshì qiánmian hái yǒu yí wèi lǎoshī, tā zhèngzài gěi xuéshengmen shàng kè ne."}, "answer": "F", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": 32, "zh": "你手里拿着什么？", "pinyin": "Nǐ shǒu li názhe shénme?", "options": {"A": "是给我妈妈买的新衣服，明天是她的生日。 Shì gěi wǒ māma mǎi de xīn yīfu, míngtiān shì tā de shēngrì.", "B": "他开着车出去了。下午可能回来。 Tā kāizhe chē chūqu le. Xiàwǔ kěnéng huílai.", "C": "大卫也想跟我们一起去。 Dàwèi yě xiǎng gēn wǒmen yìqǐ qù.", "D": "不是两年，是一年半。 Bú shì liǎng nián, shì yì nián bàn.", "E": "他在哪儿呢？你看见他了吗？ Tā zài nǎr ne? Nǐ kànjiàn tā le ma?", "F": "教室前面还有一位老师，他正在给学生们上课呢。 Jiàoshì qiánmian hái yǒu yí wèi lǎoshī, tā zhèngzài gěi xuéshengmen shàng kè ne."}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": 33, "zh": "张先生呢？我今天怎么没看见他？", "pinyin": "Zhāng xiānsheng ne? Wǒ jīntiān zěnme méi kànjiàn tā?", "options": {"A": "是给我妈妈买的新衣服，明天是她的生日。 Shì gěi wǒ māma mǎi de xīn yīfu, míngtiān shì tā de shēngrì.", "B": "他开着车出去了。下午可能回来。 Tā kāizhe chē chūqu le. Xiàwǔ kěnéng huílai.", "C": "大卫也想跟我们一起去。 Dàwèi yě xiǎng gēn wǒmen yìqǐ qù.", "D": "不是两年，是一年半。 Bú shì liǎng nián, shì yì nián bàn.", "E": "他在哪儿呢？你看见他了吗？ Tā zài nǎr ne? Nǐ kànjiàn tā le ma?", "F": "教室前面还有一位老师，他正在给学生们上课呢。 Jiàoshì qiánmian hái yǒu yí wèi lǎoshī, tā zhèngzài gěi xuéshengmen shàng kè ne."}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": 34, "zh": "下午三点，你在学校门口等着我。我们一起去打篮球。", "pinyin": "Xiàwǔ sān diǎn, nǐ zài xuéxiào ménkǒu děngzhe wǒ. Wǒmen yìqǐ qù dǎ lánqiú.", "options": {"A": "是给我妈妈买的新衣服，明天是她的生日。 Shì gěi wǒ māma mǎi de xīn yīfu, míngtiān shì tā de shēngrì.", "B": "他开着车出去了。下午可能回来。 Tā kāizhe chē chūqu le. Xiàwǔ kěnéng huílai.", "C": "大卫也想跟我们一起去。 Dàwèi yě xiǎng gēn wǒmen yìqǐ qù.", "D": "不是两年，是一年半。 Bú shì liǎng nián, shì yì nián bàn.", "E": "他在哪儿呢？你看见他了吗？ Tā zài nǎr ne? Nǐ kànjiàn tā le ma?", "F": "教室前面还有一位老师，他正在给学生们上课呢。 Jiàoshì qiánmian hái yǒu yí wèi lǎoshī, tā zhèngzài gěi xuéshengmen shàng kè ne."}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": 35, "zh": "你不是学过两年汉语吗？", "pinyin": "Nǐ bú shì xuéguo liǎng nián Hànyǔ ma?", "options": {"A": "是给我妈妈买的新衣服，明天是她的生日。 Shì gěi wǒ māma mǎi de xīn yīfu, míngtiān shì tā de shēngrì.", "B": "他开着车出去了。下午可能回来。 Tā kāizhe chē chūqu le. Xiàwǔ kěnéng huílai.", "C": "大卫也想跟我们一起去。 Dàwèi yě xiǎng gēn wǒmen yìqǐ qù.", "D": "不是两年，是一年半。 Bú shì liǎng nián, shì yì nián bàn.", "E": "他在哪儿呢？你看见他了吗？ Tā zài nǎr ne? Nǐ kànjiàn tā le ma?", "F": "教室前面还有一位老师，他正在给学生们上课呢。 Jiàoshì qiánmian hái yǒu yí wèi lǎoshī, tā zhèngzài gěi xuéshengmen shàng kè ne."}, "answer": "D", "answer_ref": {"book": "teacher", "pages": [140]}}]}, {"n": "三、语音 第一部分", "type_zh": "语音 第一部分 听录音", "instruction_zh": "第1题：听录音，注意句末的升降调", "instruction_en": "Question 1: Listen to the recording and pay attention to the intonation at the end of each sentence.", "items": [{"n": "1-(1)", "zh": "老师，下课吧。↘", "pinyin": "Lǎoshī, xià kè ba.", "transcript_zh": "老师，下课吧。"}, {"n": "1-(2)", "zh": "周末大家好好儿休息吧。↘", "pinyin": "Zhōumò dàjiā hǎohāor xiūxi ba.", "transcript_zh": "周末大家好好儿休息吧。"}, {"n": "1-(3)", "zh": "七点半了，快起床吧。↘", "pinyin": "Qī diǎn bàn le, kuài qǐ chuáng ba.", "transcript_zh": "七点半了，快起床吧。"}, {"n": "1-(4)", "zh": "别说话了，快点儿吃饭。↘", "pinyin": "Bié shuōhuà le, kuàidiǎnr chī fàn.", "transcript_zh": "别说话了，快点儿吃饭。"}]}, {"n": "三、语音 第二部分", "type_zh": "语音 第二部分 跟读", "instruction_zh": "第2题：听录音并跟读下列句子，注意句末的升降调", "instruction_en": "Question 2: Listen to the recording and repeat the following sentences, paying attention to the intonation at the end of each sentence.", "items": [{"n": "2-(1)", "zh": "天气真好，一起去运动运动吧。↘", "pinyin": "Tiānqì zhēn hǎo, yìqǐ qù yùndòng yùndòng ba.", "transcript_zh": "天气真好，一起去运动运动吧。"}, {"n": "2-(2)", "zh": "下雨了，快回家吧。↘", "pinyin": "Xià yǔ le, kuài huí jiā ba.", "transcript_zh": "下雨了，快回家吧。"}, {"n": "2-(3)", "zh": "老师来了，别说话了。↘", "pinyin": "Lǎoshī lái le, bié shuōhuà le.", "transcript_zh": "老师来了，别说话了。"}, {"n": "2-(4)", "zh": "请进房间里休息一下儿吧。↘", "pinyin": "Qǐng jìn fángjiān li xiūxi yíxiàr ba.", "transcript_zh": "请进房间里休息一下儿吧。"}]}, {"n": "四、汉字 第一部分", "type_zh": "汉字 偏旁归类", "instruction_zh": "第1–2题：看汉字，按偏旁归类", "instruction_en": "Questions 1-2: Group the characters with the same radical.", "word_bank": [["A 新", "B 颜", "C 所", "D 额"], ["E 斧", "F 须", "G 忻", "H 项"]], "items": [{"n": 1, "zh": "斤：________", "answer": "A C E G", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": 2, "zh": "页：________", "answer": "B D F H", "answer_ref": {"book": "teacher", "pages": [140]}}]}, {"n": "四、汉字 第二部分", "type_zh": "汉字 猜词义", "instruction_zh": "第3题：看生词和图片，猜出词义", "instruction_en": "Question 3: Guess the meaning of each word based on the new words and pictures.", "word_bank": [["钢笔", "毛笔", "铅笔", "画笔"]], "items": [{"n": "3-钢笔", "zh": "钢笔 ________", "options": {"A": "[picture] a pencil", "B": "[picture] Chinese writing brushes hanging on a brush rack", "C": "[picture] the nib of a fountain pen", "D": "[picture] several paintbrushes lying together"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": "3-毛笔", "zh": "毛笔 ________", "options": {"A": "[picture] a pencil", "B": "[picture] Chinese writing brushes hanging on a brush rack", "C": "[picture] the nib of a fountain pen", "D": "[picture] several paintbrushes lying together"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": "3-铅笔", "zh": "铅笔 ________", "options": {"A": "[picture] a pencil", "B": "[picture] Chinese writing brushes hanging on a brush rack", "C": "[picture] the nib of a fountain pen", "D": "[picture] several paintbrushes lying together"}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [140]}}, {"n": "3-画笔", "zh": "画笔 ________", "options": {"A": "[picture] a pencil", "B": "[picture] Chinese writing brushes hanging on a brush rack", "C": "[picture] the nib of a fountain pen", "D": "[picture] several paintbrushes lying together"}, "answer": "D", "answer_ref": {"book": "teacher", "pages": [140]}}]}], "answers_ref": {"book": "teacher", "pages": [139, 140]}}, "unclear": ["Сурах бичиг PDF х.118 生词 хүснэгтэд 铅笔-ийн пиньинь «qiānbǐn» гэж хэвлэгдсэн (илүү «n»), харин 课文2-ын мөр болон 热身 (PDF х.117)-д «qiānbǐ» — номд байгаагаар new_words-д «qiānbǐn» гэж бичсэн.", "Нэр томьёоны зөрүү: сурах бичиг (PDF х.120 注释1, х.124 小组活动) «结构助词“着”» / «The Structural Particle»; багшийн ном (PDF х.94 教学目标, х.96 语言点, х.100 本课小结) «动态助词“着”» — номд байгаагаар.", "Багшийн ном PDF х.96 语言点(1) 句型框-ийн хоёр дахь мөр «主语＋没（有）＋动词＋着＋定语» — эхний мөрөнд «宾语», энд «定语» гэж хэвлэгдсэн; номд байгаагаар.", "Сурах бичиг PDF х.101 注释2 жишээ (3) (улаанаар, 课文3-аас) «她不是有男朋友了吗？» — 课文3 (PDF х.119)-ийн мөр «她不是有男朋友吗？» («了»-гүй). Номд байгаагаар хоёуланг нь.", "Сурах бичиг PDF х.120 注释1 хүснэгт: эхний хүснэгтийн «（她）拿着铅笔。» мөр улаанаар (课文2-оос), жишээ (3) болон 注释3 жишээ (3) улаанаар — 课文-ээс авсан өгүүлбэр; structure_rows ба examples-д энгийнээр оруулсан. Хүснэгтийн O нүд хоосон мөрүүдэд « | » үлдээсэн.", "Сурах бичиг (PDF х.123) ба багшийн ном (PDF х.94, 99, 100) — 偏旁 «斤字旁» нь 新/所 дахь зүүн/баруун талын нарийн хэлбэрээр хэвлэгдсэн; тусдаа Unicode тэмдэгт хэрэглээгүй, JSON-д «斤» гэж бичсэн.", "Багшийн ном PDF х.99 汉字 补充练习 c: бүрэлдэхүүн «合 ⺮ 宀 毛 主 兵 彳 手» — 2 дахь нь 竹字头 (⺮), 3 дахь нь 宝盖 (宀) хэлбэрээр харагдсан; a (找出), b (拆分), c (组合) даалгаврын хариулт хэвлэгдээгүй.", "Сурах бичгийн 热身2 (动词加宾语), 练习2 回答问题, 练习3 描述图片, 运用 双人活动/小组活动 — хариулт хэвлэгдээгүй. 热身1-ийн хариулт зөвхөн багшийн номд (PDF х.95): ①C ②A ③F ④E ⑤B ⑥D; 热身2-т багшийн ном зөвхөн «下课 下车 下飞机 ……» жишээ өгсөн.", "语音 (сурах бичиг PDF х.122, дасгалын ном PDF х.130, багшийн ном PDF х.99): өгүүлбэрийн төгсгөлийн уналтыг муруй сумаар тэмдэглэсэн; JSON-д «↘» гэж бичсэн (номд текстээр тайлбар байхгүй). Энэ хичээлийн 语音 жишээнд 重读 цэг байхгүй. Сурах бичгийн тайлбар «第一个分句末尾语调略升» гэсэн боловч жишээ 3 нь бүгд нэг өгүүлбэр; дасгалын номд хоёр хэсэгтэй өгүүлбэрүүд ч зөвхөн төгсгөлд нэг сумтай.", "Багшийн номын 课文 асуултууд (PDF х.97–98) «B想找谁», «A在做什么呢», «B有女朋友了吗» гэх мэт A/B-ээр; 课文1 асуулт «张先生什么时候回来？» — 课文-д «你下午再来吧» л байгаа. Номд байгаагаар.", "Багшийн ном PDF х.95 生词 扩展: «（大卫的女朋友）就是我们班那个长着两个大眼睛、非常爱笑的女孩儿。» — «、» тэмдэгтэй, сурах бичгийн 课文3 (PDF х.119)-д «，». Мөн PDF х.97 «那个正在说话的女孩不是你姐姐吗？» — «女孩» («儿»-гүй). Номд байгаагаар.", "Багшийн номын 练习册相关练习 лавлагаа (第115页, 第118-119页, 第122页, 第123页) — дасгалын номын хэвлэсэн хуудасны дугаар (PDF х.123, 126–127, 130, 131); 课本第102/103/104页 — сурах бичгийн хэвлэсэн дугаар (PDF х.122/123/124).", "Дасгалын номын 听力 бичвэр (transcript_zh) — багшийн номын хавсралт PDF х.139–140-өөс (1–11 нь х.139, 12–15 нь х.140); бүх хариулт (参考答案) PDF х.140. 例-ийн хариулт дасгалын номд өөрт нь хэвлэгдсэн. 三、语音 хэсэгт хариулт шаардлагагүй.", "Дасгалын ном PDF х.127 阅读 第三部分 例1, PDF х.128 (29)-ийн пиньинь мөрөнд тоонууд (11, 30, 20, 10; 5) орхигдсон — номд байгаагаар.", "Дасгалын ном PDF х.126 (18): «妈妈笑着说：“今天给你们做了很多好吃的东西”。» — цэг хашилтын гадна; пиньинь «Māma xiàozhe shuō “jīntiān …”.» (хоёр цэг байхгүй) — номд байгаагаар.", "Дасгалын номын 三、语音 болон 四、汉字 хэсгийн дугаарлалт 1-ээс дахин эхэлдэг; 语音 1–2 асуулт тус бүр 4 өгүүлбэртэй тул n «1-(1)» гэх мэт. 四、汉字 第二部分 — n «3-钢笔» гэх мэт.", "Аудио файлын нэр мэдэгдэхгүй тул audio талбар орхисон. Номын CD тэмдэг: сурах бичиг 课文1–4 = 13-1…13-4, 语音 13-5; дасгалын ном 听力 13-1, 语音 13-2.", "Энэ хичээлд 课堂用语, 汉字 独体字/笔顺, 俗语, 文化 хэсэг байхгүй (汉字 — зөвхөн 偏旁). Багшийн номд тусдаа 注意/辨析 хэсэг байхгүй тул notes_zh хоосон.", "Сурах бичгийн 生词 «*» тэмдэгтэй: 拿, 班, 长, 一直 (star=true).", "Зургийн тайлбарууд (picture_desc_en, pictures_desc_en, options «[picture]», 小组活动-ийн «［picture］») зургаас товч, объектив дүрсэлсэн."], "verified_pages": [94, 95, 96, 97, 98, 99, 100, 117, 118, 119, 120, 121, 122, 123, 124, 125, 126, 127, 128, 129, 130, 131, 139, 140], "schema_version": 1}'::jsonb, 1, 'image_verified')
on conflict (id) do update set book=excluded.book, title_zh=excluded.title_zh, title_pinyin=excluded.title_pinyin, title_en=excluded.title_en, payload=excluded.payload, schema_version=excluded.schema_version, status=excluded.status;
insert into public.hsk_source_lessons (id, level, book, lesson, title_zh, title_pinyin, title_en, payload, schema_version, status)
values ('hsk2-l14', 'hsk2', 'HSK2', 14, '你看过那个电影吗', 'Nǐ kànguo nàge diànyǐng ma', 'Have you seen that movie', '{"level": "hsk2", "lesson": 14, "book": "HSK2", "title_zh": "你看过那个电影吗", "title_pinyin": "Nǐ kànguo nàge diànyǐng ma", "title_en": "Have you seen that movie", "textbook": {"ref": {"book": "textbook", "pages": [125, 126, 127, 128, 129, 130, 131, 132]}, "warmup": [{"instruction_zh": "给下面的词语选择对应的图片", "instruction_en": "Match the pictures with the words/phrases.", "items": ["①电影院 diànyǐngyuàn", "②等 děng", "③晴 qíng", "④一百 yìbǎi", "⑤打电话 dǎ diànhuà", "⑥玩儿 wánr"], "pictures_desc_en": ["A: a man in a suit sitting on a park bench, looking at his wristwatch, high-rise buildings behind", "B: a baby lying on its front playing with a toy among letter blocks", "C: a hand holding a telephone handset while another hand presses the keypad", "D: an empty cinema hall: rows of seats facing a large screen", "E: a white sail against a clear blue sky", "F: the red number “100”"]}, {"instruction_zh": "看下面的图片，用汉语说出它们的名字", "instruction_en": "Look at the pictures and say the names of the things in Chinese.", "items": ["①________", "②________", "③________", "④________"], "pictures_desc_en": ["①: a flat-screen television", "②: a strip of film frames numbered 1 and 2 with a clapperboard", "③: a telephone with a handset and push-button keypad", "④: a desktop computer with monitor, tower case, keyboard and mouse"]}], "pronunciation": [{"title_zh": "感叹句的句调", "rows": ["Jīntiān tiānqì zhēn hǎo a! （1）今天天气真好啊！↘", "Zhège Hànzì zhēn nán xiě a! （2）这个汉字真难写啊！↘", "Zhè jiàn yīfu tài piàoliang le! （3）这件衣服太漂亮了！↘"], "notes_zh": ["汉语感叹句的句调一般为降调。例如：", "“↘”为书中句末的下降箭头（书中无文字说明）。"], "notes_en": ["Intonation of an Exclamatory Sentence", "A Chinese exclamatory sentence usually has a falling intonation. For example:"]}], "texts": [{"n": 1, "title_zh": "在教室", "title_en": "In the classroom", "kind": "dialogue", "lines": [{"speaker": "A", "zh": "你看过那个电影没有？", "pinyin": "Nǐ kànguo nàge diànyǐng méiyǒu?"}, {"speaker": "B", "zh": "没看过，听说很有意思。", "pinyin": "Méi kànguo, tīngshuō hěn yǒu yìsi."}, {"speaker": "A", "zh": "那我们下个星期一起去看吧？", "pinyin": "Nà wǒmen xià ge xīngqī yìqǐ qù kàn ba?"}, {"speaker": "B", "zh": "可以，但是我女朋友也想去。", "pinyin": "Kěyǐ, dànshì wǒ nǚpéngyou yě xiǎng qù."}], "english_version": "A: Have you seen that movie?\nB: No. I was told it is fantastic.\nA: Why don’t we see it together next week?\nB: OK. But my girlfriend also wants to go.", "new_words": [{"n": 1, "zh": "有意思", "pinyin": "yǒu yìsi", "en": "interesting, fun", "text": 1}, {"n": 2, "zh": "但是", "pinyin": "dànshì", "pos": "conj.", "en": "but, still, yet", "text": 1}]}, {"n": 2, "title_zh": "在办公室", "title_en": "In the office", "kind": "dialogue", "lines": [{"speaker": "A", "zh": "听说你去过中国，还想去吗？", "pinyin": "Tīngshuō nǐ qùguo Zhōngguó, hái xiǎng qù ma?"}, {"speaker": "B", "zh": "我虽然去过好几次，但是还想再去玩儿玩儿。", "pinyin": "Wǒ suīrán qùguo hǎojǐ cì, dànshì hái xiǎng zài qù wánrwanr."}, {"speaker": "A", "zh": "那我们一起去吧。", "pinyin": "Nà wǒmen yìqǐ qù ba."}, {"speaker": "B", "zh": "好啊，到时候我给你打电话。", "pinyin": "Hǎo a, dào shíhou wǒ gěi nǐ dǎ diànhuà."}], "english_version": "A: It’s said you’ve been to China. Do you want to go there again?\nB: Though I’ve been there several times, I still want to go for pleasure again.\nA: Let’s go together.\nB: Great. I’ll call you then.", "new_words": [{"n": 3, "zh": "虽然", "pinyin": "suīrán", "pos": "conj.", "en": "although, though", "text": 2}, {"n": 4, "zh": "次", "pinyin": "cì", "pos": "m.", "en": "time", "text": 2}, {"n": 5, "zh": "玩儿", "pinyin": "wánr", "pos": "v.", "en": "to play, to have fun", "text": 2}]}, {"n": 3, "title_zh": "在房间", "title_en": "In the room", "kind": "dialogue", "lines": [{"speaker": "A", "zh": "明天天气怎么样？", "pinyin": "Míngtiān tiānqì zěnmeyàng?"}, {"speaker": "B", "zh": "虽然是晴天，但是很冷。", "pinyin": "Suīrán shì qíngtiān, dànshì hěn lěng."}, {"speaker": "A", "zh": "那还能去跑步吗？", "pinyin": "Nà hái néng qù pǎo bù ma?"}, {"speaker": "B", "zh": "可以，但是你自己去吧，我还有很多事情要做。", "pinyin": "Kěyǐ, dànshì nǐ zìjǐ qù ba, wǒ hái yǒu hěn duō shìqing yào zuò."}], "english_version": "A: How will the weather be tomorrow?\nB: It will be fine, but cold.\nA: In that case, is it OK to go jogging?\nB: I think so. But I’m afraid you have to go by yourself because I have a lot of work to do.", "new_words": [{"n": 6, "zh": "晴", "pinyin": "qíng", "pos": "adj.", "en": "sunny, fine, clear", "text": 3}]}, {"n": 4, "title_zh": "在商店", "title_en": "In a store", "kind": "dialogue", "lines": [{"speaker": "A", "zh": "你在这个商店买过东西没有？", "pinyin": "Nǐ zài zhège shāngdiàn mǎiguo dōngxi méiyǒu?"}, {"speaker": "B", "zh": "买过一次，这儿的东西还可以，就是不便宜。", "pinyin": "Mǎiguo yí cì, zhèr de dōngxi hái kěyǐ, jiùshì bù piányi."}, {"speaker": "A", "zh": "我喜欢这件衣服，但是觉得有点儿贵。", "pinyin": "Wǒ xǐhuan zhè jiàn yīfu, dànshì juéde yǒudiǎnr guì."}, {"speaker": "B", "zh": "两百块还可以，喜欢就买吧。", "pinyin": "Liǎngbǎi kuài hái kěyǐ, xǐhuan jiù mǎi ba."}], "english_version": "A: Have you ever bought anything in this store?\nB: Yes, once. Things here are pretty good, not cheap though.\nA: I like this garment, but I think it’s a little expensive.\nB: Two hundred yuan is not that expensive. If you like it, just buy it.", "new_words": [{"n": 7, "zh": "百", "pinyin": "bǎi", "pos": "num.", "en": "hundred", "text": 4}]}], "grammar": [{"n": 1, "title_zh": "结构助词“过”", "title_en": "The Structural Particle “过”", "explanation_zh": "动词后加上结构助词“过”，一般用来表示过去有过的经历，这些动作行为没有持续到现在。例如：\n在动词前边加“没（有）”表示否定。例如：\n在句末加“没有”表示疑问。例如：", "explanation_en": "A verb followed by the structural particle “过” usually indicates a past experience action which hasn’t lasted to the present. For example:\nIn the negative form, “没（有）” is added before the verb. For example:\nIn the interrogative form, “没有” is added at the end of the sentence. For example:", "structure_rows": ["Subject | Predicate: V | 过 | O", "他们 | 来 | 过 | 我家。", "我 | 看 | 过 | 那个电影。", "我 | 去 | 过 | 中国。", "Subject | Predicate: 没（有）＋V | 过 | O", "他们 | 没（有）来 | 过 | 我家。", "我 | 没（有）看 | 过 | 那个电影。", "我 | 没（有）去 | 过 | 中国。", "Subject | Predicate: V | 过 | O＋没有", "他们 | 来 | 过 | 你家没有？", "你 | 看 | 过 | 那个电影没有？", "你 | 去 | 过 | 中国没有？"], "examples": [{"n": 1, "zh": "他们来过我家。"}, {"n": 2, "zh": "我看过那个电影。"}, {"n": 3, "zh": "我去过中国。"}, {"n": 4, "zh": "他们没（有）来过我家。"}, {"n": 5, "zh": "我没（有）看过那个电影。"}, {"n": 6, "zh": "我没（有）去过中国。"}, {"n": 7, "zh": "他们来过你家没有？"}, {"n": 8, "zh": "你看过那个电影没有？"}, {"n": 9, "zh": "你去过中国没有？"}]}, {"n": 2, "title_zh": "关联词“虽然……，但是……”", "title_en": "The Pair of Conjunctions “虽然……，但是……”", "explanation_zh": "“虽然……，但是……”连接两个分句，构成一种转折关系。例如：", "explanation_en": "The conjunctions “虽然……，但是……” connect two clauses, forming a complex sentence indicating an adversative relation. For example:", "examples": [{"n": 1, "zh": "虽然外面很冷，但是房间里很热。"}, {"n": 2, "zh": "虽然汉字很难，但是我很喜欢写汉字。"}, {"n": 3, "zh": "虽然是晴天，但是很冷。"}]}, {"n": 3, "title_zh": "动量补语“次”", "title_en": "The Complement of Frequency “次”", "explanation_zh": "动量补语“次”常放在谓语动词的后边，用来表示动作发生、进行的次数。例如：\n宾语是表示地点的名词时，动量补语可以放在宾语前，也可以放在宾语后。例如：\n宾语是人称代词时，动量补语要放在宾语后。例如：", "explanation_en": "The complement of frequency “次” is usually used after the predicate verb, indicating the number of times that an action has taken place. For example:\nWhen the object of a verb is a place, the complement of frequency can be put either before or after the object. For example:\nWhen the object is a personal pronoun, the complement of frequency should be put after the object. For example:", "structure_rows": ["Subject | Predicate: V | 过 | Num＋次 | O", "我们 | 看 | 过 | 三次 | 电影。", "他们 | 坐 | 过 | 一次 | 飞机。", "我 | （在这个商店）买 | 过 | 一次 | （东西）。", "Subject | Predicate: V | 过 | Num＋次 | O", "我们 | 去 | 过 | 三次 | 北京。", "他们 | 来 | 过 | 一次 | 中国。", "我 | （上星期）去 | 过 | 一次 | 医院。", "Subject | Predicate: V | 过 | O | Num＋次", "我们 | 去 | 过 | 北京 | 三次。", "他们 | 来 | 过 | 中国 | 一次。", "我 | （上星期）去 | 过 | 医院 | 一次。", "Subject | Predicate: V | 过 | O | Num＋次", "我们 | 找 | 过 | 他 | 三次。", "他们 | 看 | 过 | 我 | 一次。", "老师 | 叫 | 过 | 我 | 两次。"], "examples": [{"n": 1, "zh": "我们看过三次电影。"}, {"n": 2, "zh": "他们坐过一次飞机。"}, {"n": 3, "zh": "我（在这个商店）买过一次（东西）。"}, {"n": 4, "zh": "我们去过三次北京。"}, {"n": 5, "zh": "他们来过一次中国。"}, {"n": 6, "zh": "我（上星期）去过一次医院。"}, {"n": 7, "zh": "我们去过北京三次。"}, {"n": 8, "zh": "他们来过中国一次。"}, {"n": 9, "zh": "我（上星期）去过医院一次。"}, {"n": 10, "zh": "我们找过他三次。"}, {"n": 11, "zh": "他们看过我一次。"}, {"n": 12, "zh": "老师叫过我两次。"}]}], "exercises": [{"n": 1, "type_zh": "分角色朗读课文", "instruction_zh": "分角色朗读课文", "instruction_en": "Role-play the dialogs.", "items": []}, {"n": 2, "type_zh": "回答问题", "instruction_zh": "根据课文内容回答问题", "instruction_en": "Answer the questions based on the dialogs.", "items": [{"n": 1, "zh": "他们看过那个电影吗？", "pinyin": "Tāmen kànguo nàge diànyǐng ma?"}, {"n": 2, "zh": "他们想几个人去看电影？", "pinyin": "Tāmen xiǎng jǐ ge rén qù kàn diànyǐng?"}, {"n": 3, "zh": "他们想来中国做什么？", "pinyin": "Tāmen xiǎng lái Zhōngguó zuò shénme?"}, {"n": 4, "zh": "为什么她明天不能去跑步？", "pinyin": "Wèi shénme tā míngtiān bù néng qù pǎo bù?"}, {"n": 5, "zh": "女的觉得这个商店的东西怎么样？", "pinyin": "Nǚde juéde zhège shāngdiàn de dōngxi zěnmeyàng?"}]}, {"n": 3, "type_zh": "描述图片", "instruction_zh": "用本课新学的语言点和词语描述图片", "instruction_en": "Describe the pictures using the newly-learned language points and words.", "items": [{"n": 1, "zh": "你以前________这种水果吗？", "pinyin": "Nǐ yǐqián ______ zhè zhǒng shuǐguǒ ma?", "picture_desc_en": "a pile of red cherries with stems on a wooden surface"}, {"n": 2, "zh": "我去年________你姐姐一次。", "pinyin": "Wǒ qùnián ______ nǐ jiějie yí cì.", "picture_desc_en": "a smiling blonde woman in a white top, hand at her chin, tall grass behind her"}, {"n": 3, "zh": "虽然天气很冷，但是他________。", "pinyin": "Suīrán tiānqì hěn lěng, dànshì tā ______.", "picture_desc_en": "a swimmer in a red swimming cap doing the front crawl in a pool"}, {"n": 4, "zh": "虽然英语很难，但是她________。", "pinyin": "Suīrán Yīngyǔ hěn nán, dànshì tā ______.", "picture_desc_en": "a young woman with glasses reading a large open book in front of bookshelves"}]}], "characters": {"knowledge_title_zh": "汉字偏旁“⻗”和“贝”", "knowledge_zh": "偏旁 | 解释 | 例字\n⻗ | 雨字头，一般与云、雨等天气现象有关系。 | 雪 xuě、雾 wù\n贝 | 贝字旁，一般与钱财、鼎类器物有关系。 | 财 cái、货 huò", "knowledge_en": "Chinese Radicals: “⻗” and “贝” — The radical “⻗”, appearing at the top of a character, is usually related to such weather phenomena as clouds and rain: 雪 xuě snow; 雾 wù fog, mist. The radical “贝” is usually related to money or utensils like an ancient cooking vessel: 财 cái wealth, money; 货 huò goods, commodity.", "characters": [{"zh": "雪", "pinyin": "xuě", "note_zh": "偏旁“⻗（雨字头）”例字（snow）"}, {"zh": "雾", "pinyin": "wù", "note_zh": "偏旁“⻗（雨字头）”例字（fog, mist）"}, {"zh": "财", "pinyin": "cái", "note_zh": "偏旁“贝（贝字旁）”例字（wealth, money）"}, {"zh": "货", "pinyin": "huò", "note_zh": "偏旁“贝（贝字旁）”例字（goods, commodity）"}]}, "application": [{"title_zh": "双人活动", "instruction_zh": "两人一组，用“虽然A，但是B”练习说句子，其中一个人说A，另一个人说B。然后两人互换。", "instruction_en": "Work in pairs and make sentences using “虽然A，但是B”. One says A and the other says B. Then switch the roles.", "example_zh": ["例如：A：虽然这件衣服很漂亮， Suīrán zhè jiàn yīfu hěn piàoliang,", "B：但是太贵了，我没钱买。 dànshì tài guì le, wǒ méi qián mǎi.", "A：虽然今天天气很冷， Suīrán jīntiān tiānqì hěn lěng,", "B：……"]}, {"title_zh": "小组活动", "instruction_zh": "3～4人一组，用结构助词“过”叙述自己在中国经历过的事情，尽量使用学过的词语。每组请一位同学报告情况。", "instruction_en": "Work in groups of 3-4. Describe your experiences in China using the structural particle “过” with the words you’ve learned. Each group chooses a member to make a report.", "example_zh": ["表格：（序号） | 经历过的事情 Your Experiences", "1 | 我在北京买过一件很漂亮的衣服。 Wǒ zài Běijīng mǎiguo yí jiàn hěn piàoliang de yīfu.", "（另有3行空白）"]}]}, "teacher": {"ref": {"book": "teacher", "pages": [101, 102, 103, 104, 105, 106, 107]}, "objectives_zh": ["重点词语：学生能够熟练掌握“有意思、玩儿、晴、百”的词义和用法", "语言点：学生能够了解并掌握：（1）动态助词“过”（2）关联词“虽然……，但是……”（3）动量补语“次”", "语音：学生能够掌握感叹句的句调，并能正确朗读", "汉字：学生能够：（1）熟练认读本课生词（2）了解“⻗（雨字头）、贝（贝字旁）”所表示的意思", "功能：学生能够：（1）表达过去的经历（动态助词“过”）（2）表达先让步，然后转折的逻辑（虽然……，但是……）（3）表达动作发生、进行的次数（动量补语“次”）"], "steps": [{"title_zh": "一 复习旧课", "body_zh": "1. 教师出示第13课生词卡片，要求学生快速认读下列生词：\n手、拿、铅笔、班、长、宾馆、一直、往、路口\n2. 教师带领学生辨析下列字形相近的汉字：\n笑____　住____　路____　铅____\n笔____　往____　跑____　识____\n3. 教师根据第13课重点内容，要求学生快速回答问题：\n大卫穿着什么颜色的衣服？\n手里拿着手机的那个人是谁？\n那个长着两个大眼睛的女孩是你的同学吗？\n你认识那个坐着学习的人吗？\n你能告诉我怎么去图书馆吗？\n这儿离医院远不远？你能告诉我怎么走吗？"}, {"title_zh": "二 学习新课 1 热身", "body_zh": "热身1：教师先带领学生根据图片选出正确的词语，然后分组练习。一组学生看图片说出正确的词语；另一组学生看词语，说出图片的编号。\n答案：①D　②A　③E　④F　⑤C　⑥B\n热身2：教师说出编号，让学生用汉语说出它们的名字。\n参考答案：①电视　②电影　③电话　④电脑"}, {"title_zh": "2 生词", "body_zh": "（1）生词快速认读及正音\n有意思、但是、虽然、次、玩儿、晴、百\n• 教师可以用PPT依次快速展示生词；\n• 教师领读，学生齐读；\n• 学生接龙式读一遍，每人读两个。\n（2）重点生词扩展及常用搭配\n有意思—很有意思—非常有意思—没（有）意思—有意思的书\n　—那个电影很有意思，星期天一起去看看吧？\n　—我觉得这本新买的书没意思。\n　—听说（这个电影）很有意思。\n玩儿—好玩儿—玩儿一会儿—玩儿电脑—玩儿玩儿\n　—这个周末不太忙，一起去玩儿吧。\n　—我告诉他不要每天晚上玩儿电脑。\n　—我虽然去过好几次，但是还想再去玩儿玩儿。\n晴—晴天\n　—你看，今天是晴天。\n　—我看电视上说明天晴，天气很好。\n　—虽然是晴天，但是很冷。\n百—两百—两百多—不到两百\n　—这个学校的学生不多，只有两百人。\n　—那件红色的衣服两百多块，不太贵。\n　—两百块还可以，喜欢就买吧。\n练习册相关练习：第124页／一／第一部分，第127-128页／二／第一、二部分"}, {"title_zh": "3 语言点（1）动态助词“过”", "body_zh": "① 语言点解析：\n动态助词“过”表示曾经发生某一动作或存在某一状态，但现在已经不再进行，这种状态已经结束。\n［句型框］主语＋动词＋过＋宾语\n［句型框］主语＋没（有）＋动词＋过＋宾语\n［句型框］主语＋动词＋过＋宾语＋吗／没有？\n② 语言点导入：\n教师可以利用图片用提问的方式导入语言点，比如故宫、胡同、汉字的图片等。\n教师：你们去过故宫吗？\n学生：我们去过故宫。\n教师：来中国以前你学过汉语吗？\n学生：我没学过汉语。\n③ 语言点操练：\n教师提问，学生用肯定式和否定式回答。\n你去过王老师家没有？\n你看过中国电影没有？\n你吃过中国菜没有？\n你听过这首歌没有？\n④ 语言点扩展练习：\n教师带领学生做课本第112页的小组活动。"}, {"title_zh": "3 语言点（2）关联词“虽然……，但是……”", "body_zh": "① 语言点解析：\n表示让步与转折关系。“虽然”多用在前一个分句中，引出表示让步的分句，后一分句常用“但是、可是”引出转折关系。\n② 语言点导入：\n教师给出情境，请学生用“虽然……，但是……”说句子。\n教师：今天天气不太好，同学们还想去踢足球。\n学生：虽然天气不太好，但是同学们还想去踢足球。\n教师：那个饭馆很小，做的菜很好吃。\n学生：虽然那个饭馆很小，但是做的菜很好吃。\n③ 语言点操练：\n让学生把下列句子填写完整。\n虽然我不会写汉字，但是________。\n虽然这件衣服很漂亮，但是________。\n虽然________，但是我没有时间。\n虽然________，但是天气不太冷。\n④ 语言点扩展练习：\n教师带领学生做课本第112页的双人活动。"}, {"title_zh": "3 语言点（3）动量补语“次”", "body_zh": "① 语言点解析：\n动量补语用在动词的后边，表示动作、行为进行的数量、次数。\n［句型框］主语＋动词＋过＋数量词＋次＋宾语\n［句型框］主语＋动词＋过＋指人的名词／人称代词＋数量词＋次\n［注意］宾语是表示地点的名词时，动量补语可以放在宾语前，也可以放在宾语后。\n② 语言点导入：\n教师做动作，让学生来说。\n听一次、写一次、读一次、看一次\n③ 语言点操练：\n请学生想想已经学过哪些动词，把这些动词加上动量补语，然后大声说出来。\n例如：来一次　去一次　看一次　……\n④ 语言点扩展练习：\n用动量补语完成下列句子。\n这本书以前我________。\n我小的时候________北京。\n这个电影不错，我已经________。\n今天上午，小王________你________，你没在。"}, {"title_zh": "4 课文", "body_zh": "课文1\n（1）让学生听两遍录音并回答下列问题：\nB看过那个电影没有？\nB听说过那个电影吗？\nA想什么时候去看电影？\nB想和谁一起去看电影？\n（2）教师领读课文两遍，然后让学生分角色朗读课文。\n（3）教师用PPT展示课文提示词，请学生再次通读一遍课文后，根据提示词复述课文。\nA：你……没有？\nB：没看过，听说……。\nA：那我们……吧？\nB：可以，但是……。\n课文2\n（1）让学生听两遍录音并回答下列问题：\n女的去过中国吗？\n女的还想去中国吗？\n男的想去中国吗？\n“到时候”是指什么时候？\n（2）教师带领学生齐读课文两遍，然后请学生分角色朗读课文。\n（3）教师用PPT展示课文提示词，请学生再次通读一遍课文后，根据提示词复述课文。\nA：听说……，还想去吗？\nB：我虽然……，但是……。\nA：那我们……吧。\nB：好啊，到时候……。\n课文3\n（1）让学生听两遍录音并回答下列问题：\n明天天气怎么样？\n谁想出去跑步？\n女的能出去跑步吗？为什么？\n（2）教师带领学生齐读课文两遍，然后请学生分角色朗读课文。\n（3）教师用PPT展示课文提示词，把学生分成两组，一组学生提问，一组学生回答。然后互换角色。\nA：明天天气……？\nB：虽然……，但是……。\nA：那还能……吗？\nB：可以，但是……，我还有……。\n（4）用女的的口气叙述本段课文的主要内容。\n明天……，虽然……，但是……，我的朋友想……，但是……。\n课文4\n（1）让学生听两遍录音并回答下列问题：\n他们在做什么呢？\n男的觉得这个商店的东西怎么样？\n女的想不想买这件衣服？\n男的觉得这件衣服贵不贵？\n（2）教师带领学生齐读课文两遍，然后请学生分角色朗读课文。\n（3）教师用PPT展示课文提示词，学生可以自己设计情景，分角色表演课文。\nA：你在这个商店……没有？\nB：买过一次，……还可以，就是……。\nA：我喜欢……，但是觉得……。\nB：……还可以，……吧。"}, {"title_zh": "5 语音", "body_zh": "感叹句的句调：\n① 知识点解析\n感叹句是用来抒发喜悦、愤怒、惊讶或悲哀等强烈感情的。一般来说，表示悲哀、难过的感叹句一般用低而趋降的句调，表示喜悦、惊讶的感叹句可以用高而平的句调。\n你唱的歌真好听啊！↘\n快点儿回房间，天气多冷啊！→\n这次的汉语考试太难了！↘\n② 语音练习\n教师可利用课本第111页的语音练习部分进行练习。教师可先领读句子，使学生掌握感叹句的句调特点，然后让学生个别读，教师纠正错误。\n练习册相关练习：第131页／三"}, {"title_zh": "6 汉字", "body_zh": "① 知识点解析：\n偏旁\n⻗：雨字头，由它构成的汉字一般与云、雨等天气现象有关系。\n贝：贝字旁，由它构成的汉字一般与钱财有关系。\n② 汉字练习：\n• 教师板书本课偏旁“斤、页”，提示学生注意这两个偏旁的笔画和笔顺，并书写各自的代表汉字，帮助学生识记该偏旁的意义。\n• 补充练习\na. 找出下列含有雨字头和贝字旁的汉字\n雪　货　财　雹\n览　雾　狈　觉\nb. 拆分下列汉字\n虽：____　____　玩：____　____\n然：____　____　意：____　____\nc. 用下列偏旁和部件组合成新汉字\n口　西　日　心　青　相　虫　女\n____　____　____　____\n练习册相关练习：第132页／四"}, {"title_zh": "7 补充课堂活动——去商店买东西", "body_zh": "请学生2-3人组成小组，自己设计在商店里的购物场景，然后进行角色扮演。可以参考下面的提示。\n人物：两个人（同学、朋友）　三个人（同学、朋友、售货员）\n地点：商店里\n东西：衣服、水果、书……\n句式：在……买过……没有？\n　……还可以。\n　虽然……，但是……有点儿贵。\n　我喜欢……，你呢？\n　再看看……吧。"}, {"title_zh": "8 本课小结", "body_zh": "• 语言点：动态助词“过”\n　关联词“虽然……，但是……”\n　动量补语“次”\n• 语音：感叹句的句调\n• 汉字：偏旁“⻗、贝”"}, {"title_zh": "附注：教学建议用具", "body_zh": "1. 生词卡片：第13、14课生词卡片\n2. 图片：故宫、北京胡同、汉字等"}], "notes_zh": ["注意：宾语是表示地点的名词时，动量补语可以放在宾语前，也可以放在宾语后。"], "warmup_answers_zh": ["热身1 答案：①D　②A　③E　④F　⑤C　⑥B", "热身2 参考答案：①电视　②电影　③电话　④电脑"], "text_questions": [{"text": 1, "q_zh": "B看过那个电影没有？"}, {"text": 1, "q_zh": "B听说过那个电影吗？"}, {"text": 1, "q_zh": "A想什么时候去看电影？"}, {"text": 1, "q_zh": "B想和谁一起去看电影？"}, {"text": 2, "q_zh": "女的去过中国吗？"}, {"text": 2, "q_zh": "女的还想去中国吗？"}, {"text": 2, "q_zh": "男的想去中国吗？"}, {"text": 2, "q_zh": "“到时候”是指什么时候？"}, {"text": 3, "q_zh": "明天天气怎么样？"}, {"text": 3, "q_zh": "谁想出去跑步？"}, {"text": 3, "q_zh": "女的能出去跑步吗？为什么？"}, {"text": 4, "q_zh": "他们在做什么呢？"}, {"text": 4, "q_zh": "男的觉得这个商店的东西怎么样？"}, {"text": 4, "q_zh": "女的想不想买这件衣服？"}, {"text": 4, "q_zh": "男的觉得这件衣服贵不贵？"}], "summary_zh": "• 语言点：动态助词“过”\n　关联词“虽然……，但是……”\n　动量补语“次”\n• 语音：感叹句的句调\n• 汉字：偏旁“⻗、贝”"}, "workbook": {"ref": {"book": "workbook", "pages": [132, 133, 134, 135, 136, 137, 138, 139, 140]}, "sections": [{"n": "一、听力 第一部分", "type_zh": "听力 第一部分", "instruction_zh": "第1–5题：听句子，判断对错", "instruction_en": "Questions 1-5: Decide whether the pictures are right or wrong based on the sentences you hear.", "items": [{"n": "例1", "zh": "我们家有三个人。", "pinyin": "Wǒmen jiā yǒu sān ge rén.", "transcript_zh": "我们家有三个人。", "picture_desc_en": "a smiling family outdoors: a man carrying a child on his shoulders and a woman", "answer": "√", "answer_ref": {"book": "workbook", "pages": [132]}}, {"n": "例2", "zh": "我每天坐公共汽车去上班。", "pinyin": "Wǒ měi tiān zuò gōnggòngqìchē qù shàng bān.", "transcript_zh": "我每天坐公共汽车去上班。", "picture_desc_en": "a mountain bicycle", "answer": "×", "answer_ref": {"book": "workbook", "pages": [132]}}, {"n": 1, "zh": "", "transcript_zh": "下个星期我要和女朋友去看一次电影。", "picture_desc_en": "a young man and a young woman sitting close together at a table, the man writing, both smiling", "answer": "×", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": 2, "zh": "", "transcript_zh": "虽然工作很忙，但是我每天都游泳。", "picture_desc_en": "a swimmer in a white cap doing the front crawl in a pool", "answer": "√", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": 3, "zh": "", "transcript_zh": "你自己去跑步吧，我还有事情要做呢。", "picture_desc_en": "a man and a woman in sunglasses and sportswear outdoors, smiling", "answer": "×", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": 4, "zh": "", "transcript_zh": "这本书我看过很多次了，真的很有意思。", "picture_desc_en": "a smiling young woman holding an open book, library bookshelves behind her", "answer": "√", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": 5, "zh": "", "transcript_zh": "长时间玩电脑对眼睛不好，但是儿子非常喜欢。", "picture_desc_en": "a boy sitting at an open laptop, smiling", "answer": "√", "answer_ref": {"book": "teacher", "pages": [142]}}]}, {"n": "一、听力 第二部分", "type_zh": "听力 第二部分", "instruction_zh": "第6–10题：听对话，选择与对话内容一致的图片", "instruction_en": "Questions 6-10: Choose the right picture for each dialogue you hear.", "items": [{"n": "例", "zh": "男：你喜欢什么运动？ Nǐ xǐhuan shénme yùndòng? (What sport do you like?) 女：我最喜欢踢足球。 Wǒ zuì xǐhuan tī zúqiú. (My favorite sport is playing football.)", "transcript_zh": "男：你喜欢什么运动？ 女：我最喜欢踢足球。", "options": {"A": "[picture] a smiling man at a table with food (bowl, fruit), eating a meal", "B": "[picture] a young woman holding her head in both hands over papers on a desk", "C": "[picture] a smiling young woman holding up a bank card, a clothes rack with hangers in front of her", "D": "[picture] a young woman juggling a football on her knee on a field", "E": "[picture] a man and a girl looking at a tablet together, handholds of a bus/train overhead", "F": "[picture] basketball players jumping at the hoop, seen from above"}, "answer": "D", "answer_ref": {"book": "workbook", "pages": [133]}}, {"n": 6, "zh": "", "options": {"A": "[picture] a smiling man at a table with food (bowl, fruit), eating a meal", "B": "[picture] a young woman holding her head in both hands over papers on a desk", "C": "[picture] a smiling young woman holding up a bank card, a clothes rack with hangers in front of her", "D": "[picture] a young woman juggling a football on her knee on a field", "E": "[picture] a man and a girl looking at a tablet together, handholds of a bus/train overhead", "F": "[picture] basketball players jumping at the hoop, seen from above"}, "transcript_zh": "女：爸爸，您看过这个电影吗？我同学说很有意思。 男：没看过，下星期我们一起去看吧。", "answer": "E", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": 7, "zh": "", "options": {"A": "[picture] a smiling man at a table with food (bowl, fruit), eating a meal", "B": "[picture] a young woman holding her head in both hands over papers on a desk", "C": "[picture] a smiling young woman holding up a bank card, a clothes rack with hangers in front of her", "D": "[picture] a young woman juggling a football on her knee on a field", "E": "[picture] a man and a girl looking at a tablet together, handholds of a bus/train overhead", "F": "[picture] basketball players jumping at the hoop, seen from above"}, "transcript_zh": "女：虽然是晴天，但是天气很冷。 男：没关系，我还要和同学们一起打篮球呢。", "answer": "F", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": 8, "zh": "", "options": {"A": "[picture] a smiling man at a table with food (bowl, fruit), eating a meal", "B": "[picture] a young woman holding her head in both hands over papers on a desk", "C": "[picture] a smiling young woman holding up a bank card, a clothes rack with hangers in front of her", "D": "[picture] a young woman juggling a football on her knee on a field", "E": "[picture] a man and a girl looking at a tablet together, handholds of a bus/train overhead", "F": "[picture] basketball players jumping at the hoop, seen from above"}, "transcript_zh": "男：一起吃早饭吧。 女：我已经吃过了，你自己吃吧。", "answer": "A", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": 9, "zh": "", "options": {"A": "[picture] a smiling man at a table with food (bowl, fruit), eating a meal", "B": "[picture] a young woman holding her head in both hands over papers on a desk", "C": "[picture] a smiling young woman holding up a bank card, a clothes rack with hangers in front of her", "D": "[picture] a young woman juggling a football on her knee on a field", "E": "[picture] a man and a girl looking at a tablet together, handholds of a bus/train overhead", "F": "[picture] basketball players jumping at the hoop, seen from above"}, "transcript_zh": "男：这次考试怎么样？ 女：别说了，很多学过的汉字我都不会写了。", "answer": "B", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": 10, "zh": "", "options": {"A": "[picture] a smiling man at a table with food (bowl, fruit), eating a meal", "B": "[picture] a young woman holding her head in both hands over papers on a desk", "C": "[picture] a smiling young woman holding up a bank card, a clothes rack with hangers in front of her", "D": "[picture] a young woman juggling a football on her knee on a field", "E": "[picture] a man and a girl looking at a tablet together, handholds of a bus/train overhead", "F": "[picture] basketball players jumping at the hoop, seen from above"}, "transcript_zh": "男：别买衣服了，我没有那么多钱。 女：没关系，我这儿有钱。", "answer": "C", "answer_ref": {"book": "teacher", "pages": [142]}}]}, {"n": "一、听力 第三部分", "type_zh": "听力 第三部分", "instruction_zh": "第11–15题：听对话，选择正确答案", "instruction_en": "Questions 11-15: Listen to the dialogues and answer the questions.", "items": [{"n": "例", "zh": "问：小王的杯子是什么颜色的？", "pinyin": "Xiǎo Wáng de bēizi shì shénme yánsè de?", "transcript_zh": "男：小王，这里有几个杯子，哪个是你的？ 女：左边那个红色的是我的。 问：小王的杯子是什么颜色的？", "options": {"A": "红色 hóngsè red", "B": "黑色 hēisè black", "C": "白色 báisè white"}, "answer": "A", "answer_ref": {"book": "workbook", "pages": [134]}}, {"n": 11, "zh": "", "transcript_zh": "男：您是第一次来我们这儿吗？ 女：不是，去年九月我来过一次。 问：女的来过这里几次？", "options": {"A": "一次 yí cì", "B": "两次 liǎng cì", "C": "三次 sān cì"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": 12, "zh": "", "transcript_zh": "男：你在这个商店买过东西没有？ 女：买过一次，这儿的东西还可以，就是不便宜。 问：女的是什么意思？", "options": {"A": "东西好，便宜 dōngxi hǎo, piányi", "B": "东西不好，便宜 dōngxi bù hǎo, piányi", "C": "东西好，不便宜 dōngxi hǎo, bù piányi"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": 13, "zh": "", "transcript_zh": "女：明天一起去跑步吧。 男：你自己去吧，我还有很多工作要做呢。 问：男的为什么不去跑步？", "options": {"A": "太忙 tài máng", "B": "太累 tài lèi", "C": "不喜欢跑步 bù xǐhuan pǎo bù"}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": 14, "zh": "", "transcript_zh": "男：今天的报纸你看过了没有？ 女：没有，我在看昨天的报纸呢。 问：女的看的是哪天的报纸？", "options": {"A": "前天的 qiántiān de", "B": "今天的 jīntiān de", "C": "昨天的 zuótiān de"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": 15, "zh": "", "transcript_zh": "女：这件衣服不错，就是有点儿贵。 男：两百多块还可以，喜欢就买吧。 问：男的想让女的买这件衣服吗？", "options": {"A": "不想让女的买 bù xiǎng ràng nǚ de mǎi", "B": "想让女的买 xiǎng ràng nǚ de mǎi", "C": "两百多块太贵了 liǎng bǎi duō kuài tài guì le"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [142]}}]}, {"n": "二、阅读 第一部分", "type_zh": "阅读 第一部分", "instruction_zh": "第16–20题：看图片，选择与句子内容一致的图片", "instruction_en": "Questions 16-20: Choose the right picture for each sentence.", "items": [{"n": "例", "zh": "每个星期六，我都去打篮球。", "pinyin": "Měi ge xīngqīliù, wǒ dōu qù dǎ lánqiú.", "options": {"A": "[picture] a smiling girl in a knitted winter hat and scarf, a snowman behind her", "B": "[picture] a smiling young woman standing at a whiteboard with Chinese sentences written on it, holding a marker", "C": "[picture] the Great Wall winding over hills", "D": "[picture] a smiling young man holding a basketball above his head", "E": "[picture] a young woman with a hand on her forehead, holding a tissue to her nose", "F": "[picture] a smiling woman holding a closed umbrella outdoors, looking up at the sky"}, "answer": "D", "answer_ref": {"book": "workbook", "pages": [135]}}, {"n": 16, "zh": "长城很漂亮，我已经去过三次了。", "pinyin": "Chángchéng hěn piàoliang, wǒ yǐjīng qùguo sān cì le.", "options": {"A": "[picture] a smiling girl in a knitted winter hat and scarf, a snowman behind her", "B": "[picture] a smiling young woman standing at a whiteboard with Chinese sentences written on it, holding a marker", "C": "[picture] the Great Wall winding over hills", "D": "[picture] a smiling young man holding a basketball above his head", "E": "[picture] a young woman with a hand on her forehead, holding a tissue to her nose", "F": "[picture] a smiling woman holding a closed umbrella outdoors, looking up at the sky"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": 17, "zh": "来中国以后，我已经得过两次病了。", "pinyin": "Lái Zhōngguó yǐhòu, wǒ yǐjīng déguo liǎng cì bìng le.", "options": {"A": "[picture] a smiling girl in a knitted winter hat and scarf, a snowman behind her", "B": "[picture] a smiling young woman standing at a whiteboard with Chinese sentences written on it, holding a marker", "C": "[picture] the Great Wall winding over hills", "D": "[picture] a smiling young man holding a basketball above his head", "E": "[picture] a young woman with a hand on her forehead, holding a tissue to her nose", "F": "[picture] a smiling woman holding a closed umbrella outdoors, looking up at the sky"}, "answer": "E", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": 18, "zh": "虽然是晴天，但是很冷。", "pinyin": "Suīrán shì qíngtiān, dànshì hěn lěng.", "options": {"A": "[picture] a smiling girl in a knitted winter hat and scarf, a snowman behind her", "B": "[picture] a smiling young woman standing at a whiteboard with Chinese sentences written on it, holding a marker", "C": "[picture] the Great Wall winding over hills", "D": "[picture] a smiling young man holding a basketball above his head", "E": "[picture] a young woman with a hand on her forehead, holding a tissue to her nose", "F": "[picture] a smiling woman holding a closed umbrella outdoors, looking up at the sky"}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": 19, "zh": "不下雨了，天晴了。", "pinyin": "Bú xià yǔ le, tiān qíng le.", "options": {"A": "[picture] a smiling girl in a knitted winter hat and scarf, a snowman behind her", "B": "[picture] a smiling young woman standing at a whiteboard with Chinese sentences written on it, holding a marker", "C": "[picture] the Great Wall winding over hills", "D": "[picture] a smiling young man holding a basketball above his head", "E": "[picture] a young woman with a hand on her forehead, holding a tissue to her nose", "F": "[picture] a smiling woman holding a closed umbrella outdoors, looking up at the sky"}, "answer": "F", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": 20, "zh": "我们已经学过这个汉字了。", "pinyin": "Wǒmen yǐjīng xuéguo zhège Hànzì le.", "options": {"A": "[picture] a smiling girl in a knitted winter hat and scarf, a snowman behind her", "B": "[picture] a smiling young woman standing at a whiteboard with Chinese sentences written on it, holding a marker", "C": "[picture] the Great Wall winding over hills", "D": "[picture] a smiling young man holding a basketball above his head", "E": "[picture] a young woman with a hand on her forehead, holding a tissue to her nose", "F": "[picture] a smiling woman holding a closed umbrella outdoors, looking up at the sky"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [142]}}]}, {"n": "二、阅读 第二部分", "type_zh": "阅读 第二部分", "instruction_zh": "第21–25题：选择合适的词语填空", "instruction_en": "Questions 21-25: Choose the proper words to fill in the brackets.", "word_bank": [["A 有意思 yǒu yìsi", "B 但是 dànshì", "C 意思 yìsi", "D 过 guò", "E 贵 guì", "F 听说 tīngshuō"]], "items": [{"n": "例", "zh": "这儿的羊肉很好吃，但是也很（________）。", "pinyin": "Zhèr de yángròu hěn hǎochī, dànshì yě hěn ______.", "answer": "E", "answer_ref": {"book": "workbook", "pages": [136]}}, {"n": 21, "zh": "老师的话是什么（________），我没听懂。", "pinyin": "Lǎoshī de huà shì shénme ______, wǒ méi tīngdǒng.", "answer": "C", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": 22, "zh": "我（________）这本书非常好看，但是我还没看过。", "pinyin": "Wǒ ______ zhè běn shū fēicháng hǎo kàn, dànshì wǒ hái méi kànguo.", "answer": "F", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": 23, "zh": "那个电影太（________）了，我已经看过两次了。", "pinyin": "Nàge diànyǐng tài ______ le, wǒ yǐjīng kànguo liǎng cì le.", "answer": "A", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": 24, "zh": "虽然工作很忙，（________）我每个星期都要运动。", "pinyin": "Suīrán gōngzuò hěn máng, ______ wǒ měi ge xīngqī dōu yào yùndòng.", "answer": "B", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": 25, "zh": "我已经去（________）北京好几次了，但是还想再去玩儿玩儿。", "pinyin": "Wǒ yǐjīng qù ______ Běijīng hǎo jǐ cì le, dànshì hái xiǎng zài qù wánrwanr.", "answer": "D", "answer_ref": {"book": "teacher", "pages": [142]}}]}, {"n": "二、阅读 第三部分", "type_zh": "阅读 第三部分", "instruction_zh": "第26–30题：判断下列句子的意思是否正确", "instruction_en": "Questions 26-30: Decide whether the inferences are true or false.", "items": [{"n": "例1", "zh": "现在是11点30分，他们已经游了20分钟了。 ★他们11点10分开始游泳。", "pinyin": "Xiànzài shì diǎn fēn, tāmen yǐjīng yóule fēnzhōng le. ★Tāmen diǎn fēn kāishǐ yóuyǒng.", "answer": "√", "answer_ref": {"book": "workbook", "pages": [137]}}, {"n": "例2", "zh": "我会跳舞，但跳得不怎么样。 ★我跳得非常好。", "pinyin": "Wǒ huì tiàowǔ, dàn tiào de bù zěnmeyàng. ★Wǒ tiào de fēicháng hǎo.", "answer": "×", "answer_ref": {"book": "workbook", "pages": [137]}}, {"n": 26, "zh": "昨天和朋友们在外面玩儿了一个晚上，很累，但是非常高兴。 ★昨天玩儿得不好。", "pinyin": "Zuótiān hé péngyoumen zài wàimian wánrle yí ge wǎnshang, hěn lèi, dànshì fēicháng gāoxìng. ★Zuótiān wánr de bù hǎo.", "answer": "×", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": 27, "zh": "他做的菜比我做的好吃，但是因为工作忙，他很少做。 ★他不会做菜。", "pinyin": "Tā zuò de cài bǐ wǒ zuò de hǎochī, dànshì yīnwèi gōngzuò máng, tā hěn shǎo zuò. ★Tā bú huì zuò cài.", "answer": "×", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": 28, "zh": "我和朋友们去过这家商店，还在这儿买过两次东西。 ★这个商店他去过两次。", "pinyin": "Wǒ hé péngyoumen qùguo zhè jiā shāngdiàn, hái zài zhèr mǎiguo liǎng cì dōngxi. ★Zhège shāngdiàn tā qùguo liǎng cì.", "answer": "×", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": 29, "zh": "从学校到机场，坐出租车要一个小时，我们10点的飞机，8点从学校走可以吗？ ★他们要坐8点的飞机。", "pinyin": "Cóng xuéxiào dào jīchǎng, zuò chūzūchē yào yí ge xiǎoshí, wǒmen diǎn de fēijī, diǎn cóng xuéxiào zǒu kěyǐ ma? ★Tāmen yào zuò diǎn de fēijī.", "answer": "×", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": 30, "zh": "小李说这个电影很有意思，但是我没看过。 ★小李看过这个电影。", "pinyin": "Xiǎo Lǐ shuō zhège diànyǐng hěn yǒu yìsi, dànshì wǒ méi kànguo. ★Xiǎo Lǐ kànguo zhège diànyǐng.", "answer": "√", "answer_ref": {"book": "teacher", "pages": [142]}}]}, {"n": "二、阅读 第四部分", "type_zh": "阅读 第四部分", "instruction_zh": "第31–35题：选择合适的问答", "instruction_en": "Questions 31-35: Match the sentences to make dialogues.", "items": [{"n": "例", "zh": "他还在教室里学习。 (He is still studying in the classroom.)", "pinyin": "Tā hái zài jiàoshì li xuéxí.", "options": {"A": "你出去的时候多穿些衣服。 Nǐ chūqu de shíhou duō chuān xiē yīfu.", "B": "你在那个商店买过东西没有？ Nǐ zài nàge shāngdiàn mǎiguo dōngxi méiyǒu?", "C": "妈妈告诉过我很多次，长时间玩儿电脑和手机对眼睛不好。 Māma gàosu guo wǒ hěn duō cì, cháng shíjiān wánr diànnǎo hé shǒujī duì yǎnjing bù hǎo.", "D": "没学过，听说很难，但是很有意思。 Méi xuéguo, tīngshuō hěn nán, dànshì hěn yǒu yìsi.", "E": "他在哪儿呢？你看见他了吗？ Tā zài nǎr ne? Nǐ kànjiàn tā le ma?", "F": "没关系，喜欢就买吧。 Méi guānxi, xǐhuan jiù mǎi ba."}, "answer": "E", "answer_ref": {"book": "workbook", "pages": [138]}}, {"n": 31, "zh": "你学过汉语吗？", "pinyin": "Nǐ xuéguo Hànyǔ ma?", "options": {"A": "你出去的时候多穿些衣服。 Nǐ chūqu de shíhou duō chuān xiē yīfu.", "B": "你在那个商店买过东西没有？ Nǐ zài nàge shāngdiàn mǎiguo dōngxi méiyǒu?", "C": "妈妈告诉过我很多次，长时间玩儿电脑和手机对眼睛不好。 Māma gàosu guo wǒ hěn duō cì, cháng shíjiān wánr diànnǎo hé shǒujī duì yǎnjing bù hǎo.", "D": "没学过，听说很难，但是很有意思。 Méi xuéguo, tīngshuō hěn nán, dànshì hěn yǒu yìsi.", "E": "他在哪儿呢？你看见他了吗？ Tā zài nǎr ne? Nǐ kànjiàn tā le ma?", "F": "没关系，喜欢就买吧。 Méi guānxi, xǐhuan jiù mǎi ba."}, "answer": "D", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": 32, "zh": "今天真冷，第一次到了零下10度。", "pinyin": "Jīntiān zhēn lěng, dì yī cì dàole língxià dù.", "options": {"A": "你出去的时候多穿些衣服。 Nǐ chūqu de shíhou duō chuān xiē yīfu.", "B": "你在那个商店买过东西没有？ Nǐ zài nàge shāngdiàn mǎiguo dōngxi méiyǒu?", "C": "妈妈告诉过我很多次，长时间玩儿电脑和手机对眼睛不好。 Māma gàosu guo wǒ hěn duō cì, cháng shíjiān wánr diànnǎo hé shǒujī duì yǎnjing bù hǎo.", "D": "没学过，听说很难，但是很有意思。 Méi xuéguo, tīngshuō hěn nán, dànshì hěn yǒu yìsi.", "E": "他在哪儿呢？你看见他了吗？ Tā zài nǎr ne? Nǐ kànjiàn tā le ma?", "F": "没关系，喜欢就买吧。 Méi guānxi, xǐhuan jiù mǎi ba."}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": 33, "zh": "所以我现在很少玩儿电脑和手机了。", "pinyin": "Suǒyǐ wǒ xiànzài hěn shǎo wánr diànnǎo hé shǒujī le.", "options": {"A": "你出去的时候多穿些衣服。 Nǐ chūqu de shíhou duō chuān xiē yīfu.", "B": "你在那个商店买过东西没有？ Nǐ zài nàge shāngdiàn mǎiguo dōngxi méiyǒu?", "C": "妈妈告诉过我很多次，长时间玩儿电脑和手机对眼睛不好。 Māma gàosu guo wǒ hěn duō cì, cháng shíjiān wánr diànnǎo hé shǒujī duì yǎnjing bù hǎo.", "D": "没学过，听说很难，但是很有意思。 Méi xuéguo, tīngshuō hěn nán, dànshì hěn yǒu yìsi.", "E": "他在哪儿呢？你看见他了吗？ Tā zài nǎr ne? Nǐ kànjiàn tā le ma?", "F": "没关系，喜欢就买吧。 Méi guānxi, xǐhuan jiù mǎi ba."}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": 34, "zh": "我很喜欢这件衣服，但是觉得有点儿贵。", "pinyin": "Wǒ hěn xǐhuan zhè jiàn yīfu, dànshì juéde yǒudiǎnr guì.", "options": {"A": "你出去的时候多穿些衣服。 Nǐ chūqu de shíhou duō chuān xiē yīfu.", "B": "你在那个商店买过东西没有？ Nǐ zài nàge shāngdiàn mǎiguo dōngxi méiyǒu?", "C": "妈妈告诉过我很多次，长时间玩儿电脑和手机对眼睛不好。 Māma gàosu guo wǒ hěn duō cì, cháng shíjiān wánr diànnǎo hé shǒujī duì yǎnjing bù hǎo.", "D": "没学过，听说很难，但是很有意思。 Méi xuéguo, tīngshuō hěn nán, dànshì hěn yǒu yìsi.", "E": "他在哪儿呢？你看见他了吗？ Tā zài nǎr ne? Nǐ kànjiàn tā le ma?", "F": "没关系，喜欢就买吧。 Méi guānxi, xǐhuan jiù mǎi ba."}, "answer": "F", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": 35, "zh": "东西还可以，而且很便宜。", "pinyin": "Dōngxi hái kěyǐ, érqiě hěn piányi.", "options": {"A": "你出去的时候多穿些衣服。 Nǐ chūqu de shíhou duō chuān xiē yīfu.", "B": "你在那个商店买过东西没有？ Nǐ zài nàge shāngdiàn mǎiguo dōngxi méiyǒu?", "C": "妈妈告诉过我很多次，长时间玩儿电脑和手机对眼睛不好。 Māma gàosu guo wǒ hěn duō cì, cháng shíjiān wánr diànnǎo hé shǒujī duì yǎnjing bù hǎo.", "D": "没学过，听说很难，但是很有意思。 Méi xuéguo, tīngshuō hěn nán, dànshì hěn yǒu yìsi.", "E": "他在哪儿呢？你看见他了吗？ Tā zài nǎr ne? Nǐ kànjiàn tā le ma?", "F": "没关系，喜欢就买吧。 Méi guānxi, xǐhuan jiù mǎi ba."}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [142]}}]}, {"n": "三、语音 第一部分", "type_zh": "语音 第一部分 听录音", "instruction_zh": "第1题：听录音，注意句末的升降调", "instruction_en": "Question 1: Listen to the recording and pay attention to the intonation at the end of each sentence.", "items": [{"n": "1-(1)", "zh": "今天天气真好啊！↘", "pinyin": "Jīntiān tiānqì zhēn hǎo a!", "transcript_zh": "今天天气真好啊！"}, {"n": "1-(2)", "zh": "他的汉字写得比我好多了！↘", "pinyin": "Tā de Hànzì xiě de bǐ wǒ hǎo duō le!", "transcript_zh": "他的汉字写得比我好多了！"}, {"n": "1-(3)", "zh": "这么大的一个苹果呀！↘", "pinyin": "Zhème dà de yí ge píngguǒ ya!", "transcript_zh": "这么大的一个苹果呀！"}, {"n": "1-(4)", "zh": "你的汉语说得多好啊！↘", "pinyin": "Nǐ de Hànyǔ shuō de duō hǎo a!", "transcript_zh": "你的汉语说得多好啊！"}]}, {"n": "三、语音 第二部分", "type_zh": "语音 第二部分 跟读", "instruction_zh": "第2题：听录音并跟读下列句子，注意句末的升降调", "instruction_en": "Question 2: Listen to the recording and repeat the following sentences, paying attention to the intonation at the end of each sentence.", "items": [{"n": "2-(1)", "zh": "我觉得中国真大呀！↘", "pinyin": "Wǒ juéde Zhōngguó zhēn dà ya!", "transcript_zh": "我觉得中国真大呀！"}, {"n": "2-(2)", "zh": "昨天是星期天，商店的人好多呀！↘", "pinyin": "Zuótiān shì xīngqītiān, shāngdiàn de rén hǎo duō ya!", "transcript_zh": "昨天是星期天，商店的人好多呀！"}, {"n": "2-(3)", "zh": "她的眼睛多漂亮啊！↘", "pinyin": "Tā de yǎnjing duō piàoliang a!", "transcript_zh": "她的眼睛多漂亮啊！"}, {"n": "2-(4)", "zh": "希望你的身体快点儿好啊！↘", "pinyin": "Xīwàng nǐ de shēntǐ kuàidiǎnr hǎo a!", "transcript_zh": "希望你的身体快点儿好啊！"}]}, {"n": "四、汉字 第一部分", "type_zh": "汉字 偏旁归类", "instruction_zh": "第1–2题：看汉字，按偏旁归类", "instruction_en": "Questions 1-2: Group the characters with the same radical.", "word_bank": [["A 雪", "B 赔", "C 雷", "D 员"], ["E 货", "F 霜", "G 零", "H 账"]], "items": [{"n": 1, "zh": "⻗：________", "answer": "A C F G", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": 2, "zh": "贝：________", "answer": "B D E H", "answer_ref": {"book": "teacher", "pages": [142]}}]}, {"n": "四、汉字 第二部分", "type_zh": "汉字 猜词义", "instruction_zh": "第3题：看生词和图片，猜出词义", "instruction_en": "Question 3: Guess the meaning of each word based on the new words and pictures.", "word_bank": [["商品", "商人", "商店", "顾客"]], "items": [{"n": "3-商品", "zh": "商品 ________", "options": {"A": "[picture] a tall department-store building with a sign on the roof", "B": "[picture] many teddy bears displayed together for sale", "C": "[picture] a man and a woman in business suits standing back to back, fists raised", "D": "[picture] three smiling young women carrying shopping bags"}, "answer": "B", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": "3-商人", "zh": "商人 ________", "options": {"A": "[picture] a tall department-store building with a sign on the roof", "B": "[picture] many teddy bears displayed together for sale", "C": "[picture] a man and a woman in business suits standing back to back, fists raised", "D": "[picture] three smiling young women carrying shopping bags"}, "answer": "C", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": "3-商店", "zh": "商店 ________", "options": {"A": "[picture] a tall department-store building with a sign on the roof", "B": "[picture] many teddy bears displayed together for sale", "C": "[picture] a man and a woman in business suits standing back to back, fists raised", "D": "[picture] three smiling young women carrying shopping bags"}, "answer": "A", "answer_ref": {"book": "teacher", "pages": [142]}}, {"n": "3-顾客", "zh": "顾客 ________", "options": {"A": "[picture] a tall department-store building with a sign on the roof", "B": "[picture] many teddy bears displayed together for sale", "C": "[picture] a man and a woman in business suits standing back to back, fists raised", "D": "[picture] three smiling young women carrying shopping bags"}, "answer": "D", "answer_ref": {"book": "teacher", "pages": [142]}}]}], "answers_ref": {"book": "teacher", "pages": [141, 142]}}, "unclear": ["Гарчиг зөрүү: сурах бичиг (PDF х.125) ба багшийн ном (PDF х.101) «你看过那个电影吗 / Nǐ kànguo nàge diànyǐng ma», харин дасгалын ном (PDF х.132) ба багшийн номын хавсралт (PDF х.141) «你看过这个电影吗 / Nǐ kànguo zhège diànyǐng ma». Англи гарчиг хоёуланд «Have you seen that movie». title_zh-д сурах бичгийнхийг авсан.", "«过»-ийн нэр томьёо: сурах бичгийн 注释1 (PDF х.128) ба 运用 小组活动 (PDF х.132) «结构助词“过” / The Structural Particle», багшийн ном (PDF х.101, 103, 107) «动态助词“过”» — номд байгаагаар тус тусад нь.", "生词 1 «有意思 yǒu yìsi» — сурах бичиг PDF х.126-д үгийн ай (pos) хэвлэгдээгүй тул pos талбаргүй.", "Багшийн ном PDF х.106 汉字练习 — «教师板书本课偏旁“斤、页”» гэж хэвлэгдсэн (эхний тэмдэгт «斤»-тэй төстэй, бүрэн тод биш) — энэ хичээлийн偏旁 «⻗、贝»-тэй таарахгүй, өөр хичээлээс үлдсэн алдаа байж магадгүй; харагдсанаар бичсэн.", "偏旁 «雨字头» сурах бичиг, багшийн ном, дасгалын номд тусгай дээд хэлбэрээр хэвлэгдсэн — JSON-д Unicode «⻗» (U+2ED7) гэж бичсэн (L01 «⺩», «⻊» зэрэгтэй адил).", "贝-ийн тайлбар: сурах бичиг «一般与钱财、鼎类器物有关系», багшийн ном PDF х.106 «一般与钱财有关系» — номд байгаагаар.", "Багшийн номын 汉字 补充练习 a-д «雹»-ийн байрлалд хэвлэгдсэн тэмдэгт скан дээр «雹» мэт (дээр нь ⻗, доор нь 包) — 300dpi-д шалгасан. «狈» ч мөн адил. a/b/c-ийн хариулт хэвлэгдээгүй.", "Хүйсийн зөрүү: сурах бичгийн 课文 мөрүүд зөвхөн A/B. Сурах бичгийн 练习2 (5) «女的觉得这个商店的东西怎么样？» (课文4), харин багшийн ном PDF х.105 课文4 «男的觉得这个商店的东西怎么样？», «女的想不想买这件衣服？», «男的觉得这件衣服贵不贵？» — B-г хэн гэж үзсэн нь хоёр номд зөрж байна. 课文2-т багшийн ном «女的去过中国吗？» (去过 гэж хэлсэн нь B), 课文3-т «女的能出去跑步吗？», сурах бичгийн 练习2 (4) «为什么她明天不能去跑步？» — номд байгаагаар.", "Багшийн номын 语音 жишээнүүдийн сум (PDF х.106): 1 ба 3-т «↘», 2-т «→» (高而平). Сурах бичиг (PDF х.131) ба дасгалын ном (PDF х.139)-д бүх өгүүлбэрийн төгсгөлд доош муруй сум — JSON-д «↘» гэж тэмдэглэсэн (номд текстээр байхгүй). Энэ хичээлд 重读 цэг тэмдэглэгээ байхгүй.", "Дасгалын номын 三、语音 (PDF х.139) 1-(2): ханз «他的汉字写得比我好多了！», пиньинь «bǐ wǒ hǎo duō le» — номд байгаагаар.", "Дасгалын номын пиньинь мөрөнд тоо орхигдсон: 阅读 第三部分 例1 (11, 30, 20, 11, 10), 29 (10, 8, 8), 第四部分 32 («língxià dù», 10 орхигдсон) — номд байгаагаар.", "Дасгалын номын 听力 бичвэр (transcript_zh) ба бүх хариулт — багшийн номын хавсралт PDF х.141–142 («参考答案» PDF х.142); 例-ийн хариулт дасгалын номд өөрт нь хэвлэгдсэн. 三、语音 хэсэгт хариулт шаардлагагүй.", "Дасгалын номын 听力 第一部分 1-ийн хариулт «×» (бичвэр «下个星期我要和女朋友去看一次电影。», зураг: ширээнд хамт суусан залуу эрэгтэй, эмэгтэй) — зургийн агуулгаас хамаарах тул номд байгаагаар.", "Багшийн номын «练习册相关练习» хуудас нь хэвлэсэн дугаараар (124, 127–128, 131, 132) = PDF х.132, 135–136, 139, 140. «课本第111/112页» = PDF х.131/132.", "Сурах бичгийн 热身2 / 练习2 回答问题 / 练习3 描述图片 / 运用 — хариулт хэвлэгдээгүй. 热身1-ийн хариулт ба 热身2-ийн 参考答案 зөвхөн багшийн номд (PDF х.102).", "Сурах бичгийн 注释 хүснэгтүүдийн улаан мөрүүд — 课文-ээс авсан өгүүлбэрүүд: «你看过那个电影没有？» (注释1), «虽然是晴天，但是很冷。» (注释2 (3)), «我（在这个商店）买过一次（东西）。» (注释3; 课文4-т «买过一次» гэж 东西-гүй). structure_rows ба examples-д энгийнээр оруулсан.", "Аудио файлын нэр мэдэгдэхгүй тул audio талбар орхисон. Номын CD тэмдэг: сурах бичиг 课文1–4 = 14-1…14-4, 语音 14-5; дасгалын ном 听力 14-1, 语音 14-2.", "Энэ хичээлд 课堂用语 / 文化 / 俗语 хэсэг байхгүй; 汉字 хэсэгт зөвхөн 偏旁 (笔画/独体字 байхгүй).", "Зургийн тайлбарууд (picture_desc_en, pictures_desc_en, options «[picture]») зургаас товч, объектив дүрсэлсэн."], "verified_pages": [101, 102, 103, 104, 105, 106, 107, 125, 126, 127, 128, 129, 130, 131, 132, 133, 134, 135, 136, 137, 138, 139, 140, 141, 142], "schema_version": 1}'::jsonb, 1, 'image_verified')
on conflict (id) do update set book=excluded.book, title_zh=excluded.title_zh, title_pinyin=excluded.title_pinyin, title_en=excluded.title_en, payload=excluded.payload, schema_version=excluded.schema_version, status=excluded.status;
